from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from datetime import datetime, timedelta
import random
import uuid
import hashlib

app = FastAPI()

users = {}
tokens = {}
orders = {}
order_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class OrderCreate(BaseModel):
    pickup: str
    delivery: str
    courier: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return str(uuid.uuid4())

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = {"password": hash_password(req.password)}
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.get("/orders")
def get_orders(authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    return {
        "orders": [
            {
                "id": oid,
                "status": order["status"],
                "estimated_delivery": order["estimated_delivery"],
                "courier_location": order["courier_location"]
            }
            for oid, order in orders.items()
        ]
    }

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    order = orders[order_id]
    return {
        "id": order_id,
        "status": order["status"],
        "estimated_delivery": order["estimated_delivery"],
        "courier_location": order["courier_location"]
    }

@app.post("/orders")
def create_order(req: OrderCreate, authorization: str = Header(None)):
    global order_id_counter
    user = get_user_from_token(authorization)
    order_id = order_id_counter
    order_id_counter += 1
    orders[order_id] = {
        "pickup": req.pickup,
        "delivery": req.delivery,
        "courier": req.courier,
        "status": "pending",
        "estimated_delivery": (datetime.now() + timedelta(hours=random.randint(1, 4))).isoformat(),
        "courier_location": {"lat": random.uniform(40.0, 41.0), "lng": random.uniform(-74.0, -73.0)}
    }
    return {"id": order_id, "message": "Order created"}

