            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/promote/{user_id}")
def promote_user(user_id: int, authorization: Optional[str] = Header(None)):
    admin_id = get_current_user(authorization)
    admin = users.get(admin_id)
    if not admin or not admin.get("admin"):
        raise HTTPException(status_code=403, detail="Only admins can promote")
    target = users.get(user_id)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    target["partner"] = True
    partners.add(user_id)
    return {"message": f"User {user_id} promoted to partner"}

@app.get("/{resource}/{resource_id}")
