    if resource == "users":
        item = users.get(resource_id)
    elif resource == "videos":
        item = videos.get(resource_id)
    elif resource == "promotions":
        item = promotions.get(resource_id)
    else:
        raise HTTPException(status_code=404, detail="Resource not found")
    if not item:
        raise HTTPException(status_code=404, detail="Not found")
    return item

@app.post("/{resource}")
def create_resource(resource: str, name: str, authorization: Optional[str] = Header(None)):
    global id_counter
    user_id = get_current_user(authorization)
    if resource == "videos":
        id_counter["videos"] += 1
        vid = id_counter["videos"]
        videos[vid] = {"id": vid, "name": name, "user_id": user_id}
        return videos[vid]
