def seed():
    # Create admin user
    users[1] = {"id": 1, "email": "admin@test.com", "password": "admin123"}
    resource_counters["users"] = 1

    # Create some available slots for today
    now = datetime.now()
    for i in range(8):
        slot_id = i + 1
        start = now.replace(hour=9 + i, minute=0, second=0, microsecond=0)
        end = start + timedelta(hours=1)
        available_slots[slot_id] = {
            "id": slot_id,
            "start": start.isoformat(),
            "end": end.isoformat(),
            "available": True
        }
        resource_counters["available_slots"] = slot_id

    # Create a booked appointment
    appointments[1] = {
        "id": 1,
        "user_id": 1,
        "start": now.replace(hour=10, minute=0, second=0, microsecond=0).isoformat(),
        "end": now.replace(hour=11, minute=0, second=0, microsecond=0).isoformat(),
        "status": "booked"
    }
    resource_counters["appointments"] = 1

