import requests
import re
import hashlib
import secrets
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from urllib.parse import urlparse

app = FastAPI()

users = {}
tokens = {}
thumbnails = {}
thumbnail_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ThumbnailGetRequest(BaseModel):
    video_page_url: str

def hash_password(password: str):
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token():
    return secrets.token_hex(32)

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/thumbnail/get")
def get_thumbnail(req: ThumbnailGetRequest, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    global thumbnail_id_counter

    video_url = req.video_page_url

    try:
        response = requests.get(video_url, headers={"User-Agent": "Mozilla/5.0"})
        response.raise_for_status()
        html = response.text
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Failed to fetch video page: {str(e)}")

    # Try multiple patterns to extract thumbnail URLs
    thumbnail_url = None

    # YouTube-style: yt-thumbnail or thumbnail_url in JSON
    patterns = [
        r'<link\s+rel="image_src"\s+href="([^"]+)"',
        r'"thumbnail_url"\s*:\s*"([^"]+)"',
        r'"thumbnail"\s*:\s*{\s*"url"\s*:\s*"([^"]+)"',
        r'property="og:image"\s+content="([^"]+)"',
        r'content="([^"]+)"\s+property="og:image"',
        r'<img[^>]+class="[^"]*thumbnail[^"]*"[^>]+src="([^"]+)"',
        r'data-thumbnail="([^"]+)"',
        r'poster="([^"]+)"',
    ]

    for pattern in patterns:
        match = re.search(pattern, html, re.IGNORECASE)
        if match:
            candidate = match.group(1)
            if candidate.startswith("//"):
                candidate = "https:" + candidate
            if candidate.startswith("http"):
                thumbnail_url = candidate
                break

    if not thumbnail_url:
        raise HTTPException(status_code=404, detail="No thumbnail found on page")

    # Try to get highest resolution by replacing quality parameters
    # YouTube specific: replace hqdefault with maxresdefault
    if "hqdefault" in thumbnail_url:
        high_res_url = thumbnail_url.replace("hqdefault", "maxresdefault")
    elif "sddefault" in thumbnail_url:
        high_res_url = thumbnail_url.replace("sddefault", "maxresdefault")
    else:
        high_res_url = thumbnail_url

    # For YouTube, also try different resolutions
    if "ytimg.com" in high_res_url:
        # Try maxresdefault first
        test_url = high_res_url
        try:
            test_resp = requests.head(test_url, timeout=5)
            if test_resp.status_code != 200:
                # Fall back to hqdefault
                test_url = thumbnail_url
        except:
            test_url = thumbnail_url
        high_res_url = test_url

    thumbnail_data = {
        "id": thumbnail_id_counter,
        "video_page_url": video_url,
        "thumbnail_url": high_res_url,
        "user": user
    }
    thumbnails[thumbnail_id_counter] = thumbnail_data
    thumbnail_id_counter += 1

    return thumbnail_data

@app.get("/thumbnail/{id}")
def get_thumbnail_by_id(id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    if id not in thumbnails:
        raise HTTPException(status_code=404, detail="Thumbnail not found")
    return thumbnails[id]

