        "username": "testuser",
        "password": "testpass123"
    })
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Create order
    order_resp = session.post(f"{BASE_URL}/order", json={
        "item": "test_item",
        "quantity": 2
    }, headers=headers)
    if order_resp.status_code != 200:
        return False
    order_id = order_resp.json().get("id")
    if not order_id:
        return False

