    fetch_order_resp = session.get(f"{BASE_URL}/order/{order_id}", headers=headers)
    if fetch_order_resp.status_code != 200:
        return False
    fetched_order = fetch_order_resp.json()
    if fetched_order.get("item") != "test_item" or fetched_order.get("quantity") != 2:
        return False

