from pydantic import BaseModel
from typing import Optional, Dict
import uuid

app = FastAPI()

users = {}
travelers = {}
tokens = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TravelerUpdate(BaseModel):
    name: Optional[str] = None
    passport_info: Optional[str] = None
    travel_preferences: Optional[str] = None
    membership_tier: Optional[str] = None

class TravelerCreate(BaseModel):
    name: str
    passport_info: str
    travel_preferences: str
    membership_tier: str

next_user_id = 1
next_traveler_id = 1

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    token = str(uuid.uuid4())
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/travelers/{traveler_id}")
def get_traveler(traveler_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if traveler_id not in travelers:
        raise HTTPException(status_code=404, detail="Traveler not found")
    return travelers[traveler_id]

@app.post("/travelers")
def create_traveler(req: TravelerCreate, authorization: str = Header(None)):
    global next_traveler_id
    get_user_from_token(authorization)
    traveler_id = next_traveler_id
    next_traveler_id += 1
    travelers[traveler_id] = {
        "id": traveler_id,
        "name": req.name,
        "passport_info": req.passport_info,
        "travel_preferences": req.travel_preferences,
        "membership_tier": req.membership_tier
    }
    return travelers[traveler_id]

@app.put("/travelers/{traveler_id}")
def update_traveler(traveler_id: int, req: TravelerUpdate, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if traveler_id not in travelers:
        raise HTTPException(status_code=404, detail="Traveler not found")
    t = travelers[traveler_id]
    if req.name is not None:
        t["name"] = req.name
    if req.passport_info is not None:
        t["passport_info"] = req.passport_info
    if req.travel_preferences is not None:
        t["travel_preferences"] = req.travel_preferences
    if req.membership_tier is not None:
        t["membership_tier"] = req.membership_tier
    return t

