from typing import Optional
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
notes = {}
note_id_counter = 1

def generate_token():
    return secrets.token_hex(16)

def hash_password(password: str):
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[username] = hash_password(password)
    return {"message": "User created"}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = username
    return {"token": token}

@app.post("/notes")
def create_note(content: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    global note_id_counter
    note_id = note_id_counter
    note_id_counter += 1
    notes[note_id] = {"id": note_id, "content": content, "owner": user}
    return notes[note_id]

@app.get("/notes/{note_id}")
def get_note(note_id: int, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if note_id not in notes:
        raise HTTPException(status_code=404, detail="Note not found")
    return notes[note_id]

