import uvicorn
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel

app = FastAPI()

drivers = {}
next_driver_id = 1
users = {}
tokens = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class DriverUpdate(BaseModel):
    name: str = None
    license_info: str = None
    delivery_zone: str = None
    dispatch_priority: int = None

def require_auth(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = hashlib.sha256(req.password.encode()).hexdigest()
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if users[req.username] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = req.username
    return {"token": token}

@app.put("/drivers/{driver_id}")
def update_driver(driver_id: int, update: DriverUpdate, authorization: str = Header(None)):
    require_auth(authorization)
    if driver_id not in drivers:
        raise HTTPException(status_code=404, detail="Driver not found")
    driver = drivers[driver_id]
    if update.name is not None:
        driver["name"] = update.name
    if update.license_info is not None:
        driver["license_info"] = update.license_info
    if update.delivery_zone is not None:
        driver["delivery_zone"] = update.delivery_zone
    if update.dispatch_priority is not None:
        driver["dispatch_priority"] = update.dispatch_priority
    return driver

