    signup_data = {"username": "testuser", "password": "testpass123"}
    try:
        r = session.post(f"{BASE_URL}/signup", json=signup_data)
        if r.status_code not in (200, 201):
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    # Step 2: Login with the same user
    login_data = {"username": "testuser", "password": "testpass123"}
    try:
        r = session.post(f"{BASE_URL}/login", json=login_data)
        if r.status_code not in (200, 201):
            print("SPEC_FAIL")
            sys.exit(1)
        token = r.json().get("token")
        if not token:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    # Step 3: Create a driver resource
    headers = {"Authorization": f"Bearer {token}"}
    driver_data = {"name": "John Doe", "license_info": "ABC123", "delivery_zone": "Downtown", "dispatch_priority": 1}
    try:
        r = session.post(f"{BASE_URL}/drivers", json=driver_data, headers=headers)
        if r.status_code not in (200, 201):
            print("SPEC_FAIL")
            sys.exit(1)
        driver_id = r.json().get("id")
        if not driver_id:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    # Step 4: Fetch the created driver resource
    try:
        r = session.get(f"{BASE_URL}/drivers/{driver_id}", headers=headers)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        fetched_driver = r.json()
        if fetched_driver.get("name") != "John Doe":
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    print("SPEC_PASS")
    sys.exit(0)

if __name__ == "__main__":
    main()

