    session = requests.Session()

    # Step 1: Sign up a new user
    signup_data = {"username": "testuser", "password": "testpass"}
    r = session.post(f"{BASE_URL}/signup", json=signup_data)
    if r.status_code not in (200, 201):
        return False
    signup_response = r.json()
    if "id" not in signup_response or "username" not in signup_response:
        return False
    if signup_response["username"] != "testuser":
        return False

    # Step 2: Log in with the new user
    login_data = {"username": "testuser", "password": "testpass"}
    r = session.post(f"{BASE_URL}/login", json=login_data)
    if r.status_code != 200:
        return False
    login_response = r.json()
    if "token" not in login_response:
        return False
    token = login_response["token"]
    headers = {"Authorization": f"Bearer {token}"}

    # Step 3: Create a resource
    resource_data = {"data": {"name": "test_resource"}}
    r = session.post(f"{BASE_URL}/items", json=resource_data, headers=headers)
    if r.status_code not in (200, 201):
        return False
    create_response = r.json()
    if "id" not in create_response or "data" not in create_response:
        return False
    resource_id = create_response["id"]

    # Step 4: Fetch the created resource
    r = session.get(f"{BASE_URL}/items/{resource_id}", headers=headers)
    if r.status_code != 200:
        return False
    fetch_response = r.json()
    if fetch_response.get("id") != resource_id:
        return False
    if fetch_response.get("data") != {"name": "test_resource"}:
