def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/events/{event_id}")
def get_event(event_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    return event

@app.post("/events")
def create_event(title: str, date: str, location: str, max_capacity: int, guest_list_visibility: bool, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_event_id
    event_id = next_event_id
    next_event_id += 1
    events[event_id] = {
        "id": event_id,
        "title": title,
        "date": date,
        "location": location,
        "max_capacity": max_capacity,
        "guest_list_visibility": guest_list_visibility,
        "created_by": user_id,
        "guests": []
    }
    return events[event_id]

@app.put("/events/{event_id}")
def update_event(event_id: int, title: Optional[str] = None, date: Optional[str] = None, location: Optional[str] = None, max_capacity: Optional[int] = None, guest_list_visibility: Optional[bool] = None, bulk_invite_statuses: Optional[dict] = None, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if event["created_by"] != user_id:
        raise HTTPException(status_code=403, detail="Not authorized to update this event")
    if title is not None:
        event["title"] = title
    if date is not None:
        event["date"] = date
    if location is not None:
        event["location"] = location
    if max_capacity is not None:
        event["max_capacity"] = max_capacity
    if guest_list_visibility is not None:
        event["guest_list_visibility"] = guest_list_visibility
    if bulk_invite_statuses:
        for guest_id, status in bulk_invite_statuses.items():
            guest_id = int(guest_id)
            for g in event["guests"]:
                if g["user_id"] == guest_id:
                    g["status"] = status
    return event

@app.post("/events/{event_id}/rsvp")
def create_rsvp(event_id: int, status: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    for g in event["guests"]:
        if g["user_id"] == user_id:
            g["status"] = status
            return g
    guest = {"user_id": user_id, "status": status}
    event["guests"].append(guest)
    return guest

@app.get("/events/{event_id}/rsvp/{rsvp_id}")
def get_rsvp(event_id: int, rsvp_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if not event["guest_list_visibility"] and rsvp_id != user_id:
        raise HTTPException(status_code=403, detail="Not authorized to view this RSVP")
    for g in event["guests"]:
        if g["user_id"] == rsvp_id:
            return g
    raise HTTPException(status_code=404, detail="RSVP not found")

