import math

app = FastAPI()

users = {}
tokens = {}
subscriptions = {}
churn_tracker = {}
sub_id_counter = 1
user_id_counter = 1

PLANS = {
    "free": {"price": 0, "billing_cycle": "monthly"},
    "basic": {"price": 9.99, "billing_cycle": "monthly"},
    "pro": {"price": 29.99, "billing_cycle": "monthly"},
    "enterprise": {"price": 99.99, "billing_cycle": "yearly"},
}

def get_user_from_token(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "tier": "free"}
    subscriptions[user_id] = {
        "user_id": user_id,
        "plan": "free",
        "price": 0,
        "billing_cycle": "monthly",
        "active": True,
        "start_date": datetime.now().isoformat(),
    }
    churn_tracker[user_id] = datetime.now()
    return {"user_id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/subscriptions")
def get_subscriptions(authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    sub = subscriptions.get(user_id)
    if not sub:
        raise HTTPException(status_code=404, detail="No subscription found")
    return {
        "plan": sub["plan"],
        "price": sub["price"],
        "billing_cycle": sub["billing_cycle"],
        "active": sub["active"],
    }

@app.post("/upgrade")
def upgrade(tier: str, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    if tier not in PLANS:
        raise HTTPException(status_code=400, detail="Invalid tier")
    sub = subscriptions.get(user_id)
    if not sub:
        raise HTTPException(status_code=404, detail="No subscription found")
    old_plan = sub["plan"]
    new_plan = tier
    old_price = PLANS[old_plan]["price"]
    new_price = PLANS[new_plan]["price"]
    if new_price <= old_price:
        prorated_charge = 0
    else:
        days_in_cycle = 30
        days_used = (datetime.now() - datetime.fromisoformat(sub["start_date"])).days
        days_remaining = max(0, days_in_cycle - days_used)
        daily_rate = old_price / days_in_cycle
        credit = daily_rate * days_remaining
        prorated_charge = round(new_price - credit, 2)
    sub["plan"] = new_plan
    sub["price"] = new_price
    sub["billing_cycle"] = PLANS[new_plan]["billing_cycle"]
    sub["start_date"] = datetime.now().isoformat()
    users[user_id]["tier"] = new_plan
    return {"new_plan": new_plan, "prorated_charge": prorated_charge}

@app.get("/churn-risk")
def get_churn_risk(authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    cutoff = datetime.now() - timedelta(days=45)
    at_risk = []
    for uid, last_active in churn_tracker.items():
        if last_active < cutoff:
            u = users.get(uid)
            if u:
                at_risk.append({"user_id": uid, "username": u["username"]})
    return {"churn_risk_users": at_risk}

@app.get("/{resource}/{resource_id}")
def get_resource(resource: str, resource_id: int, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    if resource == "users":
        if resource_id not in users:
            raise HTTPException(status_code=404, detail="User not found")
        return users[resource_id]
    elif resource == "subscriptions":
        if resource_id not in subscriptions:
            raise HTTPException(status_code=404, detail="Subscription not found")
        return subscriptions[resource_id]
    raise HTTPException(status_code=400, detail="Unknown resource")

@app.post("/{resource}")
def create_resource(resource: str, data: dict, authorization: str = Header(...)):
    user_id = get_user_from_token(authorization)
    if resource == "users":
        raise HTTPException(status_code=400, detail="Use /signup for users")
    elif resource == "subscriptions":
        raise HTTPException(status_code=400, detail="Use /upgrade for subscriptions")
    raise HTTPException(status_code=400, detail="Unknown resource")

