from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import uuid
import datetime

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
events = {}
orders = {}
waitlist = {}
event_id_counter = 1
order_id_counter = 1

# Seed some events
events[1] = {"id": 1, "name": "Rock Night", "date": "2025-03-15", "capacity": 100, "sold": 0}
events[2] = {"id": 2, "name": "Jazz Evening", "date": "2025-03-20", "capacity": 50, "sold": 0}
events[3] = {"id": 3, "name": "Comedy Hour", "date": "2025-03-25", "capacity": 75, "sold": 0}
event_id_counter = 4

# Promo codes
promo_codes = {"EARLYBIRD10": 10, "FRIENDS20": 20}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PurchaseRequest(BaseModel):
    event_id: int
    quantity: int
    promo_code: Optional[str] = None

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = len(users) + 1
    users[req.username] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = user["id"]
    return {"token": token}

@app.get("/events")
def list_events():
    return [e for e in events.values()]

@app.post("/purchase")
def purchase(req: PurchaseRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(req.event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")

    discount = 0
    if req.promo_code:
        discount = promo_codes.get(req.promo_code, 0)

    if event["sold"] + req.quantity > event["capacity"]:
        # Add to waitlist
        if req.event_id not in waitlist:
            waitlist[req.event_id] = []
        waitlist[req.event_id].append({"user_id": user_id, "quantity": req.quantity})
        return {"message": "Sold out, added to waitlist", "waitlist_position": len(waitlist[req.event_id])}

    event["sold"] += req.quantity
    global order_id_counter
    order_id = order_id_counter
    order_id_counter += 1
    orders[order_id] = {
        "id": order_id,
        "user_id": user_id,
        "event_id": req.event_id,
        "quantity": req.quantity,
        "discount": discount
    }
    return {"order_id": order_id, "tickets_purchased": req.quantity, "discount_applied": discount}

@app.get("/waitlist")
def get_waitlist():
    result = {}
    for event_id, entries in waitlist.items():
        result[event_id] = len(entries)
    return result

@app.get("/events/{event_id}")
def get_event(event_id: int):
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    return event

@app.post("/events")
def create_event(name: str, date: str, capacity: int):
    global event_id_counter
    event_id = event_id_counter
    event_id_counter += 1
    events[event_id] = {
        "id": event_id,
        "name": name,
        "date": date,
        "capacity": capacity,
        "sold": 0
    }
    return events[event_id]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

@app.post("/orders")
def create_order(event_id: int, quantity: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if event["sold"] + quantity > event["capacity"]:
        raise HTTPException(status_code=400, detail="Not enough tickets")
    event["sold"] += quantity
    global order_id_counter
    order_id = order_id_counter
    order_id_counter += 1
    orders[order_id] = {
        "id": order_id,
        "user_id": user_id,
        "event_id": event_id,
        "quantity": quantity
    }
    return orders[order_id]

