users = {}
tokens = {}
students = {}
quizzes = {}
quiz_questions = {}
completions = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class QuizCreate(BaseModel):
    course_id: int
    title: str

class QuestionCreate(BaseModel):
    question_type: str
    prompt: str
    options: Optional[List[str]] = None
    correct_answer: str

class StudentAnswer(BaseModel):
    answer: str

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = len(users) + 1
    users[req.username] = {"id": user_id, "username": req.username, "password": req.password}
    students[user_id] = {"id": user_id, "username": req.username}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = users[req.username]["id"]
    return {"token": token}

@app.post("/quiz")
def create_quiz(quiz: QuizCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    quiz_id = len(quizzes) + 1
    quizzes[quiz_id] = {"id": quiz_id, "course_id": quiz.course_id, "title": quiz.title, "creator_id": user_id}
    return quizzes[quiz_id]

@app.get("/quiz/{quiz_id}")
def get_quiz(quiz_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    return quizzes[quiz_id]

@app.post("/quiz/{quiz_id}/question")
def add_question(quiz_id: int, question: QuestionCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    if quiz_id not in quizzes:
        raise HTTPException(status_code=404, detail="Quiz not found")
    if quiz_id not in quiz_questions:
        quiz_questions[quiz_id] = []
    q_id = len(quiz_questions[quiz_id]) + 1
    q_data = {"id": q_id, "quiz_id": quiz_id, "question_type": question.question_type, "prompt": question.prompt, "options": question.options, "correct_answer": question.correct_answer}
    quiz_questions[quiz_id].append(q_data)
    return q_data

@app.get("/quiz/{course_id}/{question_num}.xml")
def get_quiz_question(course_id: int, question_num: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    for qid, quiz in quizzes.items():
        if quiz["course_id"] == course_id:
            if qid not in quiz_questions:
                raise HTTPException(status_code=404, detail="No questions for this quiz")
            for q in quiz_questions[qid]:
                if q["id"] == question_num:
                    return {
                        "question": {
                            "type": q["question_type"],
                            "prompt": q["prompt"],
                            "options": q.get("options"),
                            "id": q["id"]
                        }
                    }
    raise HTTPException(status_code=404, detail="Question not found")

@app.post("/quiz/{course_id}/{question_num}/answer")
def answer_question(course_id: int, question_num: int, answer: StudentAnswer, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    for qid, quiz in quizzes.items():
        if quiz["course_id"] == course_id:
            if qid not in quiz_questions:
                raise HTTPException(status_code=404, detail="No questions for this quiz")
            for q in quiz_questions[qid]:
                if q["id"] == question_num:
                    correct = q["correct_answer"] == answer.answer
                    if user_id not in completions:
                        completions[user_id] = {}
                    if course_id not in completions[user_id]:
                        completions[user_id][course_id] = []
                    completions[user_id][course_id].append({
                        "question_id": question_num,
                        "answer": answer.answer,
                        "correct": correct
                    })
                    return {"correct": correct}
    raise HTTPException(status_code=404, detail="Question not found")

@app.get("/completion/{user_id}/{course_id}")
def get_completion(user_id: int, course_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if user_id not in completions or course_id not in completions[user_id]:
        return {"answers": []}
    return {"answers": completions[user_id][course_id]}

