        if u["username"] == req.username and u["password"] == req.password:
            token = f"tok_{uid}_{datetime.utcnow().timestamp()}"
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/shipments/{tracking_id}/documents/{doc_name}")
def get_document(tracking_id: str, doc_name: str, authorization: str = Header(None)):
    get_current_user(authorization)
    base_path = Path(f"/logistics/{tracking_id}")
    file_path = base_path / doc_name
    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="Document not found")
    return FileResponse(file_path)

@app.get("/shipments/{tracking_id}/documents")
def list_documents(tracking_id: str, page: int = 1, per_page: int = 10, authorization: str = Header(None)):
    get_current_user(authorization)
    base_path = Path(f"/logistics/{tracking_id}")
    if not base_path.exists() or not base_path.is_dir():
        raise HTTPException(status_code=404, detail="Tracking ID not found")
    all_files = []
    for f in base_path.iterdir():
        if f.is_file():
            stat = f.stat()
            all_files.append({
                "name": f.name,
                "size": stat.st_size,
                "date": datetime.fromtimestamp(stat.st_mtime).isoformat()
            })
    total = len(all_files)
    start = (page - 1) * per_page
    end = start + per_page
    return {
        "page": page,
        "per_page": per_page,
        "total": total,
        "documents": all_files[start:end]
    }

