import os
import uuid
import shutil
import subprocess
from pathlib import Path
from typing import List

from fastapi import FastAPI, UploadFile, File, HTTPException, Header
from fastapi.responses import FileResponse

app = FastAPI()

users = {}
tokens = {}
user_id_counter = 1
media_id_counter = 1
media_store = {}  # media_id -> {user_id, filename, original_path, compressed_path}

BASE_DIR = Path("dating_profiles")
BASE_DIR.mkdir(exist_ok=True)

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Unauthorized")
    token = authorization.split(" ")[1]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {"username": username, "password": password}
    token = str(uuid.uuid4())
    tokens[uid] = token
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = str(uuid.uuid4())
            tokens[uid] = token
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/profiles/{user_id}/media/{media_id}.mp4")
def stream_media(user_id: int, media_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if media_id not in media_store:
        raise HTTPException(status_code=404, detail="Media not found")
    m = media_store[media_id]
    if m["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Forbidden")
    path = m["compressed_path"] or m["original_path"]
    if not path or not os.path.exists(path):
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(path, media_type="video/mp4")

@app.post("/profiles/{user_id}/media")
async def upload_media(user_id: int, files: List[UploadFile] = File(...), authorization: str = Header(None)):
    get_current_user(authorization)
    if len(files) > 3:
        raise HTTPException(status_code=400, detail="Max 3 files")
    user_dir = BASE_DIR / str(user_id)
    user_dir.mkdir(exist_ok=True)
    ids = []
    for f in files:
        global media_id_counter
        mid = media_id_counter
        media_id_counter += 1
        ext = os.path.splitext(f.filename)[1] or ".mp4"
        original_path = user_dir / f"{mid}_original{ext}"
        compressed_path = user_dir / f"{mid}.mp4"
        content = await f.read()
        with open(original_path, "wb") as out:
            out.write(content)
        # auto-compress using ffmpeg
        try:
            subprocess.run(
                ["ffmpeg", "-i", str(original_path), "-vcodec", "libx264", "-crf", "28", str(compressed_path)],
                capture_output=True, check=True
            )
        except (subprocess.CalledProcessError, FileNotFoundError):
            compressed_path = original_path
        media_store[mid] = {
            "user_id": user_id,
            "filename": f.filename,
            "original_path": str(original_path),
            "compressed_path": str(compressed_path) if compressed_path != original_path else None
        }
        ids.append(mid)
    return {"media_ids": ids}

