import time
import shutil
from fastapi import FastAPI, Header, HTTPException, Query
from fastapi.responses import FileResponse
from pydantic import BaseModel
from typing import Optional, Dict

app = FastAPI()

users = {}
tokens = {}
itineraries = {}
next_user_id = 1
next_trip_id = 1
next_itinerary_id = 1

TRAVEL_DOCS_DIR = "/travel_docs"
os.makedirs(TRAVEL_DOCS_DIR, exist_ok=True)

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ItineraryCreate(BaseModel):
    user_id: int
    title: str
    destination: str
    days: int

def generate_token():
    return hashlib.sha256(str(time.time()).encode()).hexdigest()

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    for uid, tok in tokens.items():
        if tok == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": req.username, "password": req.password}
    return {"user_id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, user in users.items():
        if user["username"] == req.username and user["password"] == req.password:
            token = generate_token()
            tokens[uid] = token
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/itineraries")
def create_itinerary(it: ItineraryCreate, authorization: str = Header(...)):
    global next_itinerary_id
    current_user = get_current_user(authorization)
    if it.user_id != current_user:
        raise HTTPException(status_code=403, detail="Cannot create itinerary for another user")
    iid = next_itinerary_id
    next_itinerary_id += 1
    itineraries[iid] = {
        "id": iid,
        "user_id": it.user_id,
        "title": it.title,
        "destination": it.destination,
        "days": it.days,
        "created_at": time.time()
    }
    return itineraries[iid]

@app.get("/itineraries/{itinerary_id}")
def get_itinerary(itinerary_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if itinerary_id not in itineraries:
        raise HTTPException(status_code=404, detail="Itinerary not found")
    return itineraries[itinerary_id]

@app.get("/itineraries/{user_id}/{trip_id}.pdf")
def get_itinerary_pdf(user_id: int, trip_id: int, refresh: bool = Query(False), authorization: str = Header(...)):
    current_user = get_current_user(authorization)
    if current_user != user_id:
        raise HTTPException(status_code=403, detail="Forbidden")

    # Find itinerary by user_id and trip_id (using itinerary id as trip_id for simplicity)
    found = None
    for iid, it in itineraries.items():
        if it["user_id"] == user_id and iid == trip_id:
            found = it
            break

    if not found:
        raise HTTPException(status_code=404, detail="Itinerary not found")

    user_dir = os.path.join(TRAVEL_DOCS_DIR, str(user_id))
    os.makedirs(user_dir, exist_ok=True)
    pdf_path = os.path.join(user_dir, f"{trip_id}.pdf")

    if refresh or not os.path.exists(pdf_path):
        # Generate a simple PDF-like text file (since we're shipping at 3am)
        content = f"""ITINERARY #{trip_id}
User: {user_id}
Title: {found['title']}
Destination: {found['destination']}
Days: {found['days']}
Generated: {time.ctime()}
"""
        with open(pdf_path, "w") as f:
            f.write(content)

    return FileResponse(pdf_path, media_type="application/pdf", filename=f"itinerary_{trip_id}.pdf")

@app.get("/itineraries")
def list_itineraries(authorization: str = Header(...)):
    current_user = get_current_user(authorization)
    user_itineraries = [it for it in itineraries.values() if it["user_id"] == current_user]
    return {"itineraries": user_itineraries, "count": len(user_itineraries)}

