from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import hashlib
import random
import string

app = FastAPI()

users = {}
players = {}
tokens = {}
next_user_id = 1
next_player_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PlayerCreate(BaseModel):
    display_name: str
    score: int = 0
    rank: int = 0
    tier: str = "bronze"
    admin: bool = False

class PlayerUpdate(BaseModel):
    display_name: Optional[str] = None
    score: Optional[int] = None
    rank: Optional[int] = None
    tier: Optional[str] = None
    admin: Optional[bool] = None

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": hashlib.sha256(req.password.encode()).hexdigest()
    }
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == hashlib.sha256(req.password.encode()).hexdigest():
            token = generate_token()
            tokens[token] = u["id"]
            return {"user_id": u["id"], "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/players/{player_id}")
def get_player(player_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    player = players.get(player_id)
    if not player:
        raise HTTPException(status_code=404, detail="Player not found")
    return player

