def create_player(player: PlayerCreate, authorization: str = Header(None)):
    global next_player_id
    get_current_user(authorization)
    player_id = next_player_id
    next_player_id += 1
    players[player_id] = {
        "id": player_id,
        "display_name": player.display_name,
        "score": player.score,
        "rank": player.rank,
        "tier": player.tier,
        "admin": player.admin
    }
    return players[player_id]

@app.patch("/players/{player_id}")
