from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import time

app = FastAPI()

users = {}
tokens = {}
loan_requests = {}
fundings = {}
repayments = {}
loans = {}
user_id_counter = 1
loan_request_id_counter = 1
funding_id_counter = 1
repayment_id_counter = 1
loan_id_counter = 1

class SignupRequest(BaseModel):
    name: str
    email: str
    password: str

class LoginRequest(BaseModel):
    email: str
    password: str

class LoanRequestCreate(BaseModel):
    amount: float
    interest_rate: float
    term_days: int

class FundingCreate(BaseModel):
    loan_request_id: int
    amount: float

class RepaymentCreate(BaseModel):
    loan_id: int
    amount: float

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["email"] == req.email:
            raise HTTPException(status_code=400, detail="Email already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "name": req.name, "email": req.email, "password": req.password, "balance": 0.0}
    return {"user_id": user_id, "name": req.name, "email": req.email}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["email"] == req.email and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/loan_requests")
def create_loan_request(req: LoanRequestCreate, authorization: Optional[str] = Header(None)):
    global loan_request_id_counter
    user_id = get_current_user(authorization)
    lr_id = loan_request_id_counter
    loan_request_id_counter += 1
    loan_requests[lr_id] = {
        "id": lr_id,
        "borrower_id": user_id,
        "amount": req.amount,
        "interest_rate": req.interest_rate,
        "term_days": req.term_days,
        "status": "open",
        "funded_amount": 0.0,
        "created_at": time.time()
    }
    return loan_requests[lr_id]

@app.get("/loan_requests/{lr_id}")
def get_loan_request(lr_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if lr_id not in loan_requests:
        raise HTTPException(status_code=404, detail="Loan request not found")
    return loan_requests[lr_id]

@app.post("/fundings")
def create_funding(req: FundingCreate, authorization: Optional[str] = Header(None)):
    global funding_id_counter
    lender_id = get_current_user(authorization)
    if req.loan_request_id not in loan_requests:
        raise HTTPException(status_code=404, detail="Loan request not found")
    lr = loan_requests[req.loan_request_id]
    if lr["status"] != "open":
        raise HTTPException(status_code=400, detail="Loan request is not open")
    if lr["borrower_id"] == lender_id:
        raise HTTPException(status_code=400, detail="Cannot fund your own loan request")
    remaining = lr["amount"] - lr["funded_amount"]
    if req.amount > remaining:
        raise HTTPException(status_code=400, detail="Funding amount exceeds remaining")
    fid = funding_id_counter
    funding_id_counter += 1
    fundings[fid] = {
        "id": fid,
        "loan_request_id": req.loan_request_id,
        "lender_id": lender_id,
        "amount": req.amount,
        "created_at": time.time()
    }
    lr["funded_amount"] += req.amount
    if lr["funded_amount"] >= lr["amount"]:
        lr["status"] = "funded"
        global loan_id_counter
        loan_id = loan_id_counter
        loan_id_counter += 1
        loans[loan_id] = {
            "id": loan_id,
            "loan_request_id": req.loan_request_id,
            "borrower_id": lr["borrower_id"],
            "amount": lr["amount"],
            "interest_rate": lr["interest_rate"],
            "term_days": lr["term_days"],
            "status": "active",
            "outstanding": lr["amount"] * (1 + lr["interest_rate"] / 100),
            "created_at": time.time()
        }
    return fundings[fid]

@app.get("/fundings/{fid}")
def get_funding(fid: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if fid not in fundings:
        raise HTTPException(status_code=404, detail="Funding not found")
    return fundings[fid]

@app.post("/repayments")
def create_repayment(req: RepaymentCreate, authorization: Optional[str] = Header(None)):
    global repayment_id_counter
    borrower_id = get_current_user(authorization)
    if req.loan_id not in loans:
        raise HTTPException(status_code=404, detail="Loan not found")
    loan = loans[req.loan_id]
    if loan["borrower_id"] != borrower_id:
        raise HTTPException(status_code=403, detail="You are not the borrower of this loan")
    if loan["status"] != "active":
