from pydantic import BaseModel
from typing import Optional
import secrets
import time

app = FastAPI()

users = {}
tokens = {}
loan_requests = {}
fundings = {}
repayments = {}
loans = {}
user_id_counter = 1
loan_request_id_counter = 1
funding_id_counter = 1
repayment_id_counter = 1
loan_id_counter = 1

class SignupRequest(BaseModel):
    name: str
    email: str
    password: str

class LoginRequest(BaseModel):
    email: str
    password: str

class LoanRequestCreate(BaseModel):
    amount: float
    interest_rate: float
    term_days: int

class FundingCreate(BaseModel):
    loan_request_id: int
    amount: float

class RepaymentCreate(BaseModel):
    loan_id: int
    amount: float

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["email"] == req.email:
            raise HTTPException(status_code=400, detail="Email already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "name": req.name, "email": req.email, "password": req.password, "balance": 0.0}
    return {"user_id": user_id, "name": req.name, "email": req.email}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["email"] == req.email and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/loan_requests")
def create_loan_request(req: LoanRequestCreate, authorization: Optional[str] = Header(None)):
    global loan_request_id_counter
    user_id = get_current_user(authorization)
    lr_id = loan_request_id_counter
    loan_request_id_counter += 1
    loan_requests[lr_id] = {
        "id": lr_id,
        "borrower_id": user_id,
        "amount": req.amount,
        "interest_rate": req.interest_rate,
        "term_days": req.term_days,
        "status": "open",
        "funded_amount": 0.0,
        "created_at": time.time()
    }
    return loan_requests[lr_id]

@app.get("/loan_requests/{lr_id}")
def get_loan_request(lr_id: int, authorization: Optional[str] = Header(None)):
