import secrets
from datetime import datetime, timedelta
from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel

app = FastAPI()

users = {}
tokens = {}
spots = {}
orders = {}
order_id_counter = 1
spot_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class SpotCreate(BaseModel):
    name: str

class OrderCreate(BaseModel):
    spot_id: int
    start_time: str
    end_time: str

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

def compute_price(start_hour, end_hour):
    total = 0
    for h in range(start_hour, end_hour):
        if 7 <= h < 10:
            total += 10
        elif 10 <= h < 17:
            total += 5
        elif 17 <= h < 20:
            total += 8
        else:
            total += 3
    return total

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = req.password
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != req.password:
        raise HTTPException(status_code=401, detail="Bad credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/spots")
def create_spot(spot: SpotCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global spot_id_counter
    spot_id = spot_id_counter
    spot_id_counter += 1
    spots[spot_id] = {"id": spot_id, "name": spot.name, "available": True}
    return spots[spot_id]

@app.get("/spots/{spot_id}")
def get_spot(spot_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if spot_id not in spots:
        raise HTTPException(status_code=404, detail="Spot not found")
    return spots[spot_id]

@app.get("/spots")
def list_spots(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(spots.values())

@app.post("/orders")
def create_order(order: OrderCreate, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global order_id_counter
    if order.spot_id not in spots:
        raise HTTPException(status_code=404, detail="Spot not found")
    if not spots[order.spot_id]["available"]:
        raise HTTPException(status_code=400, detail="Spot not available")
    try:
        start = datetime.fromisoformat(order.start_time)
        end = datetime.fromisoformat(order.end_time)
    except:
        raise HTTPException(status_code=400, detail="Invalid datetime format")
    if start >= end:
        raise HTTPException(status_code=400, detail="Start must be before end")
    total_hours = (end - start).seconds // 3600
    if total_hours < 1:
        raise HTTPException(status_code=400, detail="Minimum 1 hour")
    price = compute_price(start.hour, end.hour)
    order_id = order_id_counter
    order_id_counter += 1
    spots[order.spot_id]["available"] = False
    orders[order_id] = {
        "id": order_id,
        "user": user,
        "spot_id": order.spot_id,
        "start_time": order.start_time,
        "end_time": order.end_time,
        "price": price
    }
    return orders[order_id]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if order_id not in orders:
        raise HTTPException(status_code=404, detail="Order not found")
    return orders[order_id]

@app.get("/orders")
def list_orders(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(orders.values())

