from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import secrets
import hashlib
from datetime import datetime

app = FastAPI()

users = {}
tokens = {}
contracts = {}
signatures = {}
audit_logs = {}
next_user_id = 1
next_contract_id = 1
next_signature_id = 1
next_audit_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ContractCreate(BaseModel):
    title: str
    content: str

class SignatureCreate(BaseModel):
    contract_id: int
    signer_name: str

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid token")
    token = authorization.split(" ")[1]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="User exists")
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": req.username, "password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == hashlib.sha256(req.password.encode()).hexdigest():
            token = secrets.token_hex(32)
            tokens[uid] = token
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/contracts")
def create_contract(req: ContractCreate, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    global next_contract_id
    cid = next_contract_id
    next_contract_id += 1
    contracts[cid] = {
        "id": cid,
        "title": req.title,
        "content": req.content,
        "created_by": uid,
        "created_at": datetime.utcnow().isoformat(),
        "status": "pending"
    }
    log_audit("contract_created", cid, uid, f"Contract '{req.title}' created")
    return contracts[cid]

@app.get("/contracts/{contract_id}")
def get_contract(contract_id: int, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    if contract_id not in contracts:
        raise HTTPException(status_code=404, detail="Contract not found")
    return contracts[contract_id]

@app.post("/signatures")
def create_signature(req: SignatureCreate, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    if req.contract_id not in contracts:
        raise HTTPException(status_code=404, detail="Contract not found")
    global next_signature_id
    sid = next_signature_id
    next_signature_id += 1
    signatures[sid] = {
        "id": sid,
        "contract_id": req.contract_id,
        "signer_name": req.signer_name,
        "signed_by": uid,
        "signed_at": datetime.utcnow().isoformat()
    }
    contracts[req.contract_id]["status"] = "signed"
    log_audit("signature_added", req.contract_id, uid, f"Signed by {req.signer_name}")
    return signatures[sid]

@app.get("/signatures/{signature_id}")
def get_signature(signature_id: int, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    if signature_id not in signatures:
        raise HTTPException(status_code=404, detail="Signature not found")
    return signatures[signature_id]

@app.get("/audit-logs/{contract_id}")
def get_audit_logs(contract_id: int, authorization: str = Header(None)):
    uid = get_current_user(authorization)
    if contract_id not in contracts:
        raise HTTPException(status_code=404, detail="Contract not found")
    logs = [v for v in audit_logs.values() if v["contract_id"] == contract_id]
    return logs

def log_audit(action: str, contract_id: int, user_id: int, detail: str):
    global next_audit_id
    aid = next_audit_id
    next_audit_id += 1
    audit_logs[aid] = {
        "id": aid,
        "contract_id": contract_id,
        "action": action,
        "user_id": user_id,
        "timestamp": datetime.utcnow().isoformat(),
        "detail": detail
    }

