from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import secrets

app = FastAPI()

users = {}
tokens = {}
cases = {}
documents = {}
case_id_counter = 1
document_id_counter = 1

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = {"password": password}
    return {"msg": "ok"}

@app.post("/login")
def login(username: str, password: str):
    user = users.get(username)
    if not user or user["password"] != password:
        raise HTTPException(status_code=401, detail="Bad credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

@app.post("/cases")
def create_case(name: str, opposing_counsel: str, filing_date: str = None, deadline_days: int = 30, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global case_id_counter
    cid = case_id_counter
    case_id_counter += 1
    if not filing_date:
        filing_date = datetime.now().isoformat()
    deadline = (datetime.now() + timedelta(days=deadline_days)).isoformat()
    cases[cid] = {
        "id": cid,
        "name": name,
        "opposing_counsel": opposing_counsel,
        "filing_date": filing_date,
        "deadline": deadline,
        "created_by": user
    }
    return cases[cid]

@app.get("/cases/{case_id}")
def get_case(case_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    case = cases.get(case_id)
    if not case:
        raise HTTPException(status_code=404, detail="Case not found")
    return case

@app.post("/documents")
def create_document(case_id: int, title: str, content: str, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if case_id not in cases:
        raise HTTPException(status_code=404, detail="Case not found")
    global document_id_counter
    did = document_id_counter
    document_id_counter += 1
    documents[did] = {
        "id": did,
        "case_id": case_id,
        "title": title,
        "content": content,
        "filed_by": user,
        "filed_at": datetime.now().isoformat()
