from pydantic import BaseModel
from typing import Optional
import uuid
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
portfolios = {}
next_user_id = 1
next_portfolio_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PortfolioCreate(BaseModel):
    name: str
    risk_tolerance: str = "moderate"
    rebalancing_frequency: str = "quarterly"

class PortfolioUpdate(BaseModel):
    name: Optional[str] = None
    risk_tolerance: Optional[str] = None
    rebalancing_frequency: Optional[str] = None
    subscription_tier: Optional[str] = None
    role: Optional[str] = None

def get_current_user(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    salt = secrets.token_hex(16)
    hashed = hashlib.sha256((req.password + salt).encode()).hexdigest()
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password_hash": hashed,
        "salt": salt
    }
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, user in users.items():
        if user["username"] == req.username:
            hash_check = hashlib.sha256((req.password + user["salt"]).encode()).hexdigest()
            if hash_check == user["password_hash"]:
                token = secrets.token_hex(32)
                tokens[token] = uid
                return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

