class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TrainerCreate(BaseModel):
    name: str

class ClassCreate(BaseModel):
    trainer_id: int
    max_capacity: int
    difficulty: str

class JoinClass(BaseModel):
    class_id: int
    user_id: int

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(body: UserSignup):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": body.username, "password": body.password}
    return {"user_id": uid}

@app.post("/login")
def login(body: UserLogin):
    for uid, u in users.items():
        if u["username"] == body.username and u["password"] == body.password:
            token = secrets.token_hex(16)
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trainers")
def create_trainer(body: TrainerCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_trainer_id
    tid = next_trainer_id
    next_trainer_id += 1
    trainers[tid] = {"id": tid, "name": body.name}
    return {"trainer_id": tid}

@app.get("/trainers/{trainer_id}")
def get_trainer(trainer_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if trainer_id not in trainers:
        raise HTTPException(status_code=404, detail="Trainer not found")
    return trainers[trainer_id]

@app.post("/classes")
def create_class(body: ClassCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_class_id
    if body.trainer_id not in trainers:
        raise HTTPException(status_code=404, detail="Trainer not found")
    cid = next_class_id
    next_class_id += 1
    classes[cid] = {
        "id": cid,
        "trainer_id": body.trainer_id,
        "max_capacity": body.max_capacity,
        "difficulty": body.difficulty,
        "enrolled_count": 0
    }
    return {"class_id": cid}

@app.get("/classes/{class_id}")
