    get_current_user(authorization)
    global next_enrollment_id, next_waitlist_id
    c = classes.get(body.class_id)
    if not c:
        raise HTTPException(status_code=404, detail="Class not found")
    if body.user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if c["enrolled_count"] < c["max_capacity"]:
        eid = next_enrollment_id
        next_enrollment_id += 1
        enrollments[eid] = {"id": eid, "class_id": body.class_id, "user_id": body.user_id}
        c["enrolled_count"] += 1
        return {"enrollment_id": eid, "status": "enrolled"}
    else:
        wid = next_waitlist_id
        next_waitlist_id += 1
        waitlist[wid] = {"id": wid, "class_id": body.class_id, "user_id": body.user_id}
        return {"waitlist_id": wid, "status": "waitlisted"}

