    get_current_user(authorization)
    c = classes.get(body.class_id)
    if not c:
        raise HTTPException(status_code=404, detail="Class not found")
    for eid, e in list(enrollments.items()):
        if e["class_id"] == body.class_id and e["user_id"] == body.user_id:
            del enrollments[eid]
            c["enrolled_count"] -= 1
            # auto-promote from waitlist
            waitlist_ids = sorted([wid for wid, w in waitlist.items() if w["class_id"] == body.class_id])
            if waitlist_ids:
                next_wid = waitlist_ids[0]
                next_user = waitlist[next_wid]["user_id"]
                del waitlist[next_wid]
                eid_new = next_enrollment_id
                next_enrollment_id += 1
                enrollments[eid_new] = {"id": eid_new, "class_id": body.class_id, "user_id": next_user}
                c["enrolled_count"] += 1
                return {"status": "dropped", "promoted_user_id": next_user}
            return {"status": "dropped"}
    raise HTTPException(status_code=404, detail="Enrollment not found")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

