from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict
import secrets
import datetime

app = FastAPI()

users: Dict[int, dict] = {}
next_user_id = 1
tokens: Dict[str, int] = {}

plans: Dict[int, dict] = {}
next_plan_id = 1

subscriptions: Dict[int, dict] = {}
next_sub_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PlanCreate(BaseModel):
    name: str
    delivery_frequency_days: int
    theme: str
    price_per_month: float

class SubscriptionCreate(BaseModel):
    user_id: int
    plan_id: int
    start_date: str

class SubscriptionUpdate(BaseModel):
    plan_id: Optional[int] = None
    delivery_frequency_days: Optional[int] = None
    theme: Optional[str] = None

class CancelSubscription(BaseModel):
    cancellation_date: str

def get_user_id_from_token(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/plans")
def create_plan(plan: PlanCreate, authorization: str = Header(...)):
    get_user_id_from_token(authorization)
    global next_plan_id
    plan_id = next_plan_id
    next_plan_id += 1
    plans[plan_id] = {
        "id": plan_id,
        "name": plan.name,
        "delivery_frequency_days": plan.delivery_frequency_days,
        "theme": plan.theme,
        "price_per_month": plan.price_per_month
    }
    return plans[plan_id]

@app.get("/plans/{plan_id}")
def get_plan(plan_id: int, authorization: str = Header(...)):
    get_user_id_from_token(authorization)
    plan = plans.get(plan_id)
    if not plan:
        raise HTTPException(status_code=404, detail="Plan not found")
    return plan

@app.post("/subscriptions")
def create_subscription(sub: SubscriptionCreate, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    if sub.user_id != user_id:
        raise HTTPException(status_code=403, detail="Cannot create subscription for another user")
    if sub.plan_id not in plans:
        raise HTTPException(status_code=404, detail="Plan not found")
    global next_sub_id
    sub_id = next_sub_id
    next_sub_id += 1
    subscriptions[sub_id] = {
        "id": sub_id,
        "user_id": sub.user_id,
        "plan_id": sub.plan_id,
        "start_date": sub.start_date,
        "delivery_frequency_days": plans[sub.plan_id]["delivery_frequency_days"],
        "theme": plans[sub.plan_id]["theme"],
        "price_per_month": plans[sub.plan_id]["price_per_month"],
        "active": True
    }
    return subscriptions[sub_id]

@app.get("/subscriptions/{sub_id}")
def get_subscription(sub_id: int, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    sub = subscriptions.get(sub_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    if sub["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your subscription")
    return sub

@app.patch("/subscriptions/{sub_id}")
def update_subscription(sub_id: int, update: SubscriptionUpdate, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    sub = subscriptions.get(sub_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    if sub["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your subscription")
    if update.plan_id is not None:
        if update.plan_id not in plans:
            raise HTTPException(status_code=404, detail="Plan not found")
        sub["plan_id"] = update.plan_id
        sub["delivery_frequency_days"] = plans[update.plan_id]["delivery_frequency_days"]
        sub["theme"] = plans[update.plan_id]["theme"]
        sub["price_per_month"] = plans[update.plan_id]["price_per_month"]
    if update.delivery_frequency_days is not None:
        sub["delivery_frequency_days"] = update.delivery_frequency_days
    if update.theme is not None:
        sub["theme"] = update.theme
    return sub

@app.post("/subscriptions/{sub_id}/cancel")
def cancel_subscription(sub_id: int, cancel: CancelSubscription, authorization: str = Header(...)):
    user_id = get_user_id_from_token(authorization)
    sub = subscriptions.get(sub_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    if sub["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your subscription")
    if not sub["active"]:
        raise HTTPException(status_code=400, detail="Already cancelled")
