def signup(req: dict):
    global user_counter
    username = req.get("username")
    password = req.get("password")
    if not username or not password:
        raise HTTPException(status_code=400, detail="username and password required")
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="username taken")
    user_counter += 1
    user = {"id": user_counter, "username": username, "password": password}
    for k, v in req.items():
        if k not in ("username", "password"):
            user[k] = v
    users[user_counter] = user
    return user


@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="invalid credentials")


@app.post("/polls")
def create_poll(req: dict, authorization: str = Header(None)):
    global poll_counter
    user_id = get_user_from_token(authorization)
    question = req.get("question")
    options = req.get("options")
    if not question or not options:
        raise HTTPException(status_code=400, detail="question and options required")
    poll_counter += 1
    poll = {
        "id": poll_counter,
        "user_id": user_id,
        "question": question,
        "options": options,
        "results": {opt: 0 for opt in options},
    }
    for k, v in req.items():
        if k not in ("question", "options"):
            poll[k] = v
    polls[poll_counter] = poll
    return poll


