from datetime import datetime, timedelta
import random
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
shipments = {}
shipment_id_counter = 1

def auth(token: str = Header(...)):
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = hashlib.sha256(password.encode()).hexdigest()
    return {"ok": True}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != hashlib.sha256(password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Bad credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

@app.post("/shipments")
def create_shipment(origin: str, destination: str, weight: float, token: str = Header(...)):
    auth(token)
    global shipment_id_counter
    sid = shipment_id_counter
    shipment_id_counter += 1
    now = datetime.utcnow()
    eta = now + timedelta(days=random.randint(1, 5))
    shipments[sid] = {
        "id": sid,
        "origin": origin,
        "destination": destination,
        "weight": weight,
        "current_location": origin,
        "estimated_delivery": eta.isoformat(),
        "delays": [],
        "created_at": now.isoformat(),
        "owner": tokens[token]
    }
    return shipments[sid]

@app.get("/shipments/{sid}/status")
def get_shipment_status(sid: int, token: str = Header(...)):
    auth(token)
    if sid not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    s = shipments[sid]
    return {
        "current_location": s["current_location"],
        "estimated_delivery": s["estimated_delivery"],
        "delays": s["delays"]
    }

