import os
import uuid
from fastapi import FastAPI, UploadFile, File, Form, HTTPException, Header
from fastapi.responses import FileResponse
from pydantic import BaseModel
import shutil

app = FastAPI()

users = {}
photos = {}
tokens = {}
photo_id_counter = 1
user_id_counter = 1
UPLOAD_DIR = "fitness_uploads"
os.makedirs(UPLOAD_DIR, exist_ok=True)

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"username": req.username, "password": req.password, "id": user_id}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}/photos/{filename}")
def get_photo(user_id: int, filename: str, authorization: str = Header(None)):
    get_user_from_token(authorization)
    filepath = os.path.join(UPLOAD_DIR, filename)
    if not os.path.exists(filepath):
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(filepath)

@app.post("/users/{user_id}/photos")
async def upload_photo(user_id: int, file: UploadFile = File(...), notes: str = Form(""), authorization: str = Header(None)):
    get_user_from_token(authorization)
    global photo_id_counter
    ext = file.filename.split(".")[-1] if "." in file.filename else "jpg"
    filename = f"photo_{photo_id_counter}_{uuid.uuid4().hex[:8]}.{ext}"
    filepath = os.path.join(UPLOAD_DIR, filename)
    with open(filepath, "wb") as f:
        shutil.copyfileobj(file.file, f)
    photo_id = photo_id_counter
    photo_id_counter += 1
    photos[photo_id] = {"id": photo_id, "user_id": user_id, "filename": filename, "notes": notes}
    return {"photo_id": photo_id, "filename": filename}

@app.get("/photos/{photo_id}")
def get_photo_by_id(photo_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
