from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from datetime import datetime, timedelta
import secrets
import threading

app = FastAPI()

users = {}
tokens = {}
shows = {}
tiers = {}
reservations = {}
reservation_locks = {}
reservation_timers = {}

show_id_counter = 0
tier_id_counter = 0
reservation_id_counter = 0
user_id_counter = 0

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ShowCreate(BaseModel):
    name: str
    date: str
    venue: str

class TierCreate(BaseModel):
    show_id: int
    name: str
    price: float
    capacity: int

class ReserveRequest(BaseModel):
    show_id: int
    tier_id: int
    quantity: int

def require_auth(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id_counter += 1
    users[user_id_counter] = {"id": user_id_counter, "username": req.username, "password": req.password}
    return {"id": user_id_counter, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/shows/{show_id}")
def get_show(show_id: int):
    if show_id not in shows:
        raise HTTPException(status_code=404, detail="Show not found")
    return shows[show_id]

@app.post("/shows")
def create_show(show: ShowCreate):
    global show_id_counter
    show_id_counter += 1
    shows[show_id_counter] = {"id": show_id_counter, "name": show.name, "date": show.date, "venue": show.venue}
    return shows[show_id_counter]

@app.get("/tiers/{tier_id}")
def get_tier(tier_id: int):
    if tier_id not in tiers:
        raise HTTPException(status_code=404, detail="Tier not found")
    return tiers[tier_id]

@app.post("/tiers")
def create_tier(tier: TierCreate):
    global tier_id_counter
    if tier.show_id not in shows:
        raise HTTPException(status_code=404, detail="Show not found")
    tier_id_counter += 1
    tiers[tier_id_counter] = {"id": tier_id_counter, "show_id": tier.show_id, "name": tier.name, "price": tier.price, "capacity": tier.capacity, "reserved": 0}
    return tiers[tier_id_counter]

@app.get("/reservations/{reservation_id}")
def get_reservation(reservation_id: int, authorization: str = Header(None)):
    user_id = require_auth(authorization)
    if reservation_id not in reservations:
        raise HTTPException(status_code=404, detail="Reservation not found")
    return reservations[reservation_id]

@app.post("/reservations")
def reserve(req: ReserveRequest, authorization: str = Header(None)):
    global reservation_id_counter
    user_id = require_auth(authorization)
    if req.show_id not in shows:
        raise HTTPException(status_code=404, detail="Show not found")
    if req.tier_id not in tiers:
        raise HTTPException(status_code=404, detail="Tier not found")
    tier = tiers[req.tier_id]
    if tier["show_id"] != req.show_id:
        raise HTTPException(status_code=400, detail="Tier does not belong to this show")

