    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password,
        "role": req.role
    }
    return {"id": user_id, "username": req.username, "role": req.role}

@app.post("/login")
