import uuid
import secrets

app = FastAPI()

users = {}
tokens = {}
orders = {}
next_user_id = 1
next_order_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class OrderCreate(BaseModel):
    item: str
    quantity: int

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = next_user_id
    next_user_id += 1
    users[req.username] = {"id": user_id, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing token")
    token = authorization.replace("Bearer ", "")
    username = tokens.get(token)
    if not username:
        raise HTTPException(status_code=401, detail="Invalid token")
    return username

@app.post("/orders")
def create_order(order: OrderCreate, authorization: Optional[str] = Header(None)):
    username = get_current_user(authorization)
    global next_order_id
    order_id = next_order_id
    next_order_id += 1
    orders[order_id] = {"id": order_id, "item": order.item, "quantity": order.quantity, "owner": username}
    return orders[order_id]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    username = get_current_user(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    if order["owner"] != username:
        raise HTTPException(status_code=403, detail="Access denied")
    return order

