from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
properties = {}
next_user_id = 1
next_property_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PropertyCreate(BaseModel):
    name: str
    address: str
    rent_amount: float
    status: Optional[str] = "active"
    manager_id: Optional[int] = None

class PropertyUpdate(BaseModel):
    name: Optional[str] = None
    address: Optional[str] = None
    rent_amount: Optional[float] = None
    status: Optional[str] = None
    manager_id: Optional[int] = None

def get_current_user(token: str = Header(...)):
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/properties")
def create_property(req: PropertyCreate, token: str = Header(...)):
    get_current_user(token)
    global next_property_id
    prop_id = next_property_id
    next_property_id += 1
    properties[prop_id] = {
        "id": prop_id,
        "name": req.name,
        "address": req.address,
        "rent_amount": req.rent_amount,
        "status": req.status,
        "manager_id": req.manager_id
    }
    return properties[prop_id]

@app.get("/properties/{prop_id}")
def get_property(prop_id: int, token: str = Header(...)):
    get_current_user(token)
    if prop_id not in properties:
        raise HTTPException(status_code=404, detail="Property not found")
    return properties[prop_id]

@app.patch("/properties/{prop_id}")
def update_property(prop_id: int, req: PropertyUpdate, token: str = Header(...)):
    get_current_user(token)
    if prop_id not in properties:
        raise HTTPException(status_code=404, detail="Property not found")
    prop = properties[prop_id]
    if req.name is not None:
        prop["name"] = req.name
    if req.address is not None:
        prop["address"] = req.address
    if req.rent_amount is not None:
        prop["rent_amount"] = req.rent_amount
    if req.status is not None:
        prop["status"] = req.status
    if req.manager_id is not None:
        prop["manager_id"] = req.manager_id
    return prop

