import sys
import requests

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Signup
    signup_resp = session.post(f"{BASE_URL}/signup", json={
        "username": "testuser",
        "password": "testpass"
    })
    if signup_resp.status_code != 200:
        return False
    user_data = signup_resp.json()
    if "id" not in user_data or "username" not in user_data:
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", json={
        "username": "testuser",
        "password": "testpass"
    })
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Create property
    headers = {"token": token}
    create_resp = session.post(f"{BASE_URL}/properties", json={
        "name": "Test Property",
        "address": "123 Main St",
        "rent_amount": 1500.0
    }, headers=headers)
    if create_resp.status_code != 200:
        return False
    prop_data = create_resp.json()
    prop_id = prop_data.get("id")
    if not prop_id:
        return False

    # Fetch own property
    fetch_resp = session.get(f"{BASE_URL}/properties/{prop_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    fetched = fetch_resp.json()
    if fetched.get("id") != prop_id:
        return False
    if fetched.get("name") != "Test Property":
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

