    session = requests.Session()

    # Signup
    signup_data = {"username": "testuser", "password": "testpass123"}
    resp = session.post(f"{BASE_URL}/signup", json=signup_data)
    if resp.status_code != 200:
        return False
    token = resp.json().get("token")
    if not token:
        return False

    # Login
    login_data = {"username": "testuser", "password": "testpass123"}
    resp = session.post(f"{BASE_URL}/login", json=login_data)
    if resp.status_code != 200:
        return False
    token = resp.json().get("token")
    if not token:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Create a trail
    trail_data = {
        "name": "Test Trail",
        "difficulty": "easy",
        "length": 5.0,
        "is_dog_friendly": True,
        "region": "Test Region"
    }
    resp = session.post(f"{BASE_URL}/trails", json=trail_data, headers=headers)
    if resp.status_code != 200:
        return False
    trail = resp.json()
    trail_id = trail.get("id")
    if not trail_id:
        return False

    # Fetch own trail
    resp = session.get(f"{BASE_URL}/trails/{trail_id}", headers=headers)
    if resp.status_code != 200:
        return False
    fetched_trail = resp.json()
    if fetched_trail.get("name") != "Test Trail":
        return False
    if fetched_trail.get("id") != trail_id:
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

