    if r.status_code not in (200, 201):
        return False

    # Login
    r = session.post(f"{BASE_URL}/login", params={"username": "testuser", "password": "pass123"})
    if r.status_code != 200:
        return False
    token = r.json().get("token")
    if not token:
        return False

    # Create alert
    headers = {"Authorization": f"Bearer {token}"}
    r = session.post(f"{BASE_URL}/alerts", params={"location": "CityA", "condition": "Rain"}, headers=headers)
    if r.status_code != 200:
        return False
    alert_data = r.json()
    alert_id = alert_data.get("id")
    if not alert_id:
        return False

    # Fetch own alert by ID
    r = session.get(f"{BASE_URL}/alerts/{alert_id}", headers=headers)
    if r.status_code != 200:
        return False
    fetched = r.json()
    if fetched.get("user") != "testuser":
        return False

