    get_current_user(authorization)
    global session_id_counter
    session_id = session_id_counter
    session_id_counter += 1
    sessions[session_id] = {
        "id": session_id,
        "name": req.name,
        "time": req.time,
        "style": req.style,
        "level": req.level,
        "max_capacity": req.max_capacity
    }
