import uuid
import json

app = FastAPI()

users = {}
rides = {}
tokens = {}
user_id_counter = 1
ride_id_counter = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for user in users.values():
        if user["username"] == username and user["password"] == password:
            token = str(uuid.uuid4())
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.get("/rides/{ride_id}")
def get_ride(ride_id: int):
    if ride_id not in rides:
        raise HTTPException(status_code=404, detail="Ride not found")
    return rides[ride_id]

@app.post("/rides")
def create_ride(start_location: str, time: str, seats: int, authorization: Optional[str] = Header(None)):
    driver_id = get_current_user(authorization)
    global ride_id_counter
    ride_id = ride_id_counter
    ride_id_counter += 1
    rides[ride_id] = {
        "id": ride_id,
        "start_location": start_location,
        "time": time,
        "seats": seats,
        "status": "active",
        "driver_id": driver_id
    }
    return rides[ride_id]

@app.patch("/rides/{ride_id}")
def update_ride(ride_id: int, start_location: Optional[str] = None, time: Optional[str] = None, seats: Optional[int] = None, status: Optional[str] = None, driver_id: Optional[int] = None, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if ride_id not in rides:
        raise HTTPException(status_code=404, detail="Ride not found")
    ride = rides[ride_id]
    if user_id != ride["driver_id"]:
        raise HTTPException(status_code=403, detail="Not authorized to modify this ride")
    if start_location is not None:
        ride["start_location"] = start_location
    if time is not None:
        ride["time"] = time
    if seats is not None:
        ride["seats"] = seats
    if status is not None:
        ride["status"] = status
    if driver_id is not None:
        ride["driver_id"] = driver_id
    return ride

