from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import hashlib

app = FastAPI()

users = {}
tokens = {}
trails = {}
trail_id_counter = 0

def auth_token_required(authorization: str = Header(...)):
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TrailCreate(BaseModel):
    name: str
    difficulty: str
    length: float
    is_dog_friendly: Optional[bool] = False
    region: Optional[str] = "unknown"

class TrailUpdate(BaseModel):
    name: Optional[str] = None
    difficulty: Optional[str] = None
    length: Optional[float] = None
    is_dog_friendly: Optional[bool] = None
    region: Optional[str] = None

@app.post("/signup")
def signup(user: UserSignup):
    if user.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[user.username] = hashlib.sha256(user.password.encode()).hexdigest()
    return {"message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    if user.username not in users:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    if users[user.username] != hashlib.sha256(user.password.encode()).hexdigest():
        raise HTTPException(status_code=400, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = user.username
    return {"token": token}

@app.get("/trails/{trail_id}")
def get_trail(trail_id: int, authorization: str = Header(...)):
    auth_token_required(authorization)
    if trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    return trails[trail_id]

@app.post("/trails")
def create_trail(trail: TrailCreate, authorization: str = Header(...)):
    auth_token_required(authorization)
    global trail_id_counter
    trail_id_counter += 1
    trails[trail_id_counter] = trail.dict()
    trails[trail_id_counter]["id"] = trail_id_counter
    return trails[trail_id_counter]

@app.patch("/trails/{trail_id}")
def update_trail(trail_id: int, trail: TrailUpdate, authorization: str = Header(...)):
    auth_token_required(authorization)
    if trail_id not in trails:
        raise HTTPException(status_code=404, detail="Trail not found")
    for key, value in trail.dict(exclude_unset=True).items():
        trails[trail_id][key] = value
    return trails[trail_id]

