from pydantic import BaseModel
from typing import Optional, Dict
import secrets

app = FastAPI()

# In-memory stores
users: Dict[int, dict] = {}
subscribers: Dict[int, dict] = {}
tokens: Dict[str, int] = {}  # token -> user_id
next_user_id = 1
next_subscriber_id = 1

# Auth helper
def get_user_id(authorization: str = Header(...)) -> int:
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

# User models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

# Endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Subscriber models
class SubscriberCreate(BaseModel):
    name: str
    email: str
    tier: Optional[str] = "free"
    is_active: Optional[bool] = True

class SubscriberUpdate(BaseModel):
    name: Optional[str] = None
    email: Optional[str] = None
    tier: Optional[str] = None
    is_active: Optional[bool] = None

@app.post("/subscribers")
def create_subscriber(req: SubscriberCreate, authorization: str = Header(...)):
    get_user_id(authorization)
    global next_subscriber_id
    sub_id = next_subscriber_id
    next_subscriber_id += 1
    subscribers[sub_id] = {
        "id": sub_id,
        "name": req.name,
        "email": req.email,
        "tier": req.tier,
        "is_active": req.is_active
    }
    return subscribers[sub_id]

@app.get("/subscribers/{sub_id}")
def get_subscriber(sub_id: int, authorization: str = Header(...)):
    get_user_id(authorization)
    sub = subscribers.get(sub_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscriber not found")
    return sub

@app.patch("/subscribers/{sub_id}")
def update_subscriber(sub_id: int, req: SubscriberUpdate, authorization: str = Header(...)):
    get_user_id(authorization)
    sub = subscribers.get(sub_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscriber not found")
    if req.name is not None:
        sub["name"] = req.name
    if req.email is not None:
        sub["email"] = req.email
    if req.tier is not None:
        sub["tier"] = req.tier
    if req.is_active is not None:
        sub["is_active"] = req.is_active
    return sub

