from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
poems = {}
poem_id_counter = 1

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Unauthorized")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[username] = hash_password(password)
    token = secrets.token_hex(32)
    tokens[token] = username
    return {"token": token}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = username
    return {"token": token}

@app.get("/poems/{poem_id}")
def get_poem(poem_id: int):
    if poem_id not in poems:
        raise HTTPException(status_code=404, detail="Poem not found")
    return poems[poem_id]

@app.post("/poems")
def create_poem(title: str, text: str, is_public: bool = True, theme: str = "default", authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    global poem_id_counter
    poem_id = poem_id_counter
    poem_id_counter += 1
    poems[poem_id] = {
        "id": poem_id,
        "title": title,
        "text": text,
        "is_public": is_public,
        "theme": theme,
        "author": user
    }
    return poems[poem_id]

@app.patch("/poems/{poem_id}")
def update_poem(poem_id: int, title: Optional[str] = None, text: Optional[str] = None, is_public: Optional[bool] = None, theme: Optional[str] = None, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if poem_id not in poems:
        raise HTTPException(status_code=404, detail="Poem not found")
    if poems[poem_id]["author"] != user:
        raise HTTPException(status_code=403, detail="Not your poem")
    if title is not None:
        poems[poem_id]["title"] = title
    if text is not None:
        poems[poem_id]["text"] = text
    if is_public is not None:
        poems[poem_id]["is_public"] = is_public
    if theme is not None:
