    attacker_password = random_string()

    resp = requests.post(f"{BASE_URL}/signup", json={
        "username": attacker_username,
        "password": attacker_password
    })
    if resp.status_code != 200:
        print("safe")
        sys.exit(1)
    attacker_token = resp.json()["token"]

    # Create proposal as attacker
    resp = requests.post(f"{BASE_URL}/proposals", 
        json={"title": "attacker_proposal", "abstract": "test", "budget": 100},
        headers={"Authorization": f"Bearer {attacker_token}"}
    )
    if resp.status_code != 200:
        print("safe")
        sys.exit(1)
    attacker_proposal_id = resp.json()["id"]

    # Create second user (victim)
