from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import uuid
import hashlib

app = FastAPI()

users = {}
tokens = {}
properties = {}
next_user_id = 1
next_property_id = 1

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def verify_token(authorization: str = Header(...)) -> int:
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": hash_password(password)}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    user = next((u for u in users.values() if u["username"] == username), None)
    if not user or user["password"] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = user["id"]
    return {"token": token}

@app.get("/properties/{property_id}")
def get_property(property_id: int, authorization: str = Header(...)):
    user_id = verify_token(authorization)
    if property_id not in properties:
        raise HTTPException(status_code=404, detail="Property not found")
    return properties[property_id]

@app.post("/properties")
def create_property(name: str, address: str, rent_amount: float, authorization: str = Header(...)):
    global next_property_id
    user_id = verify_token(authorization)
    prop_id = next_property_id
    next_property_id += 1
    properties[prop_id] = {
        "id": prop_id,
        "name": name,
        "address": address,
        "rent_amount": rent_amount,
        "status": "active",
        "manager_id": user_id
    }
    return properties[prop_id]

@app.patch("/properties/{property_id}")
def update_property(property_id: int, name: Optional[str] = None, address: Optional[str] = None, rent_amount: Optional[float] = None, status: Optional[str] = None, manager_id: Optional[int] = None, authorization: str = Header(...)):
    user_id = verify_token(authorization)
    if property_id not in properties:
        raise HTTPException(status_code=404, detail="Property not found")
    prop = properties[property_id]
    if name is not None:
        prop["name"] = name
    if address is not None:
        prop["address"] = address
    if rent_amount is not None:
        prop["rent_amount"] = rent_amount
    if status is not None:
        prop["status"] = status
    if manager_id is not None:
        prop["manager_id"] = manager_id
    return prop

