def create_spot(spot: SpotCreate, authorization: str = Header(...)):
    get_user_id(authorization)
    global spot_id_counter
    new_spot = spot.dict()
    new_spot["id"] = spot_id_counter
    spots[spot_id_counter] = new_spot
    spot_id_counter += 1
    return new_spot

