    user_id = get_current_user(authorization)
    global next_trip_id
    trip_id = next_trip_id
    next_trip_id += 1
    trips[trip_id] = {
        "id": trip_id,
        "name": name,
        "destination": destination,
        "start_date": start_date,
        "end_date": end_date,
        "created_by": user_id
    }
    # Add creator as participant with role "organizer"
    global next_participant_id
    participant_id = next_participant_id
    next_participant_id += 1
    trip_participants[participant_id] = {
        "id": participant_id,
        "trip_id": trip_id,
        "user_id": user_id,
        "role": "organizer",
        "budget": 0.0
    }
    return trips[trip_id]

