    if destination is not None:
        trip["destination"] = destination
    if start_date is not None:
        trip["start_date"] = start_date
    if end_date is not None:
        trip["end_date"] = end_date
    if participant_id is not None and participant_id in trip_participants and trip_participants[participant_id]["trip_id"] == trip_id:
        if role is not None:
            trip_participants[participant_id]["role"] = role
        if budget is not None:
            trip_participants[participant_id]["budget"] = budget
    return trip

