    trip_copy["participants"] = [p for p in trip_participants.values() if p["trip_id"] == trip_id]
    return trip_copy

@app.post("/trips")
def create_trip(name: str, destination: str, start_date: str, end_date: str, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_trip_id
    trip_id = next_trip_id
    next_trip_id += 1
    trips[trip_id] = {
        "id": trip_id,
        "name": name,
        "destination": destination,
        "start_date": start_date,
        "end_date": end_date,
        "created_by": user_id
    }
    # Add creator as participant with role "organizer"
    global next_participant_id
    participant_id = next_participant_id
    next_participant_id += 1
    trip_participants[participant_id] = {
        "id": participant_id,
        "trip_id": trip_id,
        "user_id": user_id,
        "role": "organizer",
        "budget": 0.0
    }
    return trips[trip_id]

@app.patch("/trips/{trip_id}")
def update_trip(trip_id: int, name: Optional[str] = None, destination: Optional[str] = None, 
                start_date: Optional[str] = None, end_date: Optional[str] = None, 
                participant_id: Optional[int] = None, role: Optional[str] = None, 
                budget: Optional[float] = None, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    # Check if user is a participant of this trip
    participant_ids = [p["id"] for p in trip_participants.values() if p["trip_id"] == trip_id and p["user_id"] == user_id]
    if not participant_ids:
        raise HTTPException(status_code=403, detail="Access denied")
    trip = trips[trip_id]
    if name is not None:
        trip["name"] = name
    if destination is not None:
        trip["destination"] = destination
    if start_date is not None:
        trip["start_date"] = start_date
    if end_date is not None:
        trip["end_date"] = end_date
    if participant_id is not None and participant_id in trip_participants and trip_participants[participant_id]["trip_id"] == trip_id:
        # Additional check: only allow updating own participant record unless user is organizer
        participant_user_id = trip_participants[participant_id]["user_id"]
        is_organizer = any(p["user_id"] == user_id and p["role"] == "organizer" for p in trip_participants.values() if p["trip_id"] == trip_id)
        if participant_user_id != user_id and not is_organizer:
            raise HTTPException(status_code=403, detail="Cannot modify other participants")
        if role is not None:
            # Only organizers can change roles
            if not is_organizer and role != trip_participants[participant_id]["role"]:
                raise HTTPException(status_code=403, detail="Only organizers can change roles")
            trip_participants[participant_id]["role"] = role
        if budget is not None:
            trip_participants[participant_id]["budget"] = budget
    return trip

