courses = {}
registrations = {}
tokens = {}
user_id_counter = 1
course_id_counter = 1
registration_id_counter = 1
token_counter = 1

def get_user_from_token(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(name: str, email: str):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "name": name, "email": email}
    return {"id": user_id, "name": name, "email": email}

@app.post("/login")
def login(email: str, name: str):
    for uid, u in users.items():
        if u["email"] == email and u["name"] == name:
            global token_counter
            token = f"tok_{token_counter}"
            token_counter += 1
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/courses")
def create_course(name: str, capacity: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    global course_id_counter
    course_id = course_id_counter
    course_id_counter += 1
    courses[course_id] = {"id": course_id, "name": name, "capacity": capacity}
    return {"id": course_id, "name": name, "capacity": capacity}

@app.post("/register")
def register(student_name: str, course_id: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    course = courses[course_id]
    count = sum(1 for r in registrations.values() if r["course_id"] == course_id)
    if count >= course["capacity"]:
        raise HTTPException(status_code=400, detail="Course full")
    global registration_id_counter
    reg_id = registration_id_counter
    registration_id_counter += 1
    registrations[reg_id] = {"id": reg_id, "student_name": student_name, "course_id": course_id}
    return {"id": reg_id, "student_name": student_name, "course_id": course_id}

