    get_user_from_token(authorization)
    result = []
    for cid, course in courses.items():
        count = sum(1 for r in registrations.values() if r["course_id"] == cid)
        result.append({"id": cid, "name": course["name"], "capacity": course["capacity"], "enrolled": count})
    return result

@app.get("/courses/{course_id}")
def get_course(course_id: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    course = courses[course_id]
    count = sum(1 for r in registrations.values() if r["course_id"] == course_id)
    return {"id": course_id, "name": course["name"], "capacity": course["capacity"], "enrolled": count}

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_user_from_token(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
