poll_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreatePollRequest(BaseModel):
    question: str
    options: list[str]

class VoteRequest(BaseModel):
    choice: int

def get_user_from_token(authorization: Optional[str] = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid token")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = req.password
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/polls")
def create_poll(req: CreatePollRequest, authorization: Optional[str] = Header(None)):
    user = get_user_from_token(authorization)
    global poll_id_counter
    poll_id = poll_id_counter
    poll_id_counter += 1
    polls[poll_id] = {
        "id": poll_id,
        "question": req.question,
        "options": {i: {"text": opt, "votes": 0} for i, opt in enumerate(req.options)},
        "voters": {}
    }
    return {"id": poll_id, "question": req.question, "options": req.options}

@app.post("/polls/{poll_id}/vote")
def vote(poll_id: int, req: VoteRequest, authorization: Optional[str] = Header(None)):
    user = get_user_from_token(authorization)
    if poll_id not in polls:
        raise HTTPException(status_code=404, detail="Poll not found")
    poll = polls[poll_id]
    if user in poll["voters"]:
        raise HTTPException(status_code=400, detail="Already voted")
    if req.choice not in poll["options"]:
        raise HTTPException(status_code=400, detail="Invalid choice")
    poll["options"][req.choice]["votes"] += 1
    poll["voters"][user] = req.choice
    return {"message": "Vote recorded"}

@app.get("/polls/{poll_id}")
def get_poll(poll_id: int, authorization: Optional[str] = Header(None)):
    user = get_user_from_token(authorization)
    if poll_id not in polls:
