from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import random
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
vocab = {}
vocab_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class VocabEntry(BaseModel):
    word: str
    translation: str
    language: str

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(16)

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = hash_password(req.password)
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/vocab")
def create_vocab(entry: VocabEntry, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global vocab_id_counter
    vocab[vocab_id_counter] = entry.dict()
    vocab[vocab_id_counter]["id"] = vocab_id_counter
    vocab_id_counter += 1
    return {"id": vocab_id_counter - 1}

@app.get("/vocab/{id}")
def get_vocab(id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if id not in vocab:
        raise HTTPException(status_code=404, detail="Vocab not found")
    return vocab[id]

@app.get("/vocab/quiz")
def get_quiz(authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if len(vocab) < 10:
        raise HTTPException(status_code=400, detail="Not enough vocab entries")
    sample = random.sample(list(vocab.values()), 10)
    result = []
    for item in sample:
        result.append({
            "id": item["id"],
            "word": item["word"],
            "translation": item["translation"],
            "language": item["language"]
        })
    return result

