    # Create attacker user
    attacker_user = random_username()
    attacker_pass = random_password()
    attacker_token = signup(session, attacker_user, attacker_pass)

    # Try to access victim's sighting by ID using attacker token
    # This is an IDOR test: attacker should not be able to see victim's sighting
    # But the app only checks authentication, not authorization
    stolen_sighting = get_sighting(session, attacker_token, victim_sighting_id)

    if stolen_sighting and stolen_sighting.get("user") == victim_user:
        print("PWNED")
