from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
sessions = {}
next_user_id = 1
next_session_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class SessionCreate(BaseModel):
    client_name: str
    goal: str
    schedule: str
    coach_access_tier: str

class SessionUpdate(BaseModel):
    client_name: Optional[str] = None
    goal: Optional[str] = None
    schedule: Optional[str] = None
    coach_access_tier: Optional[str] = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/sessions")
def create_session(req: SessionCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_session_id
    session_id = next_session_id
    next_session_id += 1
    sessions[session_id] = {
        "id": session_id,
        "user_id": user_id,
        "client_name": req.client_name,
        "goal": req.goal,
        "schedule": req.schedule,
        "coach_access_tier": req.coach_access_tier
    }
    return sessions[session_id]

@app.get("/sessions/{session_id}")
def get_session(session_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    session = sessions.get(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")
    if session["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return session

@app.put("/sessions/{session_id}")
def update_session(session_id: int, req: SessionUpdate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    session = sessions.get(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")
    if session["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    if req.client_name is not None:
        session["client_name"] = req.client_name
    if req.goal is not None:
        session["goal"] = req.goal
    if req.schedule is not None:
        session["schedule"] = req.schedule
    if req.coach_access_tier is not None:
        session["coach_access_tier"] = req.coach_access_tier
    return session

