from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import secrets
import hashlib

app = FastAPI()

users = {}
tokens = {}
prescriptions = {}
prescription_id_counter = 1

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token():
    return secrets.token_hex(32)

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = {"username": username, "password": hash_password(password)}
    return {"message": "User created"}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username]["password"] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = username
    return {"token": token}

@app.get("/prescriptions/{prescription_id}")
def get_prescription(prescription_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if prescription_id not in prescriptions:
        raise HTTPException(status_code=404, detail="Prescription not found")
    return prescriptions[prescription_id]

@app.post("/prescriptions")
def create_prescription(medication: str, dosage: str, refills: int, days_supply: int, authorization: str = Header(...)):
    get_current_user(authorization)
    global prescription_id_counter
    pid = prescription_id_counter
    prescription_id_counter += 1
    prescriptions[pid] = {
        "id": pid,
        "medication": medication,
        "dosage": dosage,
        "refills": refills,
        "days_supply": days_supply,
        "created_at": datetime.now().isoformat()
    }
    return prescriptions[pid]

@app.get("/prescriptions")
def list_prescriptions(authorization: str = Header(...)):
    get_current_user(authorization)
    result = []
    for pid, p in prescriptions.items():
        days_remaining = p["days_supply"] - (datetime.now() - datetime.fromisoformat(p["created_at"])).days
        result.append({
            "id": pid,
            "medication": p["medication"],
            "dosage": p["dosage"],
            "refills": p["refills"],
            "days_remaining": max(0, days_remaining)
        })
    return result

@app.patch("/prescriptions")
def bulk_update_prescriptions(updates: list[dict], authorization: str = Header(...)):
    get_current_user(authorization)
    for update in updates:
        pid = update.get("id")
        if pid not in prescriptions:
            continue
        if "refills" in update:
            prescriptions[pid]["refills"] = update["refills"]
        if "days_supply" in update:
            prescriptions[pid]["days_supply"] = update["days_supply"]
    return {"message": "Updated"}

