from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import random
import hashlib
import time
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
exercises = [
    {"name": "Push-ups", "sets": 3, "reps": 15, "calories": 30},
    {"name": "Squats", "sets": 4, "reps": 20, "calories": 40},
    {"name": "Plank", "sets": 3, "reps": "30s", "calories": 20},
    {"name": "Burpees", "sets": 3, "reps": 10, "calories": 50},
    {"name": "Lunges", "sets": 3, "reps": 12, "calories": 35},
    {"name": "Mountain Climbers", "sets": 3, "reps": 20, "calories": 45},
    {"name": "Dumbbell Rows", "sets": 3, "reps": 12, "calories": 25},
    {"name": "Bicycle Crunches", "sets": 3, "reps": 15, "calories": 20},
]
workout_id_counter = 1
workouts = {}
log_id_counter = 1
logs = {}
user_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class LogRequest(BaseModel):
    duration: int

def auth_user(token: str = Header(...)):
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[req.username] = {"id": user_id, "password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    if users[req.username]["password"] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(status_code=400, detail="Invalid credentials")
    token = hashlib.md5(f"{req.username}{time.time()}".encode()).hexdigest()
    tokens[token] = req.username
    return {"token": token}

@app.get("/workout")
def get_workout(token: str = Header(...)):
    auth_user(token)
    exercise = random.choice(exercises)
    return exercise

@app.post("/log")
def log_workout(req: LogRequest, token: str = Header(...)):
    global log_id_counter
    username = auth_user(token)
    log_id = log_id_counter
    log_id_counter += 1
    logs[log_id] = {"id": log_id, "username": username, "duration": req.duration, "timestamp": time.time()}
    return {"id": log_id, "duration": req.duration}

@app.get("/log/{log_id}")
def get_log(log_id: int, token: str = Header(...)):
    auth_user(token)
    if log_id not in logs:
        raise HTTPException(status_code=404, detail="Log not found")
    return logs[log_id]

