def create_user(req: SignupRequest):
    return signup(req)

@app.get("/matches")
def get_matches(authorization: str = Header(None)):
    current_user_id = get_user_id(authorization)
    current_user = users[current_user_id]

    potential_matches = []
    for uid, u in users.items():
        if uid == current_user_id:
            continue

        # Compatibility score based on shared interests
        shared = set(current_user["interests"]) & set(u["interests"])
        compatibility = len(shared) / max(len(current_user["interests"]), 1) * 100

        # Distance calculation (simplified)
        lat1, lon1 = current_user["latitude"], current_user["longitude"]
        lat2, lon2 = u["latitude"], u["longitude"]
        distance = math.sqrt((lat1 - lat2)**2 + (lon1 - lon2)**2) * 111  # rough km

        potential_matches.append({
            "user_id": uid,
            "name": u["name"],
            "compatibility_score": round(compatibility, 1),
            "distance_km": round(distance, 1),
            "shared_interests": list(shared)
        })

    # Sort by compatibility descending
    potential_matches.sort(key=lambda x: x["compatibility_score"], reverse=True)
    return {"matches": potential_matches[:20]}  # top 20

@app.post("/matches")
def create_match(match: Match, authorization: str = Header(None)):
    global next_match_id
    current_user_id = get_user_id(authorization)

    if match.user_id not in users:
        raise HTTPException(status_code=404, detail="Target user not found")

    match_id = next_match_id
    next_match_id += 1
    matches[match_id] = {
        "id": match_id,
        "user_id": current_user_id,
        "target_user_id": match.user_id,
        "status": match.status,
        "created_at": datetime.now().isoformat()
    }
    return {"match_id": match_id}

@app.get("/matches/{match_id}")
def get_match(match_id: int, authorization: str = Header(None)):
    get_user_id(authorization)
    if match_id not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    return matches[match_id]

@app.post("/feedback")
def feedback(req: FeedbackRequest):
    if req.match_id not in matches:
        raise HTTPException(status_code=404, detail="Match not found")
    if req.thumbs not in ["up", "down"]:
        raise HTTPException(status_code=400, detail="Thumbs must be 'up' or 'down'")

    feedbacks.append({
        "match_id": req.match_id,
        "thumbs": req.thumbs,
        "timestamp": datetime.now().isoformat()
    })
    return {"status": "logged"}

