from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import hashlib
import random
import string

app = FastAPI()

users = {}
tokens = {}
trips = {}
waypoints = {}
trip_counter = 0
waypoint_counter = 0

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def hash_password(password: str):
    return hashlib.sha256(password.encode()).hexdigest()

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class UserSignup(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TripCreate(BaseModel):
    start: str
    end: str

class WaypointCreate(BaseModel):
    trip_id: int
    name: str
    lat: float
    lon: float
    distance_from_prev: Optional[float] = 0
    gas_cost: Optional[float] = 0
    suggested_stop: Optional[str] = None

@app.post("/signup")
def signup(user: UserSignup):
    if user.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[user.username] = hash_password(user.password)
    return {"message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    stored = users.get(user.username)
    if not stored or stored != hash_password(user.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = user.username
    return {"token": token}

@app.get("/trip")
def get_trip(start: str, end: str, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    global trip_counter
    trip_counter += 1
    trip_id = trip_counter

    # Mock waypoints for LA to SF
    waypoints_list = [
        {"name": "Los Angeles", "lat": 34.0522, "lon": -118.2437, "distance_from_prev": 0, "gas_cost": 0, "suggested_stop": "Start"},
        {"name": "Bakersfield", "lat": 35.3733, "lon": -119.0187, "distance_from_prev": 112, "gas_cost": 14.56, "suggested_stop": "Buck Owens' Crystal Palace"},
        {"name": "Fresno", "lat": 36.7378, "lon": -119.7871, "distance_from_prev": 107, "gas_cost": 13.91, "suggested_stop": "Forestiere Underground Gardens"},
        {"name": "San Jose", "lat": 37.3382, "lon": -121.8863, "distance_from_prev": 150, "gas_cost": 19.50, "suggested_stop": "Winchester Mystery House"},
        {"name": "San Francisco", "lat": 37.7749, "lon": -122.4194, "distance_from_prev": 48, "gas_cost": 6.24, "suggested_stop": "Golden Gate Bridge"}
    ]

    total_distance = sum(w["distance_from_prev"] for w in waypoints_list)
    total_gas = sum(w["gas_cost"] for w in waypoints_list)
    stops = [w["suggested_stop"] for w in waypoints_list if w["suggested_stop"] and w["suggested_stop"] != "Start"]

    trip_data = {
        "id": trip_id,
        "start": start,
        "end": end,
        "waypoints": waypoints_list,
        "total_distance_miles": total_distance,
        "total_gas_cost_usd": round(total_gas, 2),
        "suggested_stops": stops
    }

    trips[trip_id] = trip_data
    return trip_data

@app.post("/optimize")
def optimize_trip(trip_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")

    # Simple optimization: reorder waypoints by lat (northward for LA->SF)
    waypoints = trip["waypoints"]
    # Keep start and end fixed, sort middle ones by latitude
    if len(waypoints) > 2:
        start = waypoints[0]
        end = waypoints[-1]
        middle = waypoints[1:-1]
        middle.sort(key=lambda w: w["lat"])
        waypoints = [start] + middle + [end]

        # Recalculate distances (simplified - just reorder)
        for i in range(1, len(waypoints)):
            waypoints[i]["distance_from_prev"] = round(abs(waypoints[i]["lat"] - waypoints[i-1]["lat"]) * 69, 2)
            waypoints[i]["gas_cost"] = round(waypoints[i]["distance_from_prev"] * 0.13, 2)

    trip["waypoints"] = waypoints
    trip["total_distance_miles"] = sum(w["distance_from_prev"] for w in waypoints)
    trip["total_gas_cost_usd"] = round(sum(w["gas_cost"] for w in waypoints), 2)

    return {"optimized": True, "trip": trip}

@app.get("/trip/{trip_id}")
def get_trip_by_id(trip_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    trip = trips.get(trip_id)
    if not trip:
        raise HTTPException(status_code=404, detail="Trip not found")
    return trip

@app.post("/waypoint")
def create_waypoint(waypoint: WaypointCreate, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    global waypoint_counter
    waypoint_counter += 1
    wp = waypoint.dict()
    wp["id"] = waypoint_counter
    waypoints[waypoint_counter] = wp
    return wp

@app.get("/waypoint/{waypoint_id}")
def get_waypoint(waypoint_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    wp = waypoints.get(waypoint_id)
    if not wp:
        raise HTTPException(status_code=404, detail="Waypoint not found")
    return wp

