from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import random
import time
import secrets
import hashlib

app = FastAPI()

users = {}
tokens = {}
questions = {}
answers = {}
next_user_id = 1
next_question_id = 1
next_answer_id = 1

sample_questions = [
    {"question": "What is 2+2?", "options": ["3", "4", "5", "6"], "difficulty": 1, "correct": "4"},
    {"question": "What is the capital of France?", "options": ["London", "Berlin", "Paris", "Madrid"], "difficulty": 1, "correct": "Paris"},
    {"question": "Which data structure uses FIFO?", "options": ["Stack", "Queue", "Tree", "Graph"], "difficulty": 2, "correct": "Queue"},
    {"question": "What does HTTP stand for?", "options": ["HyperText Transfer Protocol", "High Transfer Text Protocol", "HyperText Transmission Protocol", "Hyper Transfer Text Protocol"], "difficulty": 1, "correct": "HyperText Transfer Protocol"},
    {"question": "What is the time complexity of binary search?", "options": ["O(n)", "O(log n)", "O(n^2)", "O(1)"], "difficulty": 3, "correct": "O(log n)"},
    {"question": "Which sorting algorithm is O(n log n) in average case?", "options": ["Bubble Sort", "Insertion Sort", "Merge Sort", "Selection Sort"], "difficulty": 3, "correct": "Merge Sort"},
    {"question": "What is a primary key in a database?", "options": ["A unique identifier for a row", "A random number", "A foreign key", "A table name"], "difficulty": 2, "correct": "A unique identifier for a row"},
    {"question": "What does CSS stand for?", "options": ["Cascading Style Sheets", "Computer Style Sheets", "Creative Style Sheets", "Colorful Style Sheets"], "difficulty": 1, "correct": "Cascading Style Sheets"},
    {"question": "What is polymorphism in OOP?", "options": ["Many forms", "One form", "No forms", "Inheritance only"], "difficulty": 3, "correct": "Many forms"},
    {"question": "Which port does HTTPS use?", "options": ["80", "443", "22", "8080"], "difficulty": 2, "correct": "443"},
]

for q in sample_questions:
    qid = next_question_id
    questions[qid] = {
        "id": qid,
        "question": q["question"],
        "options": q["options"],
        "difficulty": q["difficulty"],
        "correct": q["correct"]
    }
    next_question_id += 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class AnswerSubmit(BaseModel):
    question_id: int
    answer: str

def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    uid = next_user_id
    users[uid] = {
        "id": uid,
        "username": req.username,
        "password": hashlib.sha256(req.password.encode()).hexdigest()
    }
    next_user_id += 1
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == hashlib.sha256(req.password.encode()).hexdigest():
            token = secrets.token_hex(32)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/quiz")
def get_quiz(authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    qid = random.choice(list(questions.keys()))
