def submit_answer(req: AnswerSubmit, authorization: str = Header(None)):
    uid = get_user_id_from_token(authorization)
    start_time = time.time()
    if req.question_id not in questions:
        raise HTTPException(status_code=404, detail="Question not found")
    q = questions[req.question_id]
    correct = q["correct"]
    is_correct = req.answer == correct
    time_taken = time.time() - start_time
    global next_answer_id
    aid = next_answer_id
    answers[aid] = {
        "id": aid,
        "user_id": uid,
        "question_id": req.question_id,
        "submitted_answer": req.answer,
        "correct_answer": correct,
        "is_correct": is_correct,
        "time_taken": round(time_taken, 3)
    }
    next_answer_id += 1
    return {
        "correct_answer": correct,
        "is_correct": is_correct,
        "time_taken": round(time_taken, 3)
    }

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/users")
def create_user(req: SignupRequest):
    return signup(req)

@app.get("/questions/{question_id}")
def get_question(question_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if question_id not in questions:
        raise HTTPException(status_code=404, detail="Question not found")
    q = questions[question_id]
    return {
        "id": q["id"],
        "question": q["question"],
        "options": q["options"],
        "difficulty": q["difficulty"]
    }

@app.post("/questions")
def create_question(question: str, options: list, difficulty: int, correct: str, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    global next_question_id
    qid = next_question_id
    questions[qid] = {
        "id": qid,
        "question": question,
        "options": options,
        "difficulty": difficulty,
        "correct": correct
    }
    next_question_id += 1
    return {"id": qid}

@app.get("/answers/{answer_id}")
def get_answer(answer_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    if answer_id not in answers:
        raise HTTPException(status_code=404, detail="Answer not found")
    return answers[answer_id]

@app.post("/answers")
def create_answer(req: AnswerSubmit, authorization: str = Header(None)):
    return submit_answer(req, authorization)

