from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
from typing import Optional
import uuid
import time

app = FastAPI()

users = {}
tokens = {}
usage_records = {}
next_user_id = 1
next_usage_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(401, "No auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(401, "Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    if username in users:
        raise HTTPException(400, "User exists")
    user_id = next_user_id
    next_user_id += 1
    users[username] = {"id": user_id, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username]["password"] != password:
        raise HTTPException(401, "Bad credentials")
    token = str(uuid.uuid4())
    tokens[token] = users[username]["id"]
    return {"token": token}

@app.get("/usage/{usage_id}")
def get_usage(usage_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if usage_id not in usage_records:
        raise HTTPException(404, "Not found")
    return usage_records[usage_id]

@app.post("/usage")
def create_usage(gallons: float, authorization: Optional[str] = Header(None)):
    global next_usage_id
    user_id = get_current_user(authorization)
    usage_id = next_usage_id
    next_usage_id += 1
    usage_records[usage_id] = {
        "id": usage_id,
        "user_id": user_id,
        "gallons": gallons,
        "timestamp": datetime.now().isoformat()
    }
    return usage_records[usage_id]

@app.get("/usage")
def get_daily_usage(authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    today = datetime.now().date()
    today_records = [r for r in usage_records.values() if r["user_id"] == user_id and datetime.fromisoformat(r["timestamp"]).date() == today]
    total_daily = sum(r["gallons"] for r in today_records)

    # weekly average
    week_ago = datetime.now() - timedelta(days=7)
    week_records = [r for r in usage_records.values() if r["user_id"] == user_id and datetime.fromisoformat(r["timestamp"]) >= week_ago]
    weekly_avg = sum(r["gallons"] for r in week_records) / 7 if week_records else 0

    # leak detection: check if any flow > 3 hours straight
    leak_detected = False
    user_records_sorted = sorted([r for r in usage_records.values() if r["user_id"] == user_id], key=lambda x: x["timestamp"])
    if len(user_records_sorted) >= 2:
        for i in range(len(user_records_sorted) - 1):
            t1 = datetime.fromisoformat(user_records_sorted[i]["timestamp"])
            t2 = datetime.fromisoformat(user_records_sorted[i+1]["timestamp"])
            if (t2 - t1).total_seconds() > 3 * 3600 and user_records_sorted[i]["gallons"] > 0:
                leak_detected = True
                break

    return {
        "daily_gallons": total_daily,
        "weekly_average_gallons": round(weekly_avg, 2),
        "leak_detected": leak_detected
    }

