from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import random
import string

app = FastAPI()

users = {}
tokens = {}
recipes = {}
reviews = {}
next_user_id = 1
next_recipe_id = 1
next_review_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class RecipeCreate(BaseModel):
    name: str
    ingredients: List[str]
    cook_time: int

class ReviewCreate(BaseModel):
    recipe_id: int
    rating: int

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, user in users.items():
        if user["username"] == req.username and user["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/recipes/{recipe_id}")
def get_recipe(recipe_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    return recipes[recipe_id]

@app.post("/recipes")
def create_recipe(recipe: RecipeCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_recipe_id
    recipe_id = next_recipe_id
    next_recipe_id += 1
    recipes[recipe_id] = {
        "id": recipe_id,
        "name": recipe.name,
        "ingredients": recipe.ingredients,
        "cook_time": recipe.cook_time
    }
    return recipes[recipe_id]

@app.get("/recipes")
def search_recipes(ingredients: str, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    user_ingredients = set(i.strip().lower() for i in ingredients.split(","))
    results = []
    for rid, recipe in recipes.items():
        recipe_ingredients = set(i.lower() for i in recipe["ingredients"])
        missing = recipe_ingredients - user_ingredients
        results.append({
            "id": rid,
            "name": recipe["name"],
            "missing_items": list(missing),
            "missing_count": len(missing),
            "total_cook_time": recipe["cook_time"]
        })
    results.sort(key=lambda x: x["missing_count"])
    return results

@app.post("/rate")
def rate_recipe(review: ReviewCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if review.recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    if review.rating < 1 or review.rating > 5:
        raise HTTPException(status_code=400, detail="Rating must be 1-5")
    global next_review_id
    review_id = next_review_id
    next_review_id += 1
    reviews[review_id] = {
        "id": review_id,
        "user_id": user_id,
        "recipe_id": review.recipe_id,
        "rating": review.rating
    }
    return reviews[review_id]

