    try:
        signup_resp = session.post(f"{BASE_URL}/signup", json=signup_data)
        signup_resp.raise_for_status()
        signup_json = signup_resp.json()
        token = signup_json.get("token")
        if not token:
            return False
    except Exception:
        return False

    # Login
    login_data = {"username": "testuser", "password": "testpass123"}
    try:
        login_resp = session.post(f"{BASE_URL}/login", json=login_data)
        login_resp.raise_for_status()
        login_json = login_resp.json()
        token = login_json.get("token")
        if not token:
            return False
    except Exception:
        return False

    # Create a recipe
    recipe_data = {
        "name": "Test Recipe",
        "ingredients": ["flour", "sugar", "eggs"],
        "cook_time": 30
    }
    headers = {"Authorization": f"Bearer {token}"}
    try:
        create_resp = session.post(f"{BASE_URL}/recipes", json=recipe_data, headers=headers)
        create_resp.raise_for_status()
        recipe = create_resp.json()
        recipe_id = recipe.get("id")
        if not recipe_id:
            return False
    except Exception:
        return False

    # Fetch the created recipe
    try:
        fetch_resp = session.get(f"{BASE_URL}/recipes/{recipe_id}", headers=headers)
