from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import asyncio
from fastapi import WebSocket, WebSocketDisconnect

app = FastAPI()

users = {}
tokens = {}
rooms = {}
messages = {}
next_user_id = 1
next_room_id = 1
next_message_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateRoomRequest(BaseModel):
    name: str
    subject: str
    max_capacity: int

class CoHostRequest(BaseModel):
    user_id: int

class MessageRequest(BaseModel):
    content: str

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return users[user_id]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user

@app.post("/rooms")
def create_room(req: CreateRoomRequest, authorization: str = Header(None)):
    global next_room_id
    user = get_user_from_token(authorization)
    room_id = next_room_id
    next_room_id += 1
    rooms[room_id] = {
        "id": room_id,
        "name": req.name,
        "subject": req.subject,
        "max_capacity": req.max_capacity,
        "creator_id": user["id"],
        "co_hosts": [],
        "members": [user["id"]]
    }
    messages[room_id] = []
    return rooms[room_id]

@app.get("/rooms/{room_id}")
def get_room(room_id: int):
    room = rooms.get(room_id)
    if not room:
        raise HTTPException(status_code=404, detail="Room not found")
    return room

@app.post("/rooms/{room_id}/co-host")
def promote_co_host(room_id: int, req: CoHostRequest, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    room = rooms.get(room_id)
    if not room:
        raise HTTPException(status_code=404, detail="Room not found")
    if room["creator_id"] != user["id"]:
        raise HTTPException(status_code=403, detail="Only creator can promote co-hosts")
    if req.user_id not in room["members"]:
        raise HTTPException(status_code=400, detail="User not in room")
    if req.user_id not in room["co_hosts"]:
        room["co_hosts"].append(req.user_id)
    return room

@app.get("/rooms/{room_id}/messages")
def get_messages(room_id: int):
    msgs = messages.get(room_id)
    if msgs is None:
        raise HTTPException(status_code=404, detail="Room not found")
    return msgs

@app.websocket("/ws/{room_id}")
async def websocket_endpoint(websocket: WebSocket, room_id: int):
    await websocket.accept()
    token = websocket.headers.get("authorization", "").replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        await websocket.send_json({"error": "unauthorized"})
        await websocket.close()
        return
    user = users[user_id]
    room = rooms.get(room_id)
    if not room:
        await websocket.send_json({"error": "room not found"})
        await websocket.close()
        return
    if user_id not in room["members"]:
        await websocket.send_json({"error": "not a member"})
        await websocket.close()
        return
    try:
        while True:
            data = await websocket.receive_json()
            if data.get("type") == "message":
                global next_message_id
                msg_id = next_message_id
                next_message_id += 1
                msg = {
                    "id": msg_id,
                    "user_id": user_id,
                    "username": user["username"],
                    "content": data["content"],
                    "room_id": room_id
                }
                messages[room_id].append(msg)
                for member_id in room["members"]:
                    pass  # would broadcast in real impl
                await websocket.send_json({"type": "ack", "message_id": msg_id})
    except WebSocketDisconnect:
        pass

