    if not user_id:
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", json={
        "username": "testuser",
        "password": "testpass"
    })
    if login_resp.status_code != 200:
        return False

    token = login_resp.json().get("token")
    if not token:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Get own user
    user_resp = session.get(f"{BASE_URL}/users/{user_id}", headers=headers)
    if user_resp.status_code != 200:
        return False

    own_data = user_resp.json()
    if own_data.get("username") != "testuser":
        return False

    # Create a room
    room_resp = session.post(f"{BASE_URL}/rooms", headers=headers, json={
        "name": "testroom",
        "subject": "testing",
        "max_capacity": 10
    })
    if room_resp.status_code != 200:
        return False

    room_id = room_resp.json().get("id")
    if not room_id:
        return False

    # Get the room
    get_room_resp = session.get(f"{BASE_URL}/rooms/{room_id}", headers=headers)
    if get_room_resp.status_code != 200:
        return False

    room_data = get_room_resp.json()
    if room_data.get("creator_id") != user_id:
        return False

    return True

