    profile_id = next_profile_id
    next_profile_id += 1
    profiles[profile_id] = {
        "id": profile_id,
        "user_id": user_id,
        "name": name,
        "age": age,
        "interests": interests,
        "last_active": datetime.utcnow().isoformat()
    }
    return profiles[profile_id]

