    destination: str
    start_date: str
    end_date: str

class ItineraryCreate(BaseModel):
    trip_id: int
    day: int
    activity: str
    location: str
    notes: str = ""

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    for uid, t in user_tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"id": uid, "username": req.username, "password": req.password}
    return {"id": uid, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = f"tok_{uid}_{datetime.datetime.now().timestamp()}"
            user_tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trips")
