    recipe_owner_map = getattr(app.state, 'recipe_owner_map', {})
    owner = recipe_owner_map.get(recipe_id)
    if owner is None:
        # First access defines owner
        recipe_owner_map[recipe_id] = user_id
        app.state.recipe_owner_map = recipe_owner_map
    elif owner != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return {"id": row[0], "name": row[1], "difficulty": row[2], "dietary_tags": row[3]}

@app.post("/recipes")
