    conn.commit()
    recipe_id = recipe_id_counter
    recipe_id_counter += 1
    # Track ownership
    recipe_owner_map = getattr(app.state, 'recipe_owner_map', {})
    recipe_owner_map[recipe_id] = user_id
    app.state.recipe_owner_map = recipe_owner_map
    return {"id": recipe_id}

@app.get("/recipes")
def search_recipes(ingredients: str = "", max_prep_time: int = 1000000, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    ing_list = [i.strip() for i in ingredients.split(",") if i.strip()]
    recipe_owner_map = getattr(app.state, 'recipe_owner_map', {})
    owned_recipe_ids = {rid for rid, uid in recipe_owner_map.items() if uid == user_id}
    if not owned_recipe_ids:
        return []
    id_placeholders = ','.join('?'*len(owned_recipe_ids))
    base_query = f"SELECT id, name, difficulty, dietary_tags FROM recipes WHERE id IN ({id_placeholders}) AND prep_time <= ?"
    base_params = list(owned_recipe_ids) + [max_prep_time]
    if not ing_list:
        cursor = conn.execute(base_query, base_params)
    else:
        like_clauses = " AND ".join(["ingredients LIKE ?" for _ in ing_list])
        params = [f"%{ing}%" for ing in ing_list] + base_params
        full_query = f"SELECT id, name, difficulty, dietary_tags FROM recipes WHERE id IN ({id_placeholders}) AND {like_clauses} AND prep_time <= ?"
        cursor = conn.execute(full_query, params)
    rows = cursor.fetchall()
    return [{"id": r[0], "name": r[1], "difficulty": r[2], "dietary_tags": r[3]} for r in rows]

