import os
import io
import hashlib
import secrets
from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import Response, FileResponse
from PIL import Image

app = FastAPI()

users = {}
tokens = {}
resource_id_counters = {}
resource_stores = {}

VALID_RESOURCES = {"textures"}

GAME_TEXTURES_DIR = "/var/games"

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    password_hash = hashlib.sha256(password.encode()).hexdigest()
    user_id = len(users) + 1
    users[username] = {"id": user_id, "password_hash": password_hash}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    if username not in users:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    password_hash = hashlib.sha256(password.encode()).hexdigest()
    if users[username]["password_hash"] != password_hash:
        raise HTTPException(status_code=400, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = username
    return {"token": token}

@app.get("/game/{title}/textures/{file}")
def get_texture(title: str, file: str, format: str = None, authorization: str = Header(None)):
    get_current_user(authorization)
    dir_path = os.path.join(GAME_TEXTURES_DIR, title, "textures")
    file_path = os.path.join(dir_path, file)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Texture not found")
    if format == "webp":
        img = Image.open(file_path)
        buf = io.BytesIO()
        img.save(buf, format="WEBP")
        buf.seek(0)
        return Response(content=buf.read(), media_type="image/webp")
    return FileResponse(file_path, media_type="image/png")

@app.post("/{resource}")
def create_resource(resource: str, data: dict, authorization: str = Header(None)):
    username = get_current_user(authorization)
    if resource not in VALID_RESOURCES:
        raise HTTPException(status_code=400, detail="Invalid resource type")
    if resource not in resource_id_counters:
        resource_id_counters[resource] = 0
        resource_stores[resource] = {}
    resource_id_counters[resource] += 1
    resource_id = resource_id_counters[resource]
    # Store the owner with the resource
    resource_data = {**data, "owner": username}
    resource_stores[resource][resource_id] = resource_data
    return {"id": resource_id, **data}

@app.get("/{resource}/{resource_id}")
def get_resource(resource: str, resource_id: int, authorization: str = Header(None)):
    username = get_current_user(authorization)
    if resource not in resource_stores or resource_id not in resource_stores[resource]:
        raise HTTPException(status_code=404, detail="Resource not found")
    resource_data = resource_stores[resource][resource_id]
    # Check that the current user owns this resource
    if resource_data.get("owner") != username:
        raise HTTPException(status_code=403, detail="Access denied")
    # Return the data without the owner field
    return {k: v for k, v in resource_data.items() if k != "owner"}

