    order_id = r.json().get("id")
    if not order_id:
        return False

    # Fetch own order
    r = session.get(f"{BASE_URL}/orders/{order_id}")
    if r.status_code != 200:
        return False
    fetched_order = r.json()
    if fetched_order.get("id") != order_id:
        return False

    # Create shipment
