@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username]["password"] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

@app.post("/workout")
def create_workout(name: str, description: str = "", authorization: Optional[str] = Header(None)):
    auth_required(authorization)
    global workout_id_counter
    wid = workout_id_counter
    workout_id_counter += 1
    workouts[wid] = {
        "id": wid,
        "name": name,
        "description": description,
        "clips": {}
    }
    workout_dir = Path(WORKOUT_DIR) / str(wid)
    workout_dir.mkdir(parents=True, exist_ok=True)
    return workouts[wid]

