    auth_required(authorization)
    if workout_id not in workouts:
        raise HTTPException(status_code=404, detail="Workout not found")
    workout_dir = Path(WORKOUT_DIR) / str(workout_id)
    file_path = workout_dir / file.filename
    with open(file_path, "wb") as f:
        shutil.copyfileobj(file.file, f)
    clip_id = len(workouts[workout_id]["clips"]) + 1
    workouts[workout_id]["clips"][clip_id] = {
        "id": clip_id,
        "filename": file.filename,
        "filepath": str(file_path),
        "views": 0
    }
    return workouts[workout_id]["clips"][clip_id]

@app.get("/workout/{workout_id}/clips/{file}")
