import string
import shutil
from fastapi import FastAPI, HTTPException, Header, UploadFile, File
from fastapi.responses import FileResponse
from pathlib import Path

app = FastAPI()

users = {}
tokens = {}
trips = {}
next_user_id = 1
next_trip_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for user in users.values():
        if user["username"] == username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = next_user_id
    users[user_id] = {"id": user_id, "username": username, "password": password}
    next_user_id += 1
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for user in users.values():
        if user["username"] == username and user["password"] == password:
            token = generate_token()
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trip")
def create_trip(authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_trip_id
    trip_id = next_trip_id
    trips[trip_id] = {"id": trip_id, "owner": user_id}
    next_trip_id += 1
    trip_dir = f"/var/trips/{trip_id}"
    os.makedirs(trip_dir, exist_ok=True)
    return {"id": trip_id}

@app.get("/trip/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    return trips[trip_id]

@app.get("/trip/{trip_id}/docs/{file_name}")
def get_trip_doc(trip_id: int, file_name: str, authorization: str = Header(None)):
    get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    file_path = Path(f"/var/trips/{trip_id}/{file_name}")
    if not file_path.exists() or not file_path.is_file():
        raise HTTPException(status_code=404, detail="File not found")
    return FileResponse(str(file_path), media_type="application/pdf")

@app.post("/trip/{trip_id}/docs/{file_name}")
async def upload_trip_doc(trip_id: int, file_name: str, file: UploadFile = File(...), authorization: str = Header(None)):
    get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    trip_dir = Path(f"/var/trips/{trip_id}")
    trip_dir.mkdir(parents=True, exist_ok=True)
    # Remove old files in the directory
    for old_file in trip_dir.iterdir():
        if old_file.is_file():
            old_file.unlink()
    file_path = trip_dir / file_name
    with open(file_path, "wb") as f:
        content = await file.read()
        f.write(content)
    return {"message": "File uploaded", "file": file_name}

