    video = videos.get(video_id)
    if not video:
        raise HTTPException(status_code=404, detail="Video not found")
    return video

@app.post("/video")
def create_video(req: VideoCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    video_id = len(videos) + 1
    videos[video_id] = {"id": video_id, "title": req.title, "description": req.description, "user_id": user_id}
    chunks[video_id] = []
    return videos[video_id]

@app.get("/video/{video_id}/manifest")
def get_manifest(video_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    video = videos.get(video_id)
    if not video:
        raise HTTPException(status_code=404, detail="Video not found")
    video_chunks = chunks.get(video_id, [])
    return {"video_id": video_id, "chunks": [c["filename"] for c in video_chunks]}

@app.get("/video/{video_id}/chunks/{filename}")
