    video = videos.get(video_id)
    if not video:
        raise HTTPException(status_code=404, detail="Video not found")
    video_chunks = chunks.get(video_id, [])
    chunk = next((c for c in video_chunks if c["filename"] == filename), None)
    if not chunk:
        raise HTTPException(status_code=404, detail="Chunk not found")
    file_path = os.path.join("/var/videos", str(video_id), filename)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="File not found on disk")
    with open(file_path, "rb") as f:
        content = f.read()
    return Response(content=content, media_type="video/mp2t")

@app.post("/video/{video_id}/chunks")
