    user_id = get_current_user(authorization)
    video = videos.get(video_id)
    if not video:
        raise HTTPException(status_code=404, detail="Video not found")
    chunk_id = len(chunks.get(video_id, [])) + 1
    chunk_data = {"id": chunk_id, "filename": req.filename, "filepath": req.filepath}
    if video_id not in chunks:
        chunks[video_id] = []
    chunks[video_id].append(chunk_data)
    return chunk_data

