import os
import tarfile
import io
import hashlib
import secrets
from fastapi import FastAPI, HTTPException, Header, UploadFile, File
from fastapi.responses import Response, StreamingResponse

app = FastAPI()

users = {}
tokens = {}
recipes = {}
recipe_photos = {}
next_user_id = 1
next_recipe_id = 1
AUTH_TOKEN_PREFIX = "token_"

def generate_token():
    return AUTH_TOKEN_PREFIX + secrets.token_hex(16)

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    password_hash = hashlib.sha256(password.encode()).hexdigest()
    users[user_id] = {"id": user_id, "username": username, "password_hash": password_hash}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password_hash"] == hashlib.sha256(password.encode()).hexdigest():
            token = generate_token()
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/recipe")
def create_recipe(name: str, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    global next_recipe_id
    recipe_id = next_recipe_id
    next_recipe_id += 1
    recipes[recipe_id] = {"id": recipe_id, "name": name, "user_id": user_id}
    os.makedirs(f"/var/recipes/{recipe_id}", exist_ok=True)
    recipe_photos[recipe_id] = {}
    return recipes[recipe_id]

@app.get("/recipe/{recipe_id}")
def get_recipe(recipe_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    return recipes[recipe_id]

@app.post("/recipe/{recipe_id}/photos")
async def upload_photo(recipe_id: int, file: UploadFile = File(...), authorization: str = Header(None)):
    get_user_from_token(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    content = await file.read()
    filepath = f"/var/recipes/{recipe_id}/{file.filename}"
    with open(filepath, "wb") as f:
        f.write(content)
    if recipe_id not in recipe_photos:
        recipe_photos[recipe_id] = {}
    recipe_photos[recipe_id][file.filename] = filepath
    return {"filename": file.filename, "path": filepath}

@app.get("/recipe/{recipe_id}/photos/{file_name}")
def get_photo(recipe_id: int, file_name: str, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    filepath = f"/var/recipes/{recipe_id}/{file_name}"
    if not os.path.exists(filepath):
        raise HTTPException(status_code=404, detail="File not found")
    with open(filepath, "rb") as f:
        content = f.read()
    return Response(content=content, media_type="application/octet-stream")

@app.get("/recipe/{recipe_id}/photos")
def get_all_photos(recipe_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    photos_dir = f"/var/recipes/{recipe_id}"
    if not os.path.exists(photos_dir):
        raise HTTPException(status_code=404, detail="No photos directory")

    tar_buffer = io.BytesIO()
    with tarfile.open(fileobj=tar_buffer, mode="w:gz") as tar:
        for filename in os.listdir(photos_dir):
            filepath = os.path.join(photos_dir, filename)
            if os.path.isfile(filepath):
                tar.add(filepath, arcname=filename)
    tar_buffer.seek(0)
    return StreamingResponse(tar_buffer, media_type="application/gzip", headers={"Content-Disposition": f"attachment; filename=recipe_{recipe_id}_photos.tar.gz"})

