from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import Response
from pygments import highlight
from pygments.lexers import get_lexer_for_filename
from pygments.formatters import HtmlFormatter
from pathlib import Path
import secrets
import uvicorn

app = FastAPI()

users = {}
tokens = {}
tutorials = {}
next_user_id = 1
next_tutorial_id = 1

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(401, "Unauthorized")
    token = authorization.split(" ")[1]
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(401, "Invalid token")
    return user_id

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"username": username, "password": password}
    return {"id": uid}

@app.post("/login")
def login(username: str, password: str):
    for uid, u in users.items():
        if u["username"] == username and u["password"] == password:
            token = secrets.token_hex(32)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(401, "Invalid credentials")

@app.get("/tutorials/{tutorial_id}")
def get_tutorial(tutorial_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    tut = tutorials.get(tutorial_id)
    if not tut:
        raise HTTPException(404, "Not found")
    return tut

@app.post("/tutorials")
def create_tutorial(name: str, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_tutorial_id
    tid = next_tutorial_id
    next_tutorial_id += 1
    tutorials[tid] = {"id": tid, "name": name}
    return {"id": tid}

@app.get("/tutorial/{tutorial_id}/code/{file_path:path}")
def serve_code(tutorial_id: int, file_path: str, authorization: str = Header(None)):
    get_current_user(authorization)
    tut = tutorials.get(tutorial_id)
    if not tut:
        raise HTTPException(404, "Tutorial not found")
    base_path = Path(f"/var/tutorials/{tutorial_id}")
    full_path = base_path / file_path
    if not full_path.exists() or not full_path.is_file():
        raise HTTPException(404, "File not found")
    content = full_path.read_text()
    try:
        lexer = get_lexer_for_filename(file_path)
        formatter = HtmlFormatter(style="monokai", full=True)
        highlighted = highlight(content, lexer, formatter)
        return Response(content=highlighted, media_type="text/html")
    except:
        return Response(content=content, media_type="text/plain")

