from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict, List
import secrets

app = FastAPI()

users: Dict[int, dict] = {}
events: Dict[int, dict] = {}
orders: Dict[int, dict] = {}
tokens: Dict[str, int] = {}
next_user_id = 1
next_event_id = 1
next_order_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateEventRequest(BaseModel):
    title: str
    description: str
    date: str
    location: str
    price: float
    total_tickets: int

class EditEventRequest(BaseModel):
    title: Optional[str] = None
    description: Optional[str] = None
    date: Optional[str] = None
    location: Optional[str] = None
    price: Optional[float] = None
    total_tickets: Optional[int] = None

class BuyTicketRequest(BaseModel):
    event_id: int
    quantity: int = 1

class RefundRequest(BaseModel):
    order_id: int

class PromoteCoHostRequest(BaseModel):
    user_id: int

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return users[user_id]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    uid = next_user_id
    next_user_id += 1
    users[uid] = {
        "id": uid,
        "username": req.username,
        "password": req.password,
        "co_host_events": []
    }
    return {"user_id": uid}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user

@app.get("/events/{event_id}")
def get_event(event_id: int):
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    return event

@app.get("/orders/{order_id}")
def get_order(order_id: int):
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

@app.post("/events")
def create_event(req: CreateEventRequest, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    global next_event_id
    eid = next_event_id
    next_event_id += 1
    events[eid] = {
        "id": eid,
        "title": req.title,
        "description": req.description,
        "date": req.date,
        "location": req.location,
        "price": req.price,
        "total_tickets": req.total_tickets,
        "available_tickets": req.total_tickets,
        "host_id": user["id"],
        "co_hosts": []
    }
    return {"event_id": eid}

@app.post("/events/{event_id}/edit")
def edit_event(event_id: int, req: EditEventRequest, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if user["id"] != event["host_id"] and user["id"] not in event["co_hosts"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    if req.title is not None:
        event["title"] = req.title
    if req.description is not None:
        event["description"] = req.description
    if req.date is not None:
        event["date"] = req.date
    if req.location is not None:
        event["location"] = req.location
    if req.price is not None:
        event["price"] = req.price
    if req.total_tickets is not None:
        diff = req.total_tickets - event["total_tickets"]
        event["total_tickets"] = req.total_tickets
        event["available_tickets"] += diff
        if event["available_tickets"] < 0:
            event["available_tickets"] = 0
    return {"message": "Event updated"}

@app.post("/orders")
def buy_ticket(req: BuyTicketRequest, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    event = events.get(req.event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if event["available_tickets"] < req.quantity:
        raise HTTPException(status_code=400, detail="Not enough tickets")
    global next_order_id
    oid = next_order_id
    next_order_id += 1
    event["available_tickets"] -= req.quantity
    orders[oid] = {
        "id": oid,
        "event_id": req.event_id,
        "buyer_id": user["id"],
        "quantity": req.quantity,
        "total_price": event["price"] * req.quantity
    }
    return {"order_id": oid}

@app.post("/orders/{order_id}/refund")
def refund_ticket(order_id: int, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    event = events.get(order["event_id"])
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if user["id"] != event["host_id"] and user["id"] not in event["co_hosts"]:
        raise HTTPException(status_code=403, detail="Not authorized")
    event["available_tickets"] += order["quantity"]
    del orders[order_id]
    return {"message": "Refund processed"}

@app.post("/events/{event_id}/promote")
def promote_cohost(event_id: int, req: PromoteCoHostRequest, authorization: str = Header(None)):
    user = get_user_from_token(authorization)
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if user["id"] != event["host_id"]:
        raise HTTPException(status_code=403, detail="Only host can promote")
    target_user = users.get(req.user_id)
    if not target_user:
        raise HTTPException(status_code=404, detail="User not found")
    if req.user_id not in event["co_hosts"]:
        event["co_hosts"].append(req.user_id)
        target_user["co_host_events"].append(event_id)
    return {"message": "Co-host added"}

