from typing import Optional
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
articles = {}
promotions = {}
curators = {}
featured_posts = {}
topics = {}
next_user_id = 1
next_article_id = 1
next_promotion_id = 1
next_topic_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(email: str, password: str, name: str = ""):
    global next_user_id
    if email in [u["email"] for u in users.values()]:
        raise HTTPException(status_code=400, detail="Email already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "email": email, "password": password, "name": name, "role": "submitter"}
    return {"user_id": user_id, "email": email}

@app.post("/login")
def login(email: str, password: str):
    for user_id, user in users.items():
        if user["email"] == email and user["password"] == password:
            token = secrets.token_hex(16)
            tokens[token] = user_id
            return {"token": token, "user_id": user_id}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int):
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user

@app.post("/articles")
def create_article(title: str, url: str, summary: str = "", authorization: Optional[str] = Header(None)):
    submitter_id = get_current_user(authorization)
    global next_article_id
    article_id = next_article_id
    next_article_id += 1
    articles[article_id] = {
        "id": article_id,
        "title": title,
        "url": url,
        "summary": summary,
        "submitter_id": submitter_id,
        "featured": False,
        "topics": [],
        "created_at": datetime.datetime.now().isoformat()
    }
    return articles[article_id]

