import secrets
import datetime

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
bills = {}
bill_items = {}
payments = {}
collectors = {}

# ID counters
user_id_counter = 1
bill_id_counter = 1
bill_item_id_counter = 1
payment_id_counter = 1

