    for uid, u in users.items():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password  # plaintext, we said no security
    }
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Resource endpoints
@app.get("/bills/{bill_id}")
def get_bill(bill_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if bill_id not in bills:
        raise HTTPException(status_code=404, detail="Bill not found")
    return bills[bill_id]

@app.post("/bills")
def create_bill(bill: BillCreate, authorization: Optional[str] = Header(None)):
