from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import datetime
import os
import shutil
from fastapi import UploadFile, File, Form

app = FastAPI()

users = {}
groups = {}
sessions = {}
resources = {}
files = {}
next_user_id = 1
next_group_id = 1
next_session_id = 1
next_resource_id = 1
next_file_id = 1

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth")
    token = authorization.replace("Bearer ", "")
    for uid, u in users.items():
        if u.get("token") == token:
            return uid, u
    raise HTTPException(status_code=401, detail="Invalid token")

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class CreateGroupRequest(BaseModel):
    name: str

class PromoteRequest(BaseModel):
    user_id: int

class CreateSessionRequest(BaseModel):
    group_id: int
    start_time: str
    end_time: str

class CreateResourceRequest(BaseModel):
    group_id: int
    title: str
    content: str = ""

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    uid = next_user_id
    next_user_id += 1
    token = secrets.token_hex(16)
    users[uid] = {
        "id": uid,
        "username": req.username,
        "password": req.password,
        "token": token,
        "role": "student"
    }
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            u["token"] = token
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/groups")
def create_group(req: CreateGroupRequest, authorization: str = Header(None)):
    global next_group_id
    uid, u = get_user_from_token(authorization)
    gid = next_group_id
    next_group_id += 1
    groups[gid] = {
        "id": gid,
        "name": req.name,
        "leader_id": uid,
        "tutors": [uid],
        "members": [uid]
    }
    return {"group_id": gid}

@app.post("/group/{group_id}/promote")
def promote_to_tutor(group_id: int, req: PromoteRequest, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    g = groups.get(group_id)
    if not g:
        raise HTTPException(status_code=404, detail="Group not found")
    if g["leader_id"] != uid:
        raise HTTPException(status_code=403, detail="Only leader can promote")
    if req.user_id not in g["members"]:
        raise HTTPException(status_code=400, detail="User not in group")
    if req.user_id not in g["tutors"]:
        g["tutors"].append(req.user_id)
    return {"status": "promoted", "user_id": req.user_id}

@app.post("/group/{group_id}/join")
def join_group(group_id: int, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    g = groups.get(group_id)
    if not g:
        raise HTTPException(status_code=404, detail="Group not found")
    if uid not in g["members"]:
        g["members"].append(uid)
    return {"status": "joined", "group_id": group_id}

@app.post("/sessions")
def create_session(req: CreateSessionRequest, authorization: str = Header(None)):
    global next_session_id
    uid, u = get_user_from_token(authorization)
    g = groups.get(req.group_id)
    if not g:
        raise HTTPException(status_code=404, detail="Group not found")
    if uid not in g["tutors"]:
        raise HTTPException(status_code=403, detail="Only tutors can schedule sessions")
    sid = next_session_id
    next_session_id += 1
    sessions[sid] = {
        "id": sid,
        "group_id": req.group_id,
        "start_time": req.start_time,
        "end_time": req.end_time,
        "tutor_id": uid
    }
    return {"session_id": sid}

@app.get("/sessions/{session_id}")
def get_session(session_id: int, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    s = sessions.get(session_id)
    if not s:
        raise HTTPException(status_code=404, detail="Session not found")
    return s

@app.post("/resources")
def create_resource(req: CreateResourceRequest, authorization: str = Header(None)):
    global next_resource_id
    uid, u = get_user_from_token(authorization)
    g = groups.get(req.group_id)
    if not g:
        raise HTTPException(status_code=404, detail="Group not found")
    if uid not in g["members"]:
        raise HTTPException(status_code=403, detail="Not a group member")
    rid = next_resource_id
    next_resource_id += 1
    resources[rid] = {
        "id": rid,
        "group_id": req.group_id,
        "title": req.title,
        "content": req.content,
        "uploader_id": uid
    }
    return {"resource_id": rid}

@app.get("/resources/{resource_id}")
def get_resource(resource_id: int, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    r = resources.get(resource_id)
    if not r:
        raise HTTPException(status_code=404, detail="Resource not found")
    return r

UPLOAD_DIR = "uploads"
os.makedirs(UPLOAD_DIR, exist_ok=True)

@app.post("/files/upload")
async def upload_file(group_id: int = Form(...), file: UploadFile = File(...), authorization: str = Header(None)):
    global next_file_id
    uid, u = get_user_from_token(authorization)
    g = groups.get(group_id)
    if not g:
        raise HTTPException(status_code=404, detail="Group not found")
    if uid not in g["members"]:
        raise HTTPException(status_code=403, detail="Not a group member")
    fid = next_file_id
    next_file_id += 1
    file_path = os.path.join(UPLOAD_DIR, f"{fid}_{file.filename}")
    with open(file_path, "wb") as f:
        f.write(await file.read())
    files[fid] = {
        "id": fid,
        "group_id": group_id,
        "filename": file.filename,
        "path": file_path,
        "uploader_id": uid
    }
    return {"file_id": fid, "filename": file.filename}

@app.get("/files/{file_id}")
def get_file(file_id: int, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    f = files.get(file_id)
    if not f:
        raise HTTPException(status_code=404, detail="File not found")
    return {"file_id": f["id"], "filename": f["filename"], "group_id": f["group_id"]}

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return {"id": user["id"], "username": user["username"], "role": user["role"]}

@app.get("/groups/{group_id}")
def get_group(group_id: int, authorization: str = Header(None)):
    uid, u = get_user_from_token(authorization)
    g = groups.get(group_id)
    if not g:
        raise HTTPException(status_code=404, detail="Group not found")
    return g

