from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets
import uvicorn

app = FastAPI()

users = {}
user_id_counter = 1
tokens = {}
tracks = {}
track_id_counter = 1
labels = {}
label_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TrackCreate(BaseModel):
    title: str
    artist: str
    duration: float

class LabelCreate(BaseModel):
    name: str

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password, "role": "listener"}
    if user_id == 1:
        users[user_id]["role"] = "label_admin"
    return {"user_id": user_id, "username": req.username, "role": users[user_id]["role"]}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/promote/{user_id}")
def promote_user(user_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] != "label_admin":
        raise HTTPException(status_code=403, detail="Only label admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "producer"
    return {"user_id": user_id, "role": "producer"}

@app.post("/tracks")
def create_track(track: TrackCreate, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    global track_id_counter
    track_id = track_id_counter
    track_id_counter += 1
    tracks[track_id] = {"id": track_id, "title": track.title, "artist": track.artist, "duration": track.duration, "owner_id": current_user_id}
    return tracks[track_id]

@app.get("/tracks/{track_id}")
def get_track(track_id: int):
    if track_id not in tracks:
        raise HTTPException(status_code=404, detail="Track not found")
    return tracks[track_id]

@app.post("/tracks/merge")
def merge_tracks(track_ids: list[int], authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] not in ("producer", "label_admin"):
        raise HTTPException(status_code=403, detail="Only producers or admin can merge")
    merged_title = "Merged Track"
    merged_duration = 0.0
    for tid in track_ids:
        if tid not in tracks:
            raise HTTPException(status_code=404, detail=f"Track {tid} not found")
        merged_duration += tracks[tid]["duration"]
    global track_id_counter
    new_id = track_id_counter
    track_id_counter += 1
    tracks[new_id] = {"id": new_id, "title": merged_title, "artist": "Merged", "duration": merged_duration, "owner_id": current_user_id, "merged_from": track_ids}
    return tracks[new_id]

@app.post("/tracks/bulk")
def bulk_upload(tracks_data: list[TrackCreate], authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] not in ("producer", "label_admin"):
        raise HTTPException(status_code=403, detail="Only producers or admin can bulk upload")
    created = []
    global track_id_counter
    for t in tracks_data:
        tid = track_id_counter
        track_id_counter += 1
        tracks[tid] = {"id": tid, "title": t.title, "artist": t.artist, "duration": t.duration, "owner_id": current_user_id}
        created.append(tracks[tid])
    return created

@app.get("/users/{user_id}")
def get_user(user_id: int):
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return {"id": users[user_id]["id"], "username": users[user_id]["username"], "role": users[user_id]["role"]}

@app.post("/labels")
def create_label(label: LabelCreate, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    global label_id_counter
    label_id = label_id_counter
    label_id_counter += 1
    labels[label_id] = {"id": label_id, "name": label.name, "owner_id": current_user_id}
    return labels[label_id]

@app.get("/labels/{label_id}")
def get_label(label_id: int):
    if label_id not in labels:
        raise HTTPException(status_code=404, detail="Label not found")
    return labels[label_id]

