    current_user_id = get_current_user(authorization)
    if users[current_user_id]["role"] != "admin":
        raise HTTPException(status_code=403, detail="Only admin can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    users[user_id]["role"] = "box_office_manager"
    return {"user_id": user_id, "role": "box_office_manager"}

