from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
import secrets
from typing import Optional

app = FastAPI()

users = {}
tokens = {}
photos = {}
albums = {}
photo_id_counter = 1
album_id_counter = 1
user_id_counter = 1

promotions = {}

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class PhotoCreate(BaseModel):
    url: str
    album_id: int

class AlbumCreate(BaseModel):
    name: str

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/photos/{photo_id}")
def get_photo(photo_id: int):
    photo = photos.get(photo_id)
    if not photo:
        raise HTTPException(status_code=404, detail="Photo not found")
    return photo

@app.post("/photos")
def create_photo(photo: PhotoCreate, authorization: Optional[str] = Header(None)):
    global photo_id_counter
    user_id = get_current_user(authorization)
    album = albums.get(photo.album_id)
    if not album:
        raise HTTPException(status_code=404, detail="Album not found")
    if photo.album_id not in album.get("allowed_curators", {}) and album.get("owner") != user_id:
        raise HTTPException(status_code=403, detail="Not authorized to add photos to this album")
    pid = photo_id_counter
    photo_id_counter += 1
    photos[pid] = {"id": pid, "url": photo.url, "album_id": photo.album_id, "uploader": user_id, "approved": False}
    return {"photo_id": pid}

@app.get("/albums/{album_id}")
def get_album(album_id: int):
    album = albums.get(album_id)
    if not album:
        raise HTTPException(status_code=404, detail="Album not found")
    return album

@app.post("/albums")
def create_album(album: AlbumCreate, authorization: Optional[str] = Header(None)):
    global album_id_counter
    user_id = get_current_user(authorization)
    aid = album_id_counter
    album_id_counter += 1
    albums[aid] = {"id": aid, "name": album.name, "owner": user_id, "allowed_curators": {}}
    return {"album_id": aid}

@app.post("/promote/{user_id}")
def promote_user(user_id: int, authorization: Optional[str] = Header(None)):
    admin_id = get_current_user(authorization)
    # first user is admin
    if admin_id != 1:
        raise HTTPException(status_code=403, detail="Only the first user (admin) can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    promotions[user_id] = {"role": "curator"}
    return {"status": "promoted", "user_id": user_id}

@app.post("/curate/{photo_id}")
def curate_photo(photo_id: int, approve: bool, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if user_id not in promotions:
        raise HTTPException(status_code=403, detail="Not a curator")
    photo = photos.get(photo_id)
    if not photo:
        raise HTTPException(status_code=404, detail="Photo not found")
    album = albums.get(photo["album_id"])
    if not album:
        raise HTTPException(status_code=404, detail="Album not found")
    if album["owner"] != user_id and user_id not in album.get("allowed_curators", {}):
        raise HTTPException(status_code=403, detail="Not authorized to curate this album")
    photo["approved"] = approve
    return {"photo_id": photo_id, "approved": approve}

@app.post("/albums/{album_id}/curators/{curator_id}")
def add_curator_to_album(album_id: int, curator_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    album = albums.get(album_id)
    if not album:
        raise HTTPException(status_code=404, detail="Album not found")
    if album["owner"] != user_id:
        raise HTTPException(status_code=403, detail="Only album owner can add curators")
    if curator_id not in users:
        raise HTTPException(status_code=404, detail="Curator user not found")
    album["allowed_curators"][curator_id] = True
    return {"status": "curator added", "album_id": album_id, "curator_id": curator_id}

