def create_photo(photo: PhotoCreate, authorization: Optional[str] = Header(None)):
    global photo_id_counter
    user_id = get_current_user(authorization)
    album = albums.get(photo.album_id)
    if not album:
        raise HTTPException(status_code=404, detail="Album not found")
    if photo.album_id not in album.get("allowed_curators", {}) and album.get("owner") != user_id:
        raise HTTPException(status_code=403, detail="Not authorized to add photos to this album")
    pid = photo_id_counter
    photo_id_counter += 1
    photos[pid] = {"id": pid, "url": photo.url, "album_id": photo.album_id, "uploader": user_id, "approved": False}
