from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import uuid
import datetime

app = FastAPI()

users = {}
teams = {}
workouts = {}
tokens = {}
next_user_id = 1
next_team_id = 1
next_workout_id = 1

def get_user_from_token(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    users[user_id] = {"id": user_id, "username": username, "password": password, "role": "member"}
    next_user_id += 1
    return {"user_id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password"] == password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/team")
def create_team(name: str, authorization: Optional[str] = Header(None)):
    global next_team_id
    user_id = get_user_from_token(authorization)
    team_id = next_team_id
    teams[team_id] = {
        "id": team_id,
        "name": name,
        "captain_id": user_id,
        "co_captains": [],
        "members": [user_id],
        "workout_ids": [],
        "weekly_scores": {}
    }
    next_team_id += 1
    users[user_id]["role"] = "captain"
    return {"team_id": team_id, "name": name}

@app.post("/team/{team_id}/join")
def join_team(team_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_user_from_token(authorization)
    if team_id not in teams:
        raise HTTPException(status_code=404, detail="Team not found")
    if user_id in teams[team_id]["members"]:
        raise HTTPException(status_code=400, detail="Already in team")
    teams[team_id]["members"].append(user_id)
    return {"message": "Joined team"}

@app.post("/team/{team_id}/promote")
def promote_to_co_captain(team_id: int, user_id: int, authorization: Optional[str] = Header(None)):
    current_user = get_user_from_token(authorization)
    if team_id not in teams:
        raise HTTPException(status_code=404, detail="Team not found")
    team = teams[team_id]
    if team["captain_id"] != current_user:
        raise HTTPException(status_code=403, detail="Only captain can promote")
    if user_id not in team["members"]:
        raise HTTPException(status_code=400, detail="User not in team")
    if user_id in team["co_captains"]:
        raise HTTPException(status_code=400, detail="Already co-captain")
    team["co_captains"].append(user_id)
    users[user_id]["role"] = "co_captain"
    return {"message": f"User {user_id} promoted to co-captain"}

@app.post("/workout")
def log_workout(team_id: int, exercise: str, duration_minutes: int, calories: int, authorization: Optional[str] = Header(None)):
