from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
trips = {}
activities = {}
notes = {}
budgets = {}

user_id_counter = 1
trip_id_counter = 1
activity_id_counter = 1
note_id_counter = 1
budget_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TripCreate(BaseModel):
    name: str
    destination: str
    start_date: str
    end_date: str

class ActivityCreate(BaseModel):
    trip_id: int
    day: int
    description: str
    time: Optional[str] = None
    location: Optional[str] = None

class NoteCreate(BaseModel):
    trip_id: int
    day: int
    content: str

class BudgetCreate(BaseModel):
    trip_id: int
    day: int
    category: str
    amount: float
    description: Optional[str] = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/trip")
def create_trip(trip: TripCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global trip_id_counter
    trip_id = trip_id_counter
    trip_id_counter += 1
    trips[trip_id] = {
        "id": trip_id,
        "name": trip.name,
        "destination": trip.destination,
        "start_date": trip.start_date,
        "end_date": trip.end_date,
        "organizer_id": user_id,
        "co_organizers": []
    }
    return trips[trip_id]

@app.get("/trip/{trip_id}")
def get_trip(trip_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    trip = trips[trip_id].copy()
    trip["activities"] = [a for a in activities.values() if a["trip_id"] == trip_id]
    trip["notes"] = [n for n in notes.values() if n["trip_id"] == trip_id]
    trip["budgets"] = [b for b in budgets.values() if b["trip_id"] == trip_id]
    return trip

@app.post("/trip/{trip_id}/promote")
def promote_to_co_organizer(trip_id: int, user_id: int, authorization: str = Header(None)):
    current_user_id = get_current_user(authorization)
    if trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    trip = trips[trip_id]
    if trip["organizer_id"] != current_user_id:
        raise HTTPException(status_code=403, detail="Only the organizer can promote")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    if user_id not in trip["co_organizers"]:
        trip["co_organizers"].append(user_id)
    return {"message": f"User {user_id} promoted to co-organizer"}

@app.post("/activity")
def create_activity(activity: ActivityCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    if activity.trip_id not in trips:
        raise HTTPException(status_code=404, detail="Trip not found")
    global activity_id_counter
    activity_id = activity_id_counter
    activity_id_counter += 1
    activities[activity_id] = {
        "id": activity_id,
        "trip_id": activity.trip_id,
        "day": activity.day,
        "description": activity.description,
        "time": activity.time,
        "location": activity.location
    }
    return activities[activity_id]

@app.get("/activity/{activity_id}")
def get_activity(activity_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if activity_id not in activities:
