from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, Dict

app = FastAPI()

users = {}
user_id_counter = 1
tokens = {}  # token -> user_id

shelters = {}
shelter_id_counter = 1

listings = {}
listing_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str
    role: str = "user"  # user, shelter, superadmin

class LoginRequest(BaseModel):
    username: str
    password: str

class ShelterCreate(BaseModel):
    name: str
    address: str

class ListingCreate(BaseModel):
    species: str
    age: int
    medical_history: str
    shelter_id: int

class PromoteRequest(BaseModel):
    user_id: int
    shelter_id: int

import secrets

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {
        "id": uid,
        "username": req.username,
        "password": req.password,
        "role": req.role
    }
    token = secrets.token_hex(16)
    tokens[token] = uid
    # If first shelter to sign up, make them superadmin
    if req.role == "shelter" and not any(u["role"] == "superadmin" for u in users.values()):
        users[uid]["role"] = "superadmin"
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/shelters")
def create_shelter(req: ShelterCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global shelter_id_counter
    sid = shelter_id_counter
    shelter_id_counter += 1
    shelters[sid] = {
        "id": sid,
        "name": req.name,
        "address": req.address,
        "created_by": user_id
    }
    return shelters[sid]

@app.get("/shelters/{shelter_id}")
def get_shelter(shelter_id: int):
    s = shelters.get(shelter_id)
    if not s:
        raise HTTPException(status_code=404, detail="Shelter not found")
    return s

@app.post("/listings")
def create_listing(req: ListingCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if req.shelter_id not in shelters:
        raise HTTPException(status_code=400, detail="Shelter not found")
    global listing_id_counter
    lid = listing_id_counter
    listing_id_counter += 1
    listings[lid] = {
        "id": lid,
        "species": req.species,
        "age": req.age,
        "medical_history": req.medical_history,
        "shelter_id": req.shelter_id,
        "created_by": user_id
    }
    return listings[lid]

@app.get("/listings/{listing_id}")
def get_listing(listing_id: int):
    l = listings.get(listing_id)
    if not l:
        raise HTTPException(status_code=404, detail="Listing not found")
    return l

@app.post("/shelters/promote")
def promote_user(req: PromoteRequest, authorization: str = Header(None)):
    admin_id = get_current_user(authorization)
    admin = users.get(admin_id)
    if not admin or admin["role"] != "superadmin":
        raise HTTPException(status_code=403, detail="Only superadmin can promote")
    target = users.get(req.user_id)
    if not target:
        raise HTTPException(status_code=404, detail="User not found")
    if req.shelter_id not in shelters:
        raise HTTPException(status_code=404, detail="Shelter not found")
    users[req.user_id]["role"] = "adopter_coordinator"
    return {"message": f"User {req.user_id} promoted to adopter_coordinator"}

