    global group_id_counter
    uid = authenticate(authorization)
    gid = group_id_counter
    group_id_counter += 1
    groups[gid] = {
        "id": gid,
        "name": name,
        "book_title": book_title,
        "creator_id": uid,
        "members": [uid],
        "discussion_leaders": [],
        "reading_schedule": {},
        "discussion_notes": {}
    }
    return groups[gid]

@app.post("/groups/{group_id}/join")
def join_group(group_id: int, authorization: Optional[str] = Header(None)):
    uid = authenticate(authorization)
    if group_id not in groups:
        raise HTTPException(404)
    if uid in groups[group_id]["members"]:
        raise HTTPException(400, "Already a member")
    groups[group_id]["members"].append(uid)
    return {"status": "joined"}

@app.post("/groups/{group_id}/promote")
def promote_member(group_id: int, member_id: int, authorization: Optional[str] = Header(None)):
    uid = authenticate(authorization)
    if group_id not in groups:
        raise HTTPException(404)
    g = groups[group_id]
    if g["creator_id"] != uid:
        raise HTTPException(403, "Only group creator can promote")
    if member_id not in g["members"]:
        raise HTTPException(400, "Member not in group")
    if member_id in g["discussion_leaders"]:
        raise HTTPException(400, "Already a discussion leader")
    g["discussion_leaders"].append(member_id)
    return {"status": "promoted", "member_id": member_id}

