    uid = authenticate(authorization)
    if group_id not in groups:
        raise HTTPException(404)
    g = groups[group_id]
    if uid not in g["discussion_leaders"] and uid != g["creator_id"]:
        raise HTTPException(403, "Only discussion leader or creator can set schedule")
    g["reading_schedule"][chapter] = date
    return {"chapter": chapter, "date": date}

@app.post("/groups/{group_id}/notes")
def add_note(group_id: int, chapter: int, note: str, authorization: Optional[str] = Header(None)):
    uid = authenticate(authorization)
    if group_id not in groups:
        raise HTTPException(404)
    g = groups[group_id]
    if uid not in g["discussion_leaders"] and uid != g["creator_id"]:
        raise HTTPException(403, "Only discussion leader or creator can add notes")
    if chapter not in g["discussion_notes"]:
        g["discussion_notes"][chapter] = []
    g["discussion_notes"][chapter].append({"user_id": uid, "note": note})
    return {"chapter": chapter, "note": note}

