from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
from datetime import datetime, timedelta
import uuid
import hashlib
import hmac
import json
import calendar

app = FastAPI()

# In-memory storage
users = {}
tokens = {}
subscriptions = {}
subscription_id_counter = 1
user_id_counter = 1

# Simple token generation
def generate_token(user_id):
    token = str(uuid.uuid4())
    tokens[token] = user_id
    return token

def get_user_id_from_token(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization.split(" ")[1]
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    email: str
    password: str

class LoginRequest(BaseModel):
    email: str
    password: str

class CreateSubscriptionRequest(BaseModel):
    user_id: int
    plan_tier: str
    payment_method: str
    billing_address: str
    coupon_code: Optional[str] = None

class UpdateSubscriptionRequest(BaseModel):
    plan_tier: Optional[str] = None
    payment_method: Optional[str] = None
    billing_address: Optional[str] = None
    coupon_code: Optional[str] = None

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"email": req.email, "password": req.password, "id": user_id}
    token = generate_token(user_id)
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["email"] == req.email and u["password"] == req.password:
            token = generate_token(uid)
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    user = users.get(user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")
    return user

@app.post("/users")
def create_user(req: SignupRequest):
    return signup(req)

@app.post("/subscriptions")
def create_subscription(req: CreateSubscriptionRequest, authorization: str = Header(None)):
    global subscription_id_counter
    get_user_id_from_token(authorization)
    user = users.get(req.user_id)
    if not user:
        raise HTTPException(status_code=404, detail="User not found")

    # Check for existing active subscription
    for sub_id, sub in subscriptions.items():
        if sub["user_id"] == req.user_id and sub["status"] == "active":
            raise HTTPException(status_code=400, detail="User already has an active subscription")

    sub_id = subscription_id_counter
    subscription_id_counter += 1

    # Calculate prorated charge (simplified: 30 day month, prorate based on remaining days)
    now = datetime.utcnow()
    current_day = now.day
    days_in_month = calendar.monthrange(now.year, now.month)[1]
    remaining_days = days_in_month - current_day + 1
    monthly_price = {"basic": 10.0, "pro": 25.0, "enterprise": 100.0}.get(req.plan_tier, 10.0)
    prorated_amount = round((monthly_price / days_in_month) * remaining_days, 2)

    # Apply coupon if provided
    coupon_discount = 0.0
    if req.coupon_code:
        # Simple coupon logic: 10% off for "SAVE10", $5 off for "FIVE"
        if req.coupon_code == "SAVE10":
            coupon_discount = round(prorated_amount * 0.1, 2)
        elif req.coupon_code == "FIVE":
            coupon_discount = 5.0
        prorated_amount = max(0, prorated_amount - coupon_discount)

    subscriptions[sub_id] = {
        "id": sub_id,
        "user_id": req.user_id,
        "plan_tier": req.plan_tier,
        "payment_method": req.payment_method,
        "billing_address": req.billing_address,
        "coupon_code": req.coupon_code,
        "status": "active",
        "created_at": now.isoformat(),
        "next_billing_date": (now + timedelta(days=30)).isoformat(),
        "prorated_charge": prorated_amount,
        "original_price": monthly_price
    }
    return subscriptions[sub_id]

@app.get("/subscriptions/{subscription_id}")
def get_subscription(subscription_id: int, authorization: str = Header(None)):
    get_user_id_from_token(authorization)
    sub = subscriptions.get(subscription_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    return sub

@app.put("/subscriptions/{subscription_id}")
def update_subscription(subscription_id: int, req: UpdateSubscriptionRequest, authorization: str = Header(None)):
    user_id = get_user_id_from_token(authorization)
    sub = subscriptions.get(subscription_id)
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    if sub["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your subscription")

    if req.plan_tier is not None:
        # Calculate prorated charge for plan change
        old_price = {"basic": 10.0, "pro": 25.0, "enterprise": 100.0}.get(sub["plan_tier"], 10.0)
        new_price = {"basic": 10.0, "pro": 25.0, "enterprise": 100.0}.get(req.plan_tier, 10.0)
        now = datetime.utcnow()
        current_day = now.day
        days_in_month = calendar.monthrange(now.year, now.month)[1]
        remaining_days = days_in_month - current_day + 1
        daily_old = old_price / days_in_month
        daily_new = new_price / days_in_month
        prorated_charge = round((daily_new - daily_old) * remaining_days, 2)

        # Apply coupon if provided
        if req.coupon_code:
            if req.coupon_code == "SAVE10":
                prorated_charge = round(prorated_charge * 0.9, 2)
            elif req.coupon_code == "FIVE":
                prorated_charge = max(0, prorated_charge - 5.0)

        sub["plan_tier"] = req.plan_tier
        sub["prorated_charge"] = prorated_charge
        sub["original_price"] = new_price

    if req.payment_method is not None:
        sub["payment_method"] = req.payment_method
    if req.billing_address is not None:
        sub["billing_address"] = req.billing_address
    if req.coupon_code is not None:
        sub["coupon_code"] = req.coupon_code

    sub["updated_at"] = datetime.utcnow().isoformat()
    return sub

