    resp = session.post(f"{BASE_URL}/login", json=login_data)
    if resp.status_code != 200:
        return False
    token = resp.json().get("token")
    if not token:
        return False

    # Step 3: Create a ticket
    headers = {"Authorization": f"Bearer {token}"}
    ticket_data = {"description": "Test ticket", "priority": "high"}
    resp = session.post(f"{BASE_URL}/tickets", json=ticket_data, headers=headers)
    if resp.status_code != 200:
        return False
    created_ticket = resp.json()
    ticket_id = created_ticket.get("id")
    if not ticket_id:
        return False

    # Step 4: Fetch the created ticket
    resp = session.get(f"{BASE_URL}/tickets/{ticket_id}", headers=headers)
    if resp.status_code != 200:
        return False
    fetched_ticket = resp.json()

