from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import uuid
import secrets

app = FastAPI()

users = {}
tokens = {}
auctions = {}
bids = {}
next_user_id = 1
next_auction_id = 1
next_bid_id = 1

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    user = next((u for u in users.values() if u["username"] == username and u["password"] == password), None)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = user["id"]
    return {"token": token}

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/users")
def create_user(username: str, password: str, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_user_id
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password}
    return {"id": user_id, "username": username}

@app.get("/auctions")
def list_auctions(authorization: str = Header(None)):
    get_current_user(authorization)
    now = datetime.utcnow()
    active = []
    for a in auctions.values():
        if a["end_time"] > now:
            active.append({
                "id": a["id"],
                "make": a["make"],
                "model": a["model"],
                "year": a["year"],
                "current_bid": a["current_bid"],
                "time_left": str(a["end_time"] - now)
            })
    return active

@app.post("/auctions/{auction_id}/bid")
def place_bid(auction_id: int, amount: float, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if auction_id not in auctions:
        raise HTTPException(status_code=404, detail="Auction not found")
    auction = auctions[auction_id]
    now = datetime.utcnow()
    if auction["end_time"] <= now:
        raise HTTPException(status_code=400, detail="Auction ended")
    if amount <= auction["current_bid"]:
        raise HTTPException(status_code=400, detail="Bid too low")
    global next_bid_id
    bid_id = next_bid_id
    next_bid_id += 1
    bids[bid_id] = {
        "id": bid_id,
        "auction_id": auction_id,
        "bidder_id": user_id,
        "amount": amount,
        "time": now.isoformat()
    }
    auction["current_bid"] = amount
    return {"id": bid_id, "amount": amount}

@app.get("/auctions/{auction_id}/history")
def get_bid_history(auction_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if auction_id not in auctions:
        raise HTTPException(status_code=404, detail="Auction not found")
    auction_bids = [b for b in bids.values() if b["auction_id"] == auction_id]
    result = []
    for b in auction_bids:
        bidder = users.get(b["bidder_id"], {})
        result.append({
            "bidder": bidder.get("username", "unknown"),
            "amount": b["amount"],
            "time": b["time"]
        })
    return result

@app.get("/auctions/{auction_id}")
def get_auction(auction_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if auction_id not in auctions:
        raise HTTPException(status_code=404, detail="Auction not found")
    return auctions[auction_id]

@app.post("/auctions")
def create_auction(make: str, model: str, year: int, start_price: float, duration_minutes: int = 60, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_auction_id
    auction_id = next_auction_id
    next_auction_id += 1
    end_time = datetime.utcnow() + timedelta(minutes=duration_minutes)
    auctions[auction_id] = {
        "id": auction_id,
        "make": make,
        "model": model,
        "year": year,
        "current_bid": start_price,
        "start_price": start_price,
        "end_time": end_time
    }
    return {"id": auction_id}

