from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

# In-memory stores
users = {}
bookings = {}
tokens = {}
user_id_counter = 1
booking_id_counter = 1

# Auth helper
def get_user_id(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Models
class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class BookingCreate(BaseModel):
    member_name: str
    desk_number: int
    time_slot: str
    membership_tier: str
    access_badge: str

class BookingUpdate(BaseModel):
    member_name: Optional[str] = None
    desk_number: Optional[int] = None
    time_slot: Optional[str] = None
    membership_tier: Optional[str] = None
    access_badge: Optional[str] = None

# Auth endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    token = secrets.token_hex(16)
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Booking endpoints
@app.get("/bookings/{booking_id}")
def get_booking(booking_id: int, authorization: str = Header(None)):
    user_id = get_user_id(authorization)
    if booking_id not in bookings:
        raise HTTPException(status_code=404, detail="Booking not found")
    booking = bookings[booking_id]
    # Check ownership
    if booking.get("owner_id") != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return booking

