import os
import uuid
import hashlib
from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import StreamingResponse
from pydantic import BaseModel
import uvicorn

app = FastAPI()

users = {}
tokens = {}
tracks = {}
playlists = {}
next_user_id = 1
next_track_id = 1
next_playlist_id = 1

MUSIC_DIR = "/var/music"

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class TrackCreate(BaseModel):
    title: str
    artist: str = ""

class PlaylistCreate(BaseModel):
    name: str
    track_ids: list[int] = []

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": hashlib.sha256(req.password.encode()).hexdigest()
    }
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == hashlib.sha256(req.password.encode()).hexdigest():
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/track/{track_id}")
def get_track(track_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    track = tracks.get(track_id)
    if not track:
        raise HTTPException(status_code=404, detail="Track not found")
    return track

@app.post("/track")
def create_track(track: TrackCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_track_id
    tid = next_track_id
    next_track_id += 1
    tracks[tid] = {
        "id": tid,
        "title": track.title,
        "artist": track.artist,
        "owner_id": user_id
    }
    return tracks[tid]

@app.get("/track/{track_id}/audio/{file}")
def stream_audio(track_id: int, file: str, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    track = tracks.get(track_id)
    if not track:
        raise HTTPException(status_code=404, detail="Track not found")
    file_path = os.path.join(MUSIC_DIR, str(track_id), file)
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Audio file not found")
    def iterfile():
        with open(file_path, "rb") as f:
            yield from f
    return StreamingResponse(iterfile(), media_type="audio/mpeg")

@app.get("/playlist/{playlist_id}")
def get_playlist(playlist_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    playlist = playlists.get(playlist_id)
    if not playlist:
        raise HTTPException(status_code=404, detail="Playlist not found")
    return playlist

@app.post("/playlist")
def create_playlist(playlist: PlaylistCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global next_playlist_id
    pid = next_playlist_id
    next_playlist_id += 1
    playlists[pid] = {
        "id": pid,
        "name": playlist.name,
        "track_ids": playlist.track_ids,
        "owner_id": user_id
    }
    return playlists[pid]

@app.get("/playlist/{playlist_id}/files")
def get_playlist_files(playlist_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    playlist = playlists.get(playlist_id)
    if not playlist:
        raise HTTPException(status_code=404, detail="Playlist not found")
    files = []
    for tid in playlist["track_ids"]:
        track = tracks.get(tid)
        if track:
            track_dir = os.path.join(MUSIC_DIR, str(tid))
            if os.path.isdir(track_dir):
                for f in sorted(os.listdir(track_dir)):
                    if f.endswith(".mp3"):
                        files.append(f"/track/{tid}/audio/{f}")
    return {"playlist_id": playlist_id, "name": playlist["name"], "files": files}

