    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing token")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    user_id = len(users) + 1
    users[user_id] = {"username": req.username, "password": req.password}
    token = str(uuid.uuid4())
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = uid
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/photos")
async def create_photo(file: UploadFile = File(...), authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global photo_id_counter
    photo_id = photo_id_counter
    photo_id_counter += 1

    profile_dir = f"profiles/{user_id}/photos"
    os.makedirs(profile_dir, exist_ok=True)

    photo_name = f"{photo_id}_{file.filename}"
    file_path = os.path.join(profile_dir, photo_name)
    with open(file_path, "wb") as f:
        shutil.copyfileobj(file.file, f)

    photos[photo_id] = {"user_id": user_id, "photo_name": photo_name, "file_path": file_path}
    return {"photo_id": photo_id, "photo_name": photo_name}

@app.get("/photos/{photo_id}")
def get_photo(photo_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    photo = photos.get(photo_id)
    if not photo or photo["user_id"] != user_id:
        raise HTTPException(status_code=404, detail="Photo not found")
    return {"photo_id": photo_id, "photo_name": photo["photo_name"]}

@app.get("/photos/{user_id}/{photo_name}")
def serve_photo(user_id: int, photo_name: str):
    file_path = f"profiles/{user_id}/photos/{photo_name}"
    if not os.path.exists(file_path):
        raise HTTPException(status_code=404, detail="Photo not found")
    return FileResponse(file_path)

