users = {}
tokens = {}
invoices = {}
line_items = {}
payment_reminders = {}
webhook_endpoints = {}

# Simple ID counters
user_id_counter = 1
invoice_id_counter = 1
line_item_id_counter = 1
reminder_id_counter = 1

