    username: str
    password: str
    email: str

class LoginRequest(BaseModel):
    username: str
    password: str

class InvoiceCreate(BaseModel):
    client_name: str
    client_email: str
    due_date: str
    tax_rate: float = 0.0
    notes: str = ""

class LineItemCreate(BaseModel):
    invoice_id: int
    description: str
    quantity: float
    unit_price: float

class WebhookRegister(BaseModel):
    url: str
    event: str

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Auth endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for user in users.values():
        if user["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password": req.password,
        "email": req.email,
        "created_at": datetime.now().isoformat()
    }
    return {"id": user_id, "username": req.username, "email": req.email}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = generate_token()
            tokens[token] = user["id"]
            return {"token": token, "user_id": user["id"]}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Invoice endpoints
@app.post("/invoices")
def create_invoice(inv: InvoiceCreate, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    global invoice_id_counter
    invoice_id = invoice_id_counter
    invoice_id_counter += 1
    invoices[invoice_id] = {
