        "tax_rate": inv.tax_rate,
        "notes": inv.notes,
        "created_at": datetime.now().isoformat(),
        "status": "pending",
        "line_items": []
    }
    return invoices[invoice_id]

@app.get("/invoices/{invoice_id}")
def get_invoice(invoice_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if invoice_id not in invoices:
        raise HTTPException(status_code=404, detail="Invoice not found")
    inv = invoices[invoice_id]
    if inv["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your invoice")
    # Calculate totals
    subtotal = sum(item["quantity"] * item["unit_price"] for item in inv["line_items"])
    tax = subtotal * (inv["tax_rate"] / 100)
    total = subtotal + tax
    result = inv.copy()
    result["subtotal"] = subtotal
    result["tax"] = tax
    result["total"] = total
    return result

@app.post("/invoices/{invoice_id}/send-reminder")
def send_reminder(invoice_id: int, authorization: str = Header(None)):
    user_id = get_current_user(authorization)
    if invoice_id not in invoices:
        raise HTTPException(status_code=404, detail="Invoice not found")
