        "user_id": user_id,
        "client_email": inv["client_email"],
        "sent_at": datetime.now().isoformat(),
        "status": "sent"
    }
    # Fire webhooks
    for wh_id, wh in list(webhook_endpoints.items()):
        if wh["event"] == "payment_reminder":
            try:
