from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import hashlib
import uuid
import time
import requests

app = FastAPI()

users = {}
tokens = {}
assignments = {}
submissions = {}
next_user_id = 1
next_assignment_id = 1
next_submission_id = 1
next_token_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class AssignmentCreate(BaseModel):
    title: str
    deadline: str
    rubric: str

class SubmissionCreate(BaseModel):
    assignment_id: int
    content: str

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/assignments")
def create_assignment(req: AssignmentCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_assignment_id
    aid = next_assignment_id
    next_assignment_id += 1
    assignments[aid] = {
        "id": aid,
        "title": req.title,
        "deadline": req.deadline,
        "rubric": req.rubric,
        "teacher_id": user_id
    }
    return assignments[aid]

@app.get("/assignments/{assignment_id}")
def get_assignment(assignment_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if assignment_id not in assignments:
        raise HTTPException(status_code=404, detail="Assignment not found")
    return assignments[assignment_id]

@app.post("/submissions")
def create_submission(req: SubmissionCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if req.assignment_id not in assignments:
        raise HTTPException(status_code=404, detail="Assignment not found")
    global next_submission_id
    sid = next_submission_id
    next_submission_id += 1
    # Simulate plagiarism check via external service (mock)
    plagiarism_score = 0.0
    try:
        resp = requests.post("https://api.plagiarismchecker.com/check", json={"content": req.content}, timeout=2)
        if resp.status_code == 200:
            plagiarism_score = resp.json().get("score", 0.0)
    except:
        plagiarism_score = 0.0
    submissions[sid] = {
        "id": sid,
        "assignment_id": req.assignment_id,
        "student_id": user_id,
        "content": req.content,
        "plagiarism_score": plagiarism_score,
        "grade": None
