import random
import string

app = FastAPI()

users = {}
tokens = {}
courses = {}
enrollments = {}
next_user_id = 1
next_course_id = 1
next_enrollment_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str, role: str = "student"):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": username, "password": password, "role": role}
    return {"id": user_id, "username": username, "role": role}

@app.post("/login")
def login(username: str, password: str):
    for user in users.values():
        if user["username"] == username and user["password"] == password:
            token = generate_token()
            tokens[token] = user
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/courses")
def create_course(name: str, instructor_id: int, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if user["role"] != "instructor":
        raise HTTPException(status_code=403, detail="Only instructors can create courses")
    global next_course_id
    course_id = next_course_id
    next_course_id += 1
    courses[course_id] = {"id": course_id, "name": name, "instructor_id": instructor_id}
    return courses[course_id]

@app.get("/courses/{course_id}")
def get_course(course_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    return courses[course_id]

@app.post("/enrollments")
def create_enrollment(student_id: int, course_id: int, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if user["role"] != "student":
        raise HTTPException(status_code=403, detail="Only students can enroll")
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    global next_enrollment_id
    enrollment_id = next_enrollment_id
    next_enrollment_id += 1
    enrollments[enrollment_id] = {"id": enrollment_id, "student_id": student_id, "course_id": course_id, "grade": None}
    return enrollments[enrollment_id]

@app.get("/enrollments/{enrollment_id}")
def get_enrollment(enrollment_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if enrollment_id not in enrollments:
        raise HTTPException(status_code=404, detail="Enrollment not found")
    return enrollments[enrollment_id]

@app.patch("/enrollments/{enrollment_id}/grade")
def set_grade(enrollment_id: int, grade: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if user["role"] != "instructor":
        raise HTTPException(status_code=403, detail="Only instructors can set grades")
    if enrollment_id not in enrollments:
        raise HTTPException(status_code=404, detail="Enrollment not found")
    enrollments[enrollment_id]["grade"] = grade
    return enrollments[enrollment_id]

@app.get("/courses/{course_id}/enrollments")
def get_enrollments_by_course(course_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if course_id not in courses:
        raise HTTPException(status_code=404, detail="Course not found")
    result = []
    for e in enrollments.values():
        if e["course_id"] == course_id:
            result.append(e)
    return result

