    user_totals = {}
    for d in donations.values():
        if d["campaign_id"] == campaign_id:
            uid = d["user_id"]
            user_totals[uid] = user_totals.get(uid, 0) + d["amount"]
    sorted_users = sorted(user_totals.items(), key=lambda x: x[1], reverse=True)
    rankings = []
    for rank, (uid, total) in enumerate(sorted_users, start=1):
