from pydantic import BaseModel
from typing import Optional, List
import secrets
from datetime import datetime, date

app = FastAPI()

users = {}
tokens = {}
appointments = {}
appointment_id_counter = 0
attendance_history = {}

class UserCreate(BaseModel):
    username: str
    password: str
    role: str = "patient"

class UserLogin(BaseModel):
    username: str
    password: str

class AppointmentCreate(BaseModel):
    patient_id: int
    doctor_id: int
    time: str
    duration: int
    notes: str = ""
    role: str = "patient"

class AppointmentSettingsUpdate(BaseModel):
    time: Optional[str] = None
    duration: Optional[int] = None
    notes: Optional[str] = None
    role: Optional[str] = None
    status: Optional[str] = None

class BulkReschedule(BaseModel):
    appointment_ids: List[int]
    new_time: str
    new_duration: Optional[int] = None

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(user: UserCreate):
    if user.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[user.username] = {"username": user.username, "password": user.password, "role": user.role}
    return {"message": "User created"}

@app.post("/login")
def login(user: UserLogin):
    if user.username not in users or users[user.username]["password"] != user.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = user.username
    return {"token": token}

@app.post("/appointments")
def create_appointment(appt: AppointmentCreate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    global appointment_id_counter
    appointment_id_counter += 1
    appt_data = appt.dict()
    appt_data["id"] = appointment_id_counter
    appt_data["created_by"] = current_user
    appt_data["created_at"] = datetime.now().isoformat()
    appointments[appointment_id_counter] = appt_data
    attendance_history[appointment_id_counter] = []
    return appt_data

@app.get("/appointments/{appointment_id}")
def get_appointment(appointment_id: int, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404, detail="Appointment not found")
    return appointments[appointment_id]

@app.put("/appointments/{appointment_id}/settings")
def update_appointment_settings(appointment_id: int, settings: AppointmentSettingsUpdate, authorization: str = Header(None)):
    current_user = get_current_user(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404, detail="Appointment not found")
    appt = appointments[appointment_id]
    if settings.time is not None:
        appt["time"] = settings.time
    if settings.duration is not None:
        appt["duration"] = settings.duration
    if settings.notes is not None:
        appt["notes"] = settings.notes
    if settings.role is not None:
        appt["role"] = settings.role
    if settings.status is not None:
        appt["status"] = settings.status
        attendance_history[appointment_id].append({"status": settings.status, "timestamp": datetime.now().isoformat(), "changed_by": current_user})
    return appt

@app.post("/appointments/bulk-reschedule")
def bulk_reschedule(bulk: BulkReschedule, authorization: str = Header(None)):
