    if product_id not in products:
        raise HTTPException(status_code=404, detail="Product not found")
    related = co_purchase_matrix.get(product_id, [])
    related_scores = [(pid, score) for pid, score in related if pid != product_id]
    related_scores.sort(key=lambda x: -x[1])
    top5 = [pid for pid, _ in related_scores[:5]]
    result = []
    for pid in top5:
        if pid in products:
            result.append(products[pid])
    return result

