from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import httpx
import secrets
import datetime

app = FastAPI()

users = {}
tokens = {}
itineraries = {}
itinerary_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ItineraryRequest(BaseModel):
    destination: str
    start_date: str
    end_date: str

class Attraction(BaseModel):
    name: str
    description: str
    estimated_cost: float

class DayPlan(BaseModel):
    day: int
    date: str
    attractions: List[Attraction]
    daily_cost: float

class Itinerary(BaseModel):
    id: int
    destination: str
    start_date: str
    end_date: str
    days: List[DayPlan]
    total_cost: float

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = req.password
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/itineraries")
def create_itinerary(req: ItineraryRequest, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global itinerary_id_counter
    start = datetime.datetime.strptime(req.start_date, "%Y-%m-%d")
    end = datetime.datetime.strptime(req.end_date, "%Y-%m-%d")
    num_days = (end - start).days + 1
    days = []
    total_cost = 0.0
    for i in range(num_days):
        current_date = (start + datetime.timedelta(days=i)).strftime("%Y-%m-%d")
        attractions = [
            Attraction(name=f"Sightseeing in {req.destination}", description="Explore local attractions", estimated_cost=50.0),
            Attraction(name="Local cuisine tasting", description="Try traditional food", estimated_cost=30.0)
        ]
        daily_cost = sum(a.estimated_cost for a in attractions)
        total_cost += daily_cost
        days.append(DayPlan(day=i+1, date=current_date, attractions=attractions, daily_cost=daily_cost))
    itinerary = Itinerary(id=itinerary_id_counter, destination=req.destination, start_date=req.start_date, end_date=req.end_date, days=days, total_cost=total_cost)
    itineraries[itinerary_id_counter] = itinerary
    itinerary_id_counter += 1
    return itinerary

@app.get("/itineraries/{itinerary_id}")
def get_itinerary(itinerary_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if itinerary_id not in itineraries:
        raise HTTPException(status_code=404, detail="Itinerary not found")
    return itineraries[itinerary_id]

@app.get("/itineraries/{itinerary_id}/weather")
def get_itinerary_weather(itinerary_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if itinerary_id not in itineraries:
        raise HTTPException(status_code=404, detail="Itinerary not found")
    itinerary = itineraries[itinerary_id]
    weather_data = []
    for day in itinerary.days:
        try:
            resp = httpx.get(f"https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.0060&daily=temperature_2m_max,temperature_2m_min&start_date={day.date}&end_date={day.date}")
            data = resp.json()
            weather_data.append({
                "date": day.date,
                "max_temp": data["daily"]["temperature_2m_max"][0] if data["daily"]["temperature_2m_max"] else None,
                "min_temp": data["daily"]["temperature_2m_min"][0] if data["daily"]["temperature_2m_min"] else None
            })
        except:
            weather_data.append({"date": day.date, "error": "Could not fetch weather"})
    return {"itinerary_id": itinerary_id, "weather": weather_data}

