    end = datetime.datetime.strptime(req.end_date, "%Y-%m-%d")
    num_days = (end - start).days + 1
    days = []
    total_cost = 0.0
    for i in range(num_days):
        current_date = (start + datetime.timedelta(days=i)).strftime("%Y-%m-%d")
        attractions = [
