        ]
        daily_cost = sum(a.estimated_cost for a in attractions)
        total_cost += daily_cost
        days.append(DayPlan(day=i+1, date=current_date, attractions=attractions, daily_cost=daily_cost))
    itinerary = Itinerary(id=itinerary_id_counter, destination=req.destination, start_date=req.start_date, end_date=req.end_date, days=days, total_cost=total_cost)
