from datetime import date, datetime
from typing import Optional
import hashlib
import secrets

app = FastAPI()

users = {}
tokens = {}
habits = {}
habit_logs = {}
next_user_id = 1
next_habit_id = 1

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth token")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global next_user_id
    for u in users.values():
        if u["username"] == username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {
        "id": user_id,
        "username": username,
        "password_hash": hashlib.sha256(password.encode()).hexdigest()
    }
    return {"id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    for u in users.values():
        if u["username"] == username and u["password_hash"] == hashlib.sha256(password.encode()).hexdigest():
            token = secrets.token_hex(32)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/habits")
def create_habit(name: str, frequency: str, goal: int, authorization: Optional[str] = Header(None)):
    global next_habit_id
    user_id = get_current_user(authorization)
    habit_id = next_habit_id
    next_habit_id += 1
    habits[habit_id] = {
        "id": habit_id,
        "user_id": user_id,
        "name": name,
        "frequency": frequency,
        "goal": goal,
        "created_at": datetime.utcnow().isoformat()
    }
    habit_logs[habit_id] = []
    return habits[habit_id]

@app.post("/habits/{habit_id}/check")
def check_habit(habit_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if habit_id not in habits:
        raise HTTPException(status_code=404, detail="Habit not found")
    if habits[habit_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your habit")
    today = date.today().isoformat()
    logs = habit_logs[habit_id]
    for log in logs:
        if log["date"] == today:
            return {"message": "Already checked today", "habit_id": habit_id}
    logs.append({"date": today, "timestamp": datetime.utcnow().isoformat()})
    return {"message": "Logged", "habit_id": habit_id}

@app.get("/habits/{habit_id}")
