            if check_date.isoformat() in dates:
                streak += 1
                check_date -= __import__('datetime').timedelta(days=1)
            else:
                break
    elif habit["frequency"] == "weekly":
        # Check current week
        today = date.today()
        start_of_week = today - __import__('datetime').timedelta(days=today.weekday())
        while True:
            week_start = start_of_week - __import__('datetime').timedelta(weeks=streak)
            week_end = week_start + __import__('datetime').timedelta(days=6)
