vocabulary = {1: {"word": "serendipity", "translation": "счастливая случайность", "example": "Finding that book was pure serendipity.", "difficulty": 3}}
quiz_sessions = {}
next_user_id = 1
next_vocab_id = 2
next_quiz_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class QuizAnswer(BaseModel):
    session_id: int
    question_id: int
    answer: str

def generate_token():
    return str(uuid.uuid4())

def get_current_user(authorization: str = Header(default=None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    if any(u["username"] == req.username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for user in users.values():
        if user["username"] == req.username and user["password"] == req.password:
            token = generate_token()
            tokens[token] = user["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/vocabulary/{id}")
def get_vocabulary(id: int, authorization: str = Header(default=None)):
    user_id = get_current_user(authorization)
    if id not in vocabulary:
        raise HTTPException(status_code=404, detail="Vocabulary not found")
    vocab = vocabulary[id]
    # Check if the vocabulary belongs to the current user
    if "owner_id" in vocab and vocab["owner_id"] != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return vocab

@app.post("/vocabulary")
def create_vocabulary(item: dict, authorization: str = Header(default=None)):
    global next_vocab_id
    user_id = get_current_user(authorization)
    vocab_id = next_vocab_id
    next_vocab_id += 1
    vocabulary[vocab_id] = {"id": vocab_id, "owner_id": user_id, **item}
    return vocabulary[vocab_id]

@app.get("/vocabulary")
def get_random_vocabulary(authorization: str = Header(default=None)):
    user_id = get_current_user(authorization)
    user_vocab = [v for v in vocabulary.values() if v.get("owner_id") == user_id or "owner_id" not in v]
    if not user_vocab:
        raise HTTPException(status_code=404, detail="No vocabulary available")
    vocab = random.choice(user_vocab)
    return vocab

@app.post("/quiz/start")
def start_quiz(authorization: str = Header(default=None)):
    global next_quiz_id
    user_id = get_current_user(authorization)
    if len(vocabulary) < 10:
        raise HTTPException(status_code=400, detail="Not enough vocabulary items (need at least 10)")
    questions = random.sample(list(vocabulary.values()), 10)
    session_id = next_quiz_id
    next_quiz_id += 1
    quiz_sessions[session_id] = {
        "user_id": user_id,
        "questions": questions,
        "current_question": 0,
        "score": 0
    }
    return {"session_id": session_id, "total_questions": 10}

@app.post("/quiz/answer")
def answer_quiz(req: QuizAnswer, authorization: str = Header(default=None)):
    user_id = get_current_user(authorization)
    if req.session_id not in quiz_sessions:
        raise HTTPException(status_code=404, detail="Quiz session not found")
    session = quiz_sessions[req.session_id]
    if session["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your quiz")
    if req.question_id < 0 or req.question_id >= len(session["questions"]):
        raise HTTPException(status_code=400, detail="Invalid question ID")
    question = session["questions"][req.question_id]
    correct = question["word"]
    is_correct = req.answer.strip().lower() == correct.lower()
    if is_correct:
        session["score"] += 1
    return {
        "correct_answer": correct,
        "is_correct": is_correct,
        "score": session["score"],
        "total": len(session["questions"])
    }

