    get_current_user(authorization)
    lot = lots.get(lot_id)
    if not lot:
        raise HTTPException(status_code=404, detail="Lot not found")
    return {"id": lot_id, "name": lot["name"], "total": lot["total"], "available": lot["available"]}

@app.post("/reservations")
def create_reservation(req: ReservationRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global reservation_id_counter
    lot = lots.get(req.lot_id)
    if not lot:
        raise HTTPException(status_code=404, detail="Lot not found")
    if lot["available"] <= 0:
        raise HTTPException(status_code=400, detail="No spots available")
    rid = reservation_id_counter
    reservation_id_counter += 1
    reservations[rid] = {
        "id": rid,
        "user_id": user_id,
        "lot_id": req.lot_id,
        "start_time": req.start_time,
        "end_time": req.end_time,
        "license_plate": req.license_plate,
        "status": "active"
    }
    lot["available"] -= 1
    return reservations[rid]

@app.get("/reservations/{reservation_id}")
def get_reservation(reservation_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    res = reservations.get(reservation_id)
    if not res:
        raise HTTPException(status_code=404, detail="Reservation not found")
    return res

@app.delete("/reservations/{reservation_id}")
def cancel_reservation(reservation_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    res = reservations.get(reservation_id)
    if not res:
        raise HTTPException(status_code=404, detail="Reservation not found")
    if res["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your reservation")
    lot = lots[res["lot_id"]]
    lot["available"] += 1
    del reservations[reservation_id]
    return {"detail": "Reservation cancelled"}

