from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Dict
import random
import string

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
tournaments = {}
matches = {}
next_user_id = 1
next_tournament_id = 1
next_match_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    for user_id, user_token in tokens.items():
        if user_token == token:
            return user_id
    raise HTTPException(status_code=401, detail="Invalid token")

class UserCreate(BaseModel):
    username: str
    password: str

class UserLogin(BaseModel):
    username: str
    password: str

class TournamentCreate(BaseModel):
    name: str
    participants: List[str]
    bracket_style: str = "single"  # single or double

class MatchScore(BaseModel):
    score1: int
    score2: int

@app.post("/signup")
def signup(user: UserCreate):
    global next_user_id
    for u in users.values():
        if u["username"] == user.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": user.username, "password": user.password}
    token = generate_token()
    tokens[user_id] = token
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(user: UserLogin):
    for uid, u in users.items():
        if u["username"] == user.username and u["password"] == user.password:
            token = generate_token()
            tokens[uid] = token
            return {"user_id": uid, "token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return {"user_id": user_id, "username": users[user_id]["username"]}

@app.post("/tournaments")
def create_tournament(tournament: TournamentCreate, authorization: str = Header(...)):
    global next_tournament_id, next_match_id
    user_id = get_current_user(authorization)

    participants = tournament.participants
    if len(participants) < 2:
        raise HTTPException(status_code=400, detail="Need at least 2 participants")
    if (len(participants) & (len(participants) - 1)) != 0:
        raise HTTPException(status_code=400, detail="Number of participants must be power of 2")

    tournament_id = next_tournament_id
    next_tournament_id += 1

    # Generate bracket
    random.shuffle(participants)
    bracket = []
    round_matches = []
    for i in range(0, len(participants), 2):
        match_id = next_match_id
        next_match_id += 1
        round_matches.append({
            "match_id": match_id,
            "participant1": participants[i],
            "participant2": participants[i+1],
            "score1": None,
            "score2": None,
            "winner": None
        })
        matches[match_id] = round_matches[-1]
    bracket.append(round_matches)

    # Generate subsequent rounds
    while len(round_matches) > 1:
        next_round = []
        for _ in range(0, len(round_matches), 2):
            match_id = next_match_id
            next_match_id += 1
            next_round.append({
                "match_id": match_id,
                "participant1": None,
                "participant2": None,
                "score1": None,
                "score2": None,
                "winner": None
            })
            matches[match_id] = next_round[-1]
        bracket.append(next_round)
        round_matches = next_round

    tournaments[tournament_id] = {
        "name": tournament.name,
        "bracket_style": tournament.bracket_style,
        "participants": participants,
        "bracket": bracket,
        "created_by": user_id
    }

    return {"tournament_id": tournament_id, "bracket": bracket}

@app.get("/tournaments/{tournament_id}/bracket")
def get_bracket(tournament_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if tournament_id not in tournaments:
        raise HTTPException(status_code=404, detail="Tournament not found")
    return tournaments[tournament_id]["bracket"]

@app.post("/matches/{match_id}/score")
def update_score(match_id: int, score: MatchScore, authorization: str = Header(...)):
    get_current_user(authorization)
    if match_id not in matches:
        raise HTTPException(status_code=404, detail="Match not found")

    match = matches[match_id]
    if match["score1"] is not None:
        raise HTTPException(status_code=400, detail="Match already scored")

    match["score1"] = score.score1
    match["score2"] = score.score2
    if score.score1 > score.score2:
        match["winner"] = match["participant1"]
    elif score.score2 > score.score1:
        match["winner"] = match["participant2"]
    else:
        raise HTTPException(status_code=400, detail="Cannot have tie")

    # Propagate winner to next round
    for tid, tournament in tournaments.items():
        for round_idx, round_matches in enumerate(tournament["bracket"]):
            for m_idx, m in enumerate(round_matches):
                if m["match_id"] == match_id:
                    if round_idx + 1 < len(tournament["bracket"]):
                        next_round = tournament["bracket"][round_idx + 1]
                        next_match_idx = m_idx // 2
                        if m_idx % 2 == 0:
                            next_round[next_match_idx]["participant1"] = match["winner"]
                        else:
                            next_round[next_match_idx]["participant2"] = match["winner"]
                    return {"match_id": match_id, "winner": match["winner"]}

    return {"match_id": match_id, "winner": match["winner"]}

