def update_score(match_id: int, score: MatchScore, authorization: str = Header(...)):
    get_current_user(authorization)
    if match_id not in matches:
        raise HTTPException(status_code=404, detail="Match not found")

    match = matches[match_id]
    if match["score1"] is not None:
        raise HTTPException(status_code=400, detail="Match already scored")

    match["score1"] = score.score1
    match["score2"] = score.score2
    if score.score1 > score.score2:
        match["winner"] = match["participant1"]
    elif score.score2 > score.score1:
        match["winner"] = match["participant2"]
    else:
        raise HTTPException(status_code=400, detail="Cannot have tie")

    # Propagate winner to next round
    for tid, tournament in tournaments.items():
        for round_idx, round_matches in enumerate(tournament["bracket"]):
            for m_idx, m in enumerate(round_matches):
                if m["match_id"] == match_id:
                    if round_idx + 1 < len(tournament["bracket"]):
                        next_round = tournament["bracket"][round_idx + 1]
                        next_match_idx = m_idx // 2
                        if m_idx % 2 == 0:
                            next_round[next_match_idx]["participant1"] = match["winner"]
                        else:
                            next_round[next_match_idx]["participant2"] = match["winner"]
                    return {"match_id": match_id, "winner": match["winner"]}

    return {"match_id": match_id, "winner": match["winner"]}

