from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
next_user_id = 1

jobs = {}
next_job_id = 1

applications = {}
next_app_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class JobCreate(BaseModel):
    title: str
    company: str
    salary_range: str
    remote_level: str

class ApplicationCreate(BaseModel):
    job_id: int
    applicant_name: str
    cover_letter_snippet: str

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    for uid, t in tokens.items():
        if t == token:
            return uid
    raise HTTPException(status_code=401, detail="Invalid token")

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    uid = next_user_id
    next_user_id += 1
    users[uid] = {"username": req.username, "password": req.password}
    return {"user_id": uid}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/jobs")
def get_jobs(authorization: str = Header(...)):
    get_current_user(authorization)
    return list(jobs.values())

@app.get("/jobs/{job_id}")
def get_job(job_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if job_id not in jobs:
        raise HTTPException(status_code=404, detail="Job not found")
    return jobs[job_id]

@app.post("/jobs")
def create_job(job: JobCreate, authorization: str = Header(...)):
    get_current_user(authorization)
    global next_job_id
    jid = next_job_id
    next_job_id += 1
    jobs[jid] = {"id": jid, **job.dict()}
    return jobs[jid]

@app.get("/applications/{app_id}")
def get_application(app_id: int, authorization: str = Header(...)):
    get_current_user(authorization)
    if app_id not in applications:
        raise HTTPException(status_code=404, detail="Application not found")
    return applications[app_id]

@app.post("/applications")
def create_application(app: ApplicationCreate, authorization: str = Header(...)):
    get_current_user(authorization)
    if app.job_id not in jobs:
        raise HTTPException(status_code=404, detail="Job not found")
    global next_app_id
    aid = next_app_id
    next_app_id += 1
    applications[aid] = {"id": aid, **app.dict(), "status": "pending"}
    return applications[aid]

