import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Step 1: Sign up
    signup_resp = session.post(f"{BASE_URL}/signup", json={"username": "testuser", "password": "testpass"})
    if signup_resp.status_code != 200:
        return False

    # Step 2: Log in
    login_resp = session.post(f"{BASE_URL}/login", json={"username": "testuser", "password": "testpass"})
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Step 3: Create a sitter (resource)
    headers = {"Authorization": f"Bearer {token}"}
    sitter_data = {
        "name": "Test Sitter",
        "hourly_rate": 20.0,
        "distance": 5.0,
        "pet_type_preferences": ["dog", "cat"]
    }
    sitter_resp = session.post(f"{BASE_URL}/sitters", json=sitter_data, headers=headers)
    if sitter_resp.status_code != 200:
        return False
    sitter_id = sitter_resp.json().get("sitter_id")
    if not sitter_id:
        return False

    # Step 4: Fetch the sitter (the user's own resource)
    fetch_resp = session.get(f"{BASE_URL}/sitters/{sitter_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    fetched_sitter = fetch_resp.json()
    if fetched_sitter.get("name") != "Test Sitter":
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

