from typing import Optional
import random
import string

app = FastAPI()

users = {}
events = {}
orders = {}
tokens = {}
next_user_id = 1
next_event_id = 1
next_order_id = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class UserCreate(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class EventCreate(BaseModel):
    title: str
    speaker: str
    date: str
    capacity: int
    price: float

class PurchaseRequest(BaseModel):
    event_id: int

@app.post("/signup")
def signup(user: UserCreate):
    global next_user_id
    for u in users.values():
        if u["username"] == user.username:
            raise HTTPException(status_code=400, detail="User exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": user.username, "password": user.password}
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/events")
def list_events():
    upcoming = [e for e in events.values() if e["capacity"] > 0]
    return {"events": upcoming}

@app.get("/events/{event_id}")
def get_event(event_id: int):
    event = events.get(event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    return event

@app.post("/events")
def create_event(event: EventCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_event_id
    event_id = next_event_id
    next_event_id += 1
    events[event_id] = {
        "id": event_id,
        "title": event.title,
        "speaker": event.speaker,
        "date": event.date,
        "capacity": event.capacity,
        "price": event.price
    }
    return events[event_id]

@app.post("/purchase")
def purchase_ticket(purchase: PurchaseRequest, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    event = events.get(purchase.event_id)
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    if event["capacity"] <= 0:
        raise HTTPException(status_code=400, detail="Event sold out")
    event["capacity"] -= 1
    global next_order_id
    order_id = next_order_id
    next_order_id += 1
    join_link = f"https://zoom.us/j/{random.randint(100000000, 999999999)}"
    orders[order_id] = {
        "id": order_id,
        "user_id": user_id,
        "event_id": purchase.event_id,
        "join_link": join_link
    }
    return {
        "order_id": order_id,
        "event_title": event["title"],
        "join_link": join_link,
        "message": "Confirmation sent (simulated)"
    }

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

