from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
from datetime import datetime, timedelta

app = FastAPI()

users = {}
tokens = {}
appointments = {}
appointment_id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class AppointmentCreate(BaseModel):
    patient_name: str
    reason: str
    status: str = "scheduled"
    scheduled_time: Optional[str] = None

class AppointmentUpdate(BaseModel):
    patient_name: Optional[str] = None
    reason: Optional[str] = None
    status: Optional[str] = None
    scheduled_time: Optional[str] = None

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization.split(" ", 1)[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = {"password": req.password}
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = f"tok_{req.username}_{datetime.utcnow().timestamp()}"
    tokens[token] = req.username
    return {"token": token}

@app.get("/appointments")
def get_appointments(authorization: str = Header(...)):
    user = get_current_user(authorization)
    now = datetime.utcnow()
    upcoming = []
    for aid, appt in appointments.items():
        if appt.get("scheduled_time"):
            try:
                appt_time = datetime.fromisoformat(appt["scheduled_time"])
                if appt_time > now:
                    upcoming.append({
                        "id": aid,
                        "patient_name": appt["patient_name"],
                        "reason": appt["reason"],
                        "status": appt["status"]
                    })
            except:
                pass
    return upcoming

@app.post("/appointments")
def create_appointment(req: AppointmentCreate, authorization: str = Header(...)):
    global appointment_id_counter
    user = get_current_user(authorization)
    aid = appointment_id_counter
    appointments[aid] = {
        "patient_name": req.patient_name,
        "reason": req.reason,
        "status": req.status,
        "scheduled_time": req.scheduled_time or datetime.utcnow().isoformat()
    }
    appointment_id_counter += 1
    return {"id": aid, "message": "Appointment created"}

@app.get("/appointments/{appointment_id}")
def get_appointment(appointment_id: int, authorization: str = Header(...)):
    user = get_current_user(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404, detail="Appointment not found")
    return appointments[appointment_id]

@app.put("/appointments/{appointment_id}")
def update_appointment(appointment_id: int, req: AppointmentUpdate, authorization: str = Header(...)):
    user = get_current_user(authorization)
    if appointment_id not in appointments:
        raise HTTPException(status_code=404, detail="Appointment not found")
    appt = appointments[appointment_id]
    if req.patient_name is not None:
        appt["patient_name"] = req.patient_name
    if req.reason is not None:
        appt["reason"] = req.reason
    if req.status is not None:
        appt["status"] = req.status
    if req.scheduled_time is not None:
        appt["scheduled_time"] = req.scheduled_time
    return {"message": "Appointment updated", "appointment": appt}

