import requests
import sys

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Signup
    signup_resp = session.post(f"{BASE_URL}/signup", json={"username": "testuser", "password": "testpass"})
    if signup_resp.status_code not in (200, 201):
        return False

    # Login
    login_resp = session.post(f"{BASE_URL}/login", json={"username": "testuser", "password": "testpass"})
    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    # Create appointment
    headers = {"Authorization": f"Bearer {token}"}
    create_resp = session.post(f"{BASE_URL}/appointments", json={
        "patient_name": "John Doe",
        "reason": "Checkup"
    }, headers=headers)
    if create_resp.status_code not in (200, 201):
        return False
    appointment_id = create_resp.json().get("id")
    if not appointment_id:
        return False

    # Fetch the created appointment
    fetch_resp = session.get(f"{BASE_URL}/appointments/{appointment_id}", headers=headers)
    if fetch_resp.status_code != 200:
        return False
    data = fetch_resp.json()
    if data.get("patient_name") != "John Doe":
        return False

    return True

if __name__ == "__main__":
    if test_golden_path():
        print("SPEC_PASS")
        sys.exit(0)
    else:
        print("SPEC_FAIL")
        sys.exit(1)

