from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import secrets
import uvicorn

app = FastAPI()

users = {}
tokens = {}
tasks = {}
task_id_counter = 0

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class Task(BaseModel):
    title: str
    priority: Optional[int] = 0
    due_date: Optional[str] = None
    estimated_hours: Optional[float] = 0.0

class BulkTasks(BaseModel):
    tasks: List[Task]

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[req.username] = req.password
    token = secrets.token_hex(32)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = req.username
    return {"token": token}

@app.get("/tasks")
def list_tasks(authorization: str = Header(None)):
    get_current_user(authorization)
    return list(tasks.values())

@app.get("/tasks/{task_id}")
def get_task(task_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if task_id not in tasks:
        raise HTTPException(status_code=404, detail="Task not found")
    return tasks[task_id]

@app.post("/tasks")
def create_task(task: Task, authorization: str = Header(None)):
    get_current_user(authorization)
    global task_id_counter
    task_id_counter += 1
    tasks[task_id_counter] = {"id": task_id_counter, **task.dict()}
    return tasks[task_id_counter]

@app.post("/tasks/bulk")
def create_bulk_tasks(bulk: BulkTasks, authorization: str = Header(None)):
    get_current_user(authorization)
    global task_id_counter
    created = []
    for task in bulk.tasks:
        task_id_counter += 1
        tasks[task_id_counter] = {"id": task_id_counter, **task.dict()}
        created.append(tasks[task_id_counter])
    return created

