from fastapi import FastAPI, HTTPException, Header
from typing import Optional
import random
import string
import hashlib

app = FastAPI()

users = {}
tokens = {}
shipments = {}
shipment_id_counter = 1
user_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    global user_id_counter
    if any(u["username"] == username for u in users.values()):
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": username,
        "password": hashlib.sha256(password.encode()).hexdigest()
    }
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(username: str, password: str):
    for uid, user in users.items():
        if user["username"] == username and user["password"] == hashlib.sha256(password.encode()).hexdigest():
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/shipments")
def get_shipments(authorization: str = Header(None)):
    get_user_from_token(authorization)
    active = []
    for sid, s in shipments.items():
        if s["status"] != "delivered":
            active.append({
                "id": sid,
                "origin": s["origin"],
                "destination": s["destination"],
                "status": s["status"],
                "estimated_delivery": s["estimated_delivery"]
            })
    return active

@app.get("/shipments/{shipment_id}")
def get_shipment(shipment_id: int, authorization: str = Header(None)):
    get_user_from_token(authorization)
    if shipment_id not in shipments:
        raise HTTPException(status_code=404, detail="Shipment not found")
    return shipments[shipment_id]

@app.post("/shipments")
