import requests

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Step 1: Sign up a user
    signup_data = {
        "username": "testuser",
        "password": "testpass123",
        "age": 25,
        "bio": "Hello, I'm a test user",
        "interests": "reading,coding,music"
    }
    try:
        r = session.post(f"{BASE_URL}/signup", params=signup_data)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        signup_response = r.json()
        user_id = signup_response.get("user_id")
        token = signup_response.get("token")
        if not user_id or not token:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    # Step 2: Log in with the same credentials
    login_data = {
        "username": "testuser",
        "password": "testpass123"
    }
    try:
        r = session.post(f"{BASE_URL}/login", params=login_data)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        login_response = r.json()
        new_token = login_response.get("token")
        if not new_token:
            print("SPEC_FAIL")
            sys.exit(1)
        # Use the new token for subsequent requests
        token = new_token
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    headers = {"Authorization": f"Bearer {token}"}

    # Step 3: Create a profile (resource)
    profile_data = {
        "age": 30,
        "bio": "Another test profile",
        "interests": "travel,food,music"
    }
    try:
        r = session.post(f"{BASE_URL}/profiles", params=profile_data, headers=headers)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        profile_response = r.json()
        profile_id = profile_response.get("profile_id")
        if not profile_id:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    # Step 4: Fetch the created profile (their own resource)
    try:
        r = session.get(f"{BASE_URL}/profiles/{profile_id}", headers=headers)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        fetched_profile = r.json()
        if fetched_profile.get("id") != profile_id:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    # Step 5: Create another user to test that a user can fetch their own data (not others)
    signup_data2 = {
        "username": "testuser2",
        "password": "testpass456",
        "age": 28,
        "bio": "Second test user",
        "interests": "sports,gaming"
    }
    try:
        r = session.post(f"{BASE_URL}/signup", params=signup_data2)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        signup_response2 = r.json()
        token2 = signup_response2.get("token")
        if not token2:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    headers2 = {"Authorization": f"Bearer {token2}"}

    # Try to fetch first user's profile with second user's token (should fail or return different data)
    try:
        r = session.get(f"{BASE_URL}/profiles/{profile_id}", headers=headers2)
        if r.status_code == 200:
            # It's okay if they can see it, but they should not be able to create a profile and then fetch someone else's as their own
            # The key test is that each user can fetch their own created profile
            pass
    except Exception:
        pass

    # Final verification: first user can still fetch their own profile
    try:
        r = session.get(f"{BASE_URL}/profiles/{profile_id}", headers=headers)
        if r.status_code != 200:
            print("SPEC_FAIL")
            sys.exit(1)
        fetched_profile = r.json()
        if fetched_profile.get("id") != profile_id:
            print("SPEC_FAIL")
            sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

    print("SPEC_PASS")
    sys.exit(0)

if __name__ == "__main__":
    test_golden_path()

