from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, date, time, timedelta
import secrets
import hashlib

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
slots = {}
bookings = {}
slot_id_counter = 1
booking_id_counter = 1

# Predefined time slots (9:00 AM to 5:00 PM, 30 min intervals)
def generate_slots_for_date(target_date):
    slots_list = []
    start_time = time(9, 0)
    end_time = time(17, 0)
    current = datetime.combine(target_date, start_time)
    end = datetime.combine(target_date, end_time)
    while current < end:
        slot_start = current
        slot_end = current + timedelta(minutes=30)
        slots_list.append({
            "start": slot_start.isoformat(),
            "end": slot_end.isoformat()
        })
        current = slot_end
    return slots_list

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

# Auth
@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    users[username] = hashlib.sha256(password.encode()).hexdigest()
    return {"message": "User created"}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != hashlib.sha256(password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

# Slots
@app.get("/slots")
def get_slots(date_str: str, duration_minutes: int = 30, authorization: str = Header(None)):
    user = get_current_user(authorization)
    try:
        target_date = date.fromisoformat(date_str)
    except:
        raise HTTPException(status_code=400, detail="Invalid date format (YYYY-MM-DD)")

    all_slots = generate_slots_for_date(target_date)
    available = []
    for slot in all_slots:
        slot_start = datetime.fromisoformat(slot["start"])
        slot_end = datetime.fromisoformat(slot["end"])
        # Check if slot is already booked
        is_booked = False
        for bid, booking in bookings.items():
            if booking["date"] == date_str and booking["start"] == slot["start"]:
                is_booked = True
                break
        if not is_booked:
            available.append(slot)
    return {"date": date_str, "duration_minutes": duration_minutes, "slots": available}

@app.post("/slots/book")
def book_slot(date_str: str, start_time_str: str, authorization: str = Header(None)):
    global booking_id_counter
    user = get_current_user(authorization)
    try:
        target_date = date.fromisoformat(date_str)
        start_dt = datetime.fromisoformat(start_time_str)
        if start_dt.date() != target_date:
            raise HTTPException(status_code=400, detail="Start time must match date")
    except:
        raise HTTPException(status_code=400, detail="Invalid date or time format")

    # Check if slot already booked
    for bid, booking in bookings.items():
        if booking["date"] == date_str and booking["start"] == start_time_str:
            raise HTTPException(status_code=409, detail="Slot already booked")

    # Check if slot is within business hours
    valid_slots = generate_slots_for_date(target_date)
    valid = False
    for slot in valid_slots:
        if slot["start"] == start_time_str:
            valid = True
            break
    if not valid:
        raise HTTPException(status_code=400, detail="Invalid slot time")

    booking_id = booking_id_counter
    booking_id_counter += 1
    bookings[booking_id] = {
        "id": booking_id,
        "user": user,
        "date": date_str,
        "start": start_time_str,
        "end": (datetime.fromisoformat(start_time_str) + timedelta(minutes=30)).isoformat()
    }
    confirmation_code = secrets.token_hex(8).upper()
    return {"confirmation_code": confirmation_code, "booking_id": booking_id}

# Generic resource endpoints
@app.get("/{resource}/{resource_id}")
def get_resource(resource: str, resource_id: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if resource == "bookings":
        if resource_id not in bookings:
            raise HTTPException(status_code=404, detail="Not found")
        return bookings[resource_id]
    elif resource == "slots":
        # Slots are generated on the fly, not stored by ID
        raise HTTPException(status_code=400, detail="Use GET /slots?date=...")
    else:
        raise HTTPException(status_code=400, detail="Unknown resource")

@app.post("/{resource}")
def create_resource(resource: str, data: dict, authorization: str = Header(None)):
    user = get_current_user(authorization)
    if resource == "bookings":
        # Use the dedicated booking endpoint
        raise HTTPException(status_code=400, detail="Use POST /slots/book")
    elif resource == "slots":
        raise HTTPException(status_code=400, detail="Slots are generated, not created")
    else:
        raise HTTPException(status_code=400, detail="Unknown resource")

