    available = []
    for t in tables.values():
        if all(abs((dt - slot).total_seconds()) >= 7200 for slot in t["reserved_slots"]):
            available.append({
                "id": t["id"],
                "capacity": t["capacity"],
                "section": t["section"]
            })
    return available

