import secrets
import random
from datetime import datetime, timedelta
import math

app = FastAPI()

users = {}
tokens = {}
properties = {}
comps_data = {}
market_trends = {}
next_user_id = 1
next_property_id = 1

class SignupRequest(BaseModel):
    email: str
    password: str

class LoginRequest(BaseModel):
    email: str
    password: str

class PropertyCreate(BaseModel):
    address: str
    price: float
    sqft: float
    beds: int
    baths: int
    zip_code: str

class CompResponse(BaseModel):
    property_id: int
    address: str
    sold_price: float
    price_per_sqft: float
    days_on_market: int
    sold_date: str

class MarketTrend(BaseModel):
    month: str
    median_price: float

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["email"] == req.email:
            raise HTTPException(status_code=400, detail="Email already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "email": req.email, "password": req.password}
    return {"user_id": user_id, "email": req.email}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["email"] == req.email and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/properties")
def create_property(prop: PropertyCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global next_property_id
    prop_id = next_property_id
    next_property_id += 1
    properties[prop_id] = {
        "id": prop_id,
        "address": prop.address,
        "price": prop.price,
        "sqft": prop.sqft,
        "beds": prop.beds,
        "baths": prop.baths,
        "zip_code": prop.zip_code,
        "created_at": datetime.now().isoformat()
    }
    return properties[prop_id]

@app.get("/properties/{property_id}")
def get_property(property_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    prop = properties.get(property_id)
    if not prop:
        raise HTTPException(status_code=404, detail="Property not found")
    return prop

@app.get("/properties/{property_id}/comps")
def get_comps(property_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    prop = properties.get(property_id)
    if not prop:
        raise HTTPException(status_code=404, detail="Property not found")

    if property_id not in comps_data:
        seed = property_id * 42
        rng = random.Random(seed)
        comps = []
        base_price = prop["price"]
        base_sqft = prop["sqft"]
        for i in range(5):
            comp_id = property_id * 100 + i
            price_mult = 0.8 + rng.random() * 0.4
            sqft_mult = 0.85 + rng.random() * 0.3
            sold_price = round(base_price * price_mult, 2)
            sqft = round(base_sqft * sqft_mult, 1)
            price_per_sqft = round(sold_price / sqft, 2)
            days = rng.randint(10, 120)
            sold_date = (datetime.now() - timedelta(days=days)).strftime("%Y-%m-%d")
            comps.append({
                "property_id": comp_id,
                "address": f"{100 + i} Similar St, {prop['zip_code']}",
                "sold_price": sold_price,
                "price_per_sqft": price_per_sqft,
                "days_on_market": days,
                "sold_date": sold_date
            })
        comps_data[property_id] = comps

    return {"comps": comps_data[property_id]}

@app.get("/market/trends")
def get_market_trends(authorization: str = Header(None)):
    get_current_user(authorization)

    if not market_trends:
        rng = random.Random(42)
        base_price = 450000
        trends = []
        for i in range(12):
            month_date = datetime.now() - timedelta(days=30 * (11 - i))
            month_str = month_date.strftime("%Y-%m")
            variation = 1 + (rng.random() - 0.5) * 0.1
            trend_price = round(base_price * (1 + i * 0.005) * variation, 2)
            trends.append({
                "month": month_str,
                "median_price": trend_price
            })
        market_trends["data"] = trends

    return {"trends": market_trends["data"]}

