def get_user_id(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/playlists")
def create_playlist(req: CreatePlaylistRequest, authorization: str = Header(...)):
    user_id = get_user_id(authorization)
    global playlist_id_counter
    pid = playlist_id_counter
    playlist_id_counter += 1
    playlists[pid] = {"id": pid, "name": req.name, "user_id": user_id, "created_at": datetime.now().isoformat()}
    playlist_videos[pid] = []
    return playlists[pid]

@app.get("/playlists/{playlist_id}")
def get_playlist(playlist_id: int, authorization: str = Header(...)):
    user_id = get_user_id(authorization)
    pl = playlists.get(playlist_id)
    if not pl:
        raise HTTPException(status_code=404, detail="Playlist not found")
    if pl["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your playlist")
    return {"playlist": pl, "videos": playlist_videos.get(playlist_id, [])}

