    global video_id_counter
    vid = video_id_counter
    video_id_counter += 1
    video = {"id": vid, "url": req.url, "title": req.title, "resume_timestamp": 0}
    playlist_videos[playlist_id].append(video)
    return video

@app.get("/playlists/{playlist_id}/watch")
def watch_playlist(playlist_id: int, authorization: str = Header(...)):
    user_id = get_user_id(authorization)
    pl = playlists.get(playlist_id)
    if not pl:
        raise HTTPException(status_code=404, detail="Playlist not found")
    videos = playlist_videos.get(playlist_id, [])
    recommendations = []
    for pid, p in playlists.items():
        if pid != playlist_id and p["user_id"] == user_id:
            recommendations.append({"id": pid, "name": p["name"]})
    return {
        "playlist_name": pl["name"],
        "videos": [{"url": v["url"], "resume_timestamp": v["resume_timestamp"]} for v in videos],
        "recommendations": recommendations[:5]
    }

