class RecordExpenseRequest(BaseModel):
    group_id: int
    paid_by_user_id: int
    amount: float
    currency: str = "USD"
    splits: List[dict]  # [{"user_id": 1, "percentage": 50}, ...]

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"user_id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = str(uuid.uuid4())
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/users/{user_id}")
def get_user(user_id: int, authorization: Optional[str] = Header(None)):
    current_user_id = get_current_user(authorization)
    if current_user_id != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    if user_id not in users:
        raise HTTPException(status_code=404, detail="User not found")
    return users[user_id]

@app.post("/groups")
def create_group(req: CreateGroupRequest, authorization: Optional[str] = Header(None)):
    global group_id_counter
    get_current_user(authorization)
    for mid in req.member_ids:
        if mid not in users:
            raise HTTPException(status_code=400, detail=f"User {mid} not found")
    group_id = group_id_counter
    group_id_counter += 1
    groups[group_id] = {"id": group_id, "name": req.name, "member_ids": req.member_ids, "expenses": []}
    return groups[group_id]

@app.get("/groups/{group_id}")
def get_group(group_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    return groups[group_id]

@app.post("/expenses/record")
def record_expense(req: RecordExpenseRequest, authorization: Optional[str] = Header(None)):
    global expense_id_counter
    get_current_user(authorization)
    if req.group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    group = groups[req.group_id]
    if req.paid_by_user_id not in group["member_ids"]:
        raise HTTPException(status_code=400, detail="Payer not in group")
    total_pct = sum(s["percentage"] for s in req.splits)
    if abs(total_pct - 100.0) > 0.01:
        raise HTTPException(status_code=400, detail="Percentages must sum to 100")
    for s in req.splits:
        if s["user_id"] not in group["member_ids"]:
            raise HTTPException(status_code=400, detail=f"User {s['user_id']} not in group")
    expense_id = expense_id_counter
    expense_id_counter += 1
    expense = {
        "id": expense_id,
        "group_id": req.group_id,
        "paid_by_user_id": req.paid_by_user_id,
        "amount": req.amount,
        "currency": req.currency,
        "splits": req.splits
    }
    expenses[expense_id] = expense
    group["expenses"].append(expense_id)
    return expense

@app.get("/groups/{group_id}/balances")
def get_balances(group_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if group_id not in groups:
        raise HTTPException(status_code=404, detail="Group not found")
    group = groups[group_id]
    balances = {uid: 0.0 for uid in group["member_ids"]}
    for eid in group["expenses"]:
        exp = expenses[eid]
        for split in exp["splits"]:
            user_id = split["user_id"]
            percentage = split["percentage"]
            owes_amount = exp["amount"] * (percentage / 100.0)
            balances[user_id] -= owes_amount
            balances[exp["paid_by_user_id"]] += owes_amount
    result = []
    for uid, balance in balances.items():
        result.append({"user_id": uid, "username": users[uid]["username"], "balance": round(balance, 2), "currency": "USD"})
    return result

