    if not logs:
        return {
            "current_streak": 0,
            "history_graph": "",
            "next_milestone": 1
        }

    today = date.today()
    current_streak = 0
    check_date = today
    log_dates = set()
    for l in logs:
        log_dates.add(l["logged_date"])

    while check_date in log_dates:
