from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Dict
import hashlib
import random
import string

app = FastAPI()

users = {}
tokens = {}
recipes = {}
recipe_id_counter = 1
user_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_current_user(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth header")
    token = authorization[7:]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class Ingredient(BaseModel):
    name: str
    quantity: float
    unit: str

class Recipe(BaseModel):
    name: str
    servings: int
    ingredients: List[Ingredient]
    substitutions: Optional[Dict[str, str]] = None

class RecipeSave(BaseModel):
    original_id: int
    new_servings: int
    substitutions: Optional[Dict[str, str]] = None

@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    token = generate_token()
    tokens[token] = user_id
    return {"user_id": user_id, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/recipes/{recipe_id}")
def get_recipe(recipe_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    return recipes[recipe_id]

@app.post("/recipes")
def create_recipe(recipe: Recipe, authorization: str = Header(...)):
    global recipe_id_counter
    user_id = get_current_user(authorization)
    rid = recipe_id_counter
    recipe_id_counter += 1
    recipes[rid] = {
        "id": rid,
        "user_id": user_id,
        "name": recipe.name,
        "servings": recipe.servings,
        "ingredients": [i.dict() for i in recipe.ingredients],
        "substitutions": recipe.substitutions or {}
    }
    return {"id": rid}

@app.get("/recipes/{recipe_id}/scale")
def scale_recipe(recipe_id: int, target_servings: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    if recipe_id not in recipes:
        raise HTTPException(status_code=404, detail="Recipe not found")
    recipe = recipes[recipe_id]
    scale_factor = target_servings / recipe["servings"]
    scaled = []
    for ing in recipe["ingredients"]:
        new_qty = ing["quantity"] * scale_factor
        # metric conversions for common units
        unit = ing["unit"]
        if unit == "cup" or unit == "cups":
            new_qty = round(new_qty * 236.588, 1)
            unit = "ml"
        elif unit == "tbsp" or unit == "tablespoon" or unit == "tablespoons":
            new_qty = round(new_qty * 14.787, 1)
            unit = "ml"
        elif unit == "tsp" or unit == "teaspoon" or unit == "teaspoons":
            new_qty = round(new_qty * 4.929, 1)
            unit = "ml"
        elif unit == "oz" or unit == "ounce" or unit == "ounces":
            new_qty = round(new_qty * 28.3495, 1)
            unit = "g"
        elif unit == "lb" or unit == "pound" or unit == "pounds":
            new_qty = round(new_qty * 453.592, 1)
            unit = "g"
        elif unit == "fl oz" or unit == "fluid ounce" or unit == "fluid ounces":
            new_qty = round(new_qty * 29.5735, 1)
            unit = "ml"
        scaled.append({"name": ing["name"], "quantity": new_qty, "unit": unit})
    return {
        "original_servings": recipe["servings"],
        "target_servings": target_servings,
        "ingredients": scaled
    }

@app.post("/recipes/save")
def save_modified_recipe(req: RecipeSave, authorization: str = Header(...)):
    global recipe_id_counter
    user_id = get_current_user(authorization)
    if req.original_id not in recipes:
        raise HTTPException(status_code=404, detail="Original recipe not found")
    original = recipes[req.original_id]
    scale_factor = req.new_servings / original["servings"]
    new_ingredients = []
    for ing in original["ingredients"]:
        new_qty = ing["quantity"] * scale_factor
        new_ingredients.append({"name": ing["name"], "quantity": new_qty, "unit": ing["unit"]})
    substitutions = req.substitutions or {}
    # apply substitutions
    for i, ing in enumerate(new_ingredients):
        if ing["name"] in substitutions:
            new_ingredients[i]["name"] = substitutions[ing["name"]]
    rid = recipe_id_counter
    recipe_id_counter += 1
    recipes[rid] = {
        "id": rid,
        "user_id": user_id,
        "name": original["name"] + " (modified)",
        "servings": req.new_servings,
        "ingredients": new_ingredients,
        "substitutions": substitutions,
        "original_id": req.original_id
    }
    return {"id": rid}

