    if login_resp.status_code != 200:
        return False
    token = login_resp.json().get("token")
    if not token:
        return False

    headers = {"Authorization": f"Bearer {token}"}

    # Create wedding
    wedding_resp = session.post(f"{BASE_URL}/weddings", params={"name": "Test Wedding", "date": "2025-06-15"}, headers=headers)
    if wedding_resp.status_code not in (200, 201):
        return False
    wedding_id = wedding_resp.json().get("id")
