    global artist_id_counter
    artist_id = artist_id_counter
    artist_id_counter += 1
    artists[artist_id] = {"id": artist_id, "name": artist.name, "genre": artist.genre, "shows": [], "owner": current_user}
    return artists[artist_id]

@app.get("/artists/{artist_id}")
