from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List, Union
import secrets
import time

app = FastAPI()

users = {}
tokens = {}
surveys = {}
responses = {}
next_user_id = 1
next_survey_id = 1
next_response_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class Question(BaseModel):
    question_text: str
    question_type: str  # "text" or "multiple_choice"
    options: Optional[List[str]] = None

class SurveyCreate(BaseModel):
    title: str
    questions: List[Question]

class SurveyResponse(BaseModel):
    answers: List[Union[str, List[str]]]

def get_user_from_token(authorization: str = Header(...)):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid token")
    token = authorization[7:]
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"user_id": user_id, "message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(32)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/surveys")
def create_survey(survey: SurveyCreate, authorization: str = Header(...)):
    global next_survey_id
    get_user_from_token(authorization)
    survey_id = next_survey_id
    next_survey_id += 1
    surveys[survey_id] = {
        "id": survey_id,
        "title": survey.title,
        "questions": [q.dict() for q in survey.questions]
    }
    responses[survey_id] = []
    return {"survey_id": survey_id}

@app.get("/surveys/{survey_id}")
def get_survey(survey_id: int, authorization: str = Header(...)):
    get_user_from_token(authorization)
    survey = surveys.get(survey_id)
    if not survey:
        raise HTTPException(status_code=404, detail="Survey not found")
    return survey

@app.post("/surveys/{survey_id}/responses")
def submit_response(survey_id: int, response: SurveyResponse, authorization: str = Header(...)):
    get_user_from_token(authorization)
    survey = surveys.get(survey_id)
    if not survey:
        raise HTTPException(status_code=404, detail="Survey not found")
    if len(response.answers) != len(survey["questions"]):
        raise HTTPException(status_code=400, detail="Answer count mismatch")
    global next_response_id
    response_id = next_response_id
    next_response_id += 1
    responses[survey_id].append({
        "response_id": response_id,
        "answers": response.answers,
        "timestamp": time.time()
    })
    return {"response_id": response_id}

@app.get("/surveys/{survey_id}/responses/count")
def get_response_count(survey_id: int, authorization: str = Header(...)):
    get_user_from_token(authorization)
    survey = surveys.get(survey_id)
    if not survey:
        raise HTTPException(status_code=404, detail="Survey not found")
    return {"survey_id": survey_id, "response_count": len(responses.get(survey_id, []))}

