from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import secrets
import threading

app = FastAPI()

users = {}
tokens = {}
alerts = {}
alert_counter = 0
lock = threading.Lock()

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = password
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = username
    return {"token": token}

@app.get("/alerts/{alert_id}")
def get_alert(alert_id: int, authorization: str = Header(None)):
    user = get_current_user(authorization)
    with lock:
        alert = alerts.get(alert_id)
        if not alert:
            raise HTTPException(status_code=404, detail="Alert not found")
        if alert["expires_at"] < datetime.utcnow():
            del alerts[alert_id]
            raise HTTPException(status_code=404, detail="Alert expired")
        return alert

@app.post("/alerts")
def create_alert(region: str, severity: str, message: str, ttl_seconds: int = 3600, authorization: str = Header(None)):
    user = get_current_user(authorization)
    global alert_counter
    with lock:
        alert_counter += 1
        alert_id = alert_counter
        expires_at = datetime.utcnow() + timedelta(seconds=ttl_seconds)
        alerts[alert_id] = {
            "id": alert_id,
            "region": region,
            "severity": severity,
            "message": message,
            "created_by": user,
            "expires_at": expires_at
        }
        return alerts[alert_id]

