    global reservation_id_counter
    rid = reservation_id_counter
    reservation_id_counter += 1
    reservations[rid] = {
        "id": rid,
        "user": user,
        "party_size": req.party_size,
        "time": req.time,
        "special_requests": req.special_requests
    }
    return reservations[rid]

