meeting_id_counter = 1
recurring_rules = {}

def verify_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(401, "Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(401, "Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class Meeting(BaseModel):
    title: str
    start_time: str
    end_time: str
    attendees: List[str] = []
    agenda: str = ""
    room: str = ""
    recurring: Optional[str] = None

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(400, "User exists")
    users[req.username] = {"password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"ok": True}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user or user["password"] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(401, "Bad credentials")
    token = str(uuid.uuid4())
    tokens[token] = req.username
    return {"token": token}

@app.get("/meetings/{meeting_id}")
def get_meeting(meeting_id: int, authorization: str = Header(None)):
    username = verify_token(authorization)
    m = meetings.get(meeting_id)
    if not m:
        raise HTTPException(404, "Not found")
    if m.get("owner") != username:
        raise HTTPException(403, "Access denied")
    return m

@app.post("/meetings")
def create_meeting(meeting: Meeting, authorization: str = Header(None)):
    global meeting_id_counter
    username = verify_token(authorization)
    mid = meeting_id_counter
    meeting_id_counter += 1
    meeting_dict = meeting.dict()
    meeting_dict["id"] = mid
    meeting_dict["owner"] = username
    meetings[mid] = meeting_dict
    if meeting.recurring:
        recurring_rules[mid] = meeting.recurring
    return {"id": mid}

@app.put("/meetings/{meeting_id}")
def update_meeting(meeting_id: int, meeting: Meeting, authorization: str = Header(None)):
    username = verify_token(authorization)
    if meeting_id not in meetings:
        raise HTTPException(404, "Not found")
    if meetings[meeting_id].get("owner") != username:
        raise HTTPException(403, "Access denied")
    meetings[meeting_id].update(meeting.dict())
    if meeting.recurring:
        recurring_rules[meeting_id] = meeting.recurring
    elif meeting_id in recurring_rules:
        del recurring_rules[meeting_id]
    return {"ok": True}

@app.delete("/meetings/{meeting_id}")
def delete_meeting(meeting_id: int, authorization: str = Header(None)):
    username = verify_token(authorization)
    if meeting_id not in meetings:
        raise HTTPException(404, "Not found")
    if meetings[meeting_id].get("owner") != username:
        raise HTTPException(403, "Access denied")
    del meetings[meeting_id]
    recurring_rules.pop(meeting_id, None)
    return {"ok": True}

@app.get("/meetings")
def list_meetings(authorization: str = Header(None)):
    username = verify_token(authorization)
    user_meetings = [m for m in meetings.values() if m.get("owner") == username]
    return user_meetings

@app.get("/sync/calendar")
def sync_calendar(authorization: str = Header(None)):
    username = verify_token(authorization)
    events = []
    for mid, m in meetings.items():
        if m.get("owner") != username:
            continue
        event = {
            "id": mid,
            "title": m["title"],
            "start": m["start_time"],
            "end": m["end_time"],
            "attendees": m["attendees"],
            "room": m["room"],
            "recurring": m.get("recurring")
        }
        events.append(event)
        if m.get("recurring"):
            try:
                count = int(m["recurring"].split(":")[-1])
                start = datetime.fromisoformat(m["start_time"])
                for i in range(1, count):
                    next_start = start + timedelta(days=7*i)
                    next_end = datetime.fromisoformat(m["end_time"]) + timedelta(days=7*i)
                    events.append({
                        "id": f"{mid}-r{i}",
                        "title": m["title"],
                        "start": next_start.isoformat(),
                        "end": next_end.isoformat(),
                        "attendees": m["attendees"],
                        "room": m["room"],
                        "recurring": None
                    })
            except:
                pass
    return events

