from fastapi import FastAPI, HTTPException, Header
from fastapi.responses import Response
import csv
import io
import os
import random
import string

app = FastAPI()

users = {}
tokens = {}
holdings = {}
holdings_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User already exists")
    user_id = len(users) + 1
    users[username] = {"id": user_id, "password": password}
    return {"user_id": user_id, "username": username}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username]["password"] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = users[username]["id"]
    return {"token": token}

@app.get("/holdings/{holding_id}")
def get_holding(holding_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    if holding_id not in holdings:
        raise HTTPException(status_code=404, detail="Holding not found")
    return holdings[holding_id]

@app.post("/holdings")
def create_holding(symbol: str, quantity: int, price: float, authorization: str = Header(None)):
    global holdings_id_counter
    user_id = get_user_from_token(authorization)
    holding = {
        "id": holdings_id_counter,
        "user_id": user_id,
        "symbol": symbol,
        "quantity": quantity,
        "price": price
    }
    holdings[holdings_id_counter] = holding
    holdings_id_counter += 1
    return holding

@app.get("/holdings/{user_id}/export")
def export_holdings(user_id: int, format: str = "csv", authorization: str = Header(None)):
    current_user = get_user_from_token(authorization)
    if current_user != user_id:
        raise HTTPException(status_code=403, detail="Not authorized")

    csv_path = f"/user_data/{user_id}/portfolio.csv"
    if not os.path.exists(csv_path):
        raise HTTPException(status_code=404, detail="Portfolio file not found")

    with open(csv_path, "r") as f:
        content = f.read()

    return Response(content=content, media_type="text/csv", headers={"Content-Disposition": f"attachment; filename=portfolio.csv"})

