def get_user_from_token(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="No auth header")
    token = authorization.replace("Bearer ", "")
    user_id = tokens.get(token)
    if not user_id:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class BookCreate(BaseModel):
    title: str
    author: str

class OrderCreate(BaseModel):
    book_id: int
    user_id: int

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    salt = os.urandom(16).hex()
    hashed = hashlib.sha256((req.password + salt).encode()).hexdigest()
    user_id = len(users) + 1
    users[req.username] = {"id": user_id, "password": hashed, "salt": salt}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    user = users.get(req.username)
    if not user:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    hashed = hashlib.sha256((req.password + user["salt"]).encode()).hexdigest()
    if hashed != user["password"]:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = user["id"]
    return {"token": token}

@app.get("/books/{book_id}")
def get_book(book_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    book = books.get(book_id)
    if not book:
        raise HTTPException(status_code=404, detail="Book not found")
    return book

@app.post("/books")
def create_book(book: BookCreate, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    book_id = len(books) + 1
    books[book_id] = {"id": book_id, "title": book.title, "author": book.author, "user_id": user_id}
    return books[book_id]

@app.get("/orders/{order_id}")
def get_order(order_id: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    order = orders.get(order_id)
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order

@app.post("/orders")
def create_order(order: OrderCreate, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    if order.book_id not in books:
        raise HTTPException(status_code=404, detail="Book not found")
    order_id = len(orders) + 1
    orders[order_id] = {"id": order_id, "book_id": order.book_id, "user_id": order.user_id}
    return orders[order_id]

@app.get("/books/{book_id}/chapters/{chapter_number}")
def get_chapter(book_id: int, chapter_number: int, authorization: str = Header(None)):
    user_id = get_user_from_token(authorization)
    epub_path = Path(f"/ebooks/{book_id}")
    if not epub_path.exists():
        raise HTTPException(status_code=404, detail="Book not found")

    with zipfile.ZipFile(epub_path, 'r') as z:
        # Find the OPF file
        opf_files = [f for f in z.namelist() if f.endswith('.opf')]
        if not opf_files:
            raise HTTPException(status_code=500, detail="Invalid EPUB")

        # Parse OPF to get manifest and spine
        opf_content = z.read(opf_files[0])
        root = ET.fromstring(opf_content)
        ns = {'opf': 'http://www.idpf.org/2007/opf'}

        # Get spine order
        spine = root.find('.//opf:spine', ns)
        if spine is None:
            raise HTTPException(status_code=500, detail="No spine found")

        itemrefs = spine.findall('opf:itemref', ns)

        if chapter_number > len(itemrefs) or chapter_number < 1:
            raise HTTPException(status_code=404, detail="Chapter not found")

        # Get the item id from spine
        itemref = itemrefs[chapter_number - 1]
        idref = itemref.get('idref')

        # Find the file path in manifest
        manifest = root.find('.//opf:manifest', ns)
        items = manifest.findall('opf:item', ns)

        for item in items:
            if item.get('id') == idref:
                file_path = item.get('href')
                break
        else:
            raise HTTPException(status_code=500, detail="Chapter file not found in manifest")

        # Read the chapter content
        content = z.read(file_path)
        return {"chapter_number": chapter_number, "content": content.decode('utf-8')}

