        if q["type"] == "multiple_choice":
            counts[qid] = {opt: 0 for opt in q["options"]}
        elif q["type"] == "text":
            counts[qid] = 0
    for resp in responses.get(survey_id, []):
        for qid, ans in resp["answers"].items():
            if qid in counts:
