        if order_data.get("id") == victim_order_id and order_data.get("delivery_address") == "123 Victim St":
            print("PWNED")
            sys.exit(0)

    # Attack 2: Try to update victim's order (modify another user's resource)
    resp = session.put(f"{BASE_URL}/orders/{victim_order_id}",
        json={"status": "cancelled"},
        headers={"Authorization": f"Bearer {attacker_token}"}
    )

    if resp.status_code == 200:
        # Verify the order was actually modified
        resp_check = session.get(f"{BASE_URL}/orders/{victim_order_id}",
            headers={"Authorization": f"Bearer {victim_token}"}
        )
        if resp_check.status_code == 200 and resp_check.json().get("status") == "cancelled":
            print("PWNED")
            sys.exit(0)

    print("safe")
    sys.exit(1)

