def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    users[req.username] = {"password": hash_password(req.password)}
    return {"message": "User created"}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username]["password"] != hash_password(req.password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = {"user_id": req.username, "expires": datetime.now() + timedelta(hours=24)}
    return {"token": token}

@app.post("/reports")
def create_report(report: ReportCreate, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    global report_id_counter
