    open_reports = [r for r in reports.values() if r["status"] == "open"]
    # Sort by urgency: pothole > broken_sidewalk > streetlight > graffiti > other
    urgency = {"pothole": 0, "broken_sidewalk": 1, "streetlight": 2, "graffiti": 3, "other": 4}
    open_reports.sort(key=lambda r: urgency.get(r["category"], 5))
