    if report_id not in reports:
        raise HTTPException(status_code=404, detail="Report not found")
    if reports[report_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your report")
    report = reports[report_id]
    if update.lat is not None:
        report["lat"] = update.lat
    if update.lon is not None:
        report["lon"] = update.lon
    if update.category is not None:
        if update.category not in categories:
            raise HTTPException(status_code=400, detail=f"Invalid category")
        report["category"] = update.category
    if update.description is not None:
        report["description"] = update.description
    if update.status is not None:
        if update.status not in ("open", "closed", "in_progress"):
            raise HTTPException(status_code=400, detail="Invalid status")
        report["status"] = update.status
    return report

@app.delete("/reports/{report_id}")
def delete_report(report_id: int, authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    if report_id not in reports:
        raise HTTPException(status_code=404, detail="Report not found")
    if reports[report_id]["user_id"] != user_id:
        raise HTTPException(status_code=403, detail="Not your report")
    del reports[report_id]
    return {"message": "Report deleted"}

@app.get("/stats/category")
def stats_category(authorization: str = Header(...)):
    user_id = get_current_user(authorization)
    counts = {}
    for r in reports.values():
        cat = r["category"]
        counts[cat] = counts.get(cat, 0) + 1
    # Ensure all categories appear
    for c in categories:
        if c not in counts:
            counts[c] = 0
    return counts

