from datetime import datetime, timezone
from typing import Optional
import uuid
import time

app = FastAPI()

users = {}
tasks = {}
task_id_counter = 1
tokens = {}

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = password
    return {"message": "created"}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = str(uuid.uuid4())
    tokens[token] = username
    return {"token": token}

@app.post("/tasks")
def create_task(title: str, due_date: str, priority: int = 0, assignee: str = "", authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    global task_id_counter
    tid = task_id_counter
    task_id_counter += 1
    tasks[tid] = {
        "id": tid,
        "title": title,
        "due_date": due_date,
        "priority": priority,
        "assignee": assignee,
        "status": "todo",
        "created_by": user,
        "timestamps": {
            "todo": datetime.now(timezone.utc).isoformat(),
            "doing": None,
            "done": None
        }
    }
    return tasks[tid]

@app.get("/tasks")
def list_tasks(authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    sorted_tasks = sorted(tasks.values(), key=lambda t: (t["priority"], t["due_date"]), reverse=True)
    return sorted_tasks

@app.put("/tasks/{task_id}/status")
def update_task_status(task_id: int, status: str, authorization: Optional[str] = Header(None)):
    user = get_current_user(authorization)
    if task_id not in tasks:
        raise HTTPException(status_code=404, detail="Task not found")
    if status not in ("todo", "doing", "done"):
        raise HTTPException(status_code=400, detail="Invalid status")
    tasks[task_id]["status"] = status
    tasks[task_id]["timestamps"][status] = datetime.now(timezone.utc).isoformat()
    return tasks[task_id]

