import secrets
from fastapi import FastAPI, HTTPException, Header, Request
from fastapi.responses import RedirectResponse
from pydantic import BaseModel

app = FastAPI()

users = {}
tokens = {}
urls = {}
clicks = {}
id_counter = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class ShortenRequest(BaseModel):
    url: str

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(401, "Missing Authorization header")
    token = authorization.replace("Bearer ", "")
    user = tokens.get(token)
    if not user:
        raise HTTPException(401, "Invalid token")
    return user

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(400, "User already exists")
    users[req.username] = req.password
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    password = users.get(req.username)
    if not password or password != req.password:
        raise HTTPException(401, "Invalid credentials")
    token = secrets.token_hex(16)
    tokens[token] = req.username
    return {"token": token}

@app.post("/shorten")
def shorten(req: ShortenRequest, authorization: str = Header(None)):
    get_current_user(authorization)
    global id_counter
    code = str(id_counter)
    id_counter += 1
    urls[code] = req.url
    clicks[code] = []
    return {"short_code": code}

@app.get("/{code}")
async def redirect(code: str, request: Request):
    long_url = urls.get(code)
    if not long_url:
        raise HTTPException(404, "Not found")
    referrer = request.headers.get("referer", "direct")
    user_agent = request.headers.get("user-agent", "unknown")
    clicks[code].append({"referrer": referrer, "user_agent": user_agent})
    return RedirectResponse(url=long_url)

@app.get("/stats/{code}")
def stats(code: str, authorization: str = Header(None)):
    get_current_user(authorization)
    if code not in urls:
        raise HTTPException(404, "Not found")
    total_clicks = len(clicks[code])
    referrers = {}
    for click in clicks[code]:
        ref = click["referrer"]
        referrers[ref] = referrers.get(ref, 0) + 1
    top_referrers = sorted(referrers.items(), key=lambda x: -x[1])[:5]
    return {"total_clicks": total_clicks, "top_referrers": top_referrers}

