    for uid, u in users.items():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username exists")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = generate_token()
            tokens[token] = uid
            return {"token": token, "user_id": uid}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/profile")
def create_profile(req: ProfileRequest, authorization: str = Header(None)):
    global next_profile_id
    user_id = get_user_from_token(authorization)
    profile_id = next_profile_id
    next_profile_id += 1
    profiles[profile_id] = {
        "id": profile_id,
        "user_id": user_id,
        "skills_offered": req.skills_offered,
        "skills_wanted": req.skills_wanted
    }
    return profiles[profile_id]

