    user_id = get_user_from_token(authorization)
    user_profile = None
    for pid, p in profiles.items():
        if p["user_id"] == user_id:
            user_profile = p
            break
    if not user_profile:
        raise HTTPException(status_code=400, detail="Create a profile first")

