from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional, List
import time
import secrets

app = FastAPI()

users = {}
tokens = {}
jobs = {}
saves = {}
job_views = {}
next_user_id = 1
next_job_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class JobCreate(BaseModel):
    title: str
    salary_range: str
    skill: str
    remote: bool = False
    employment_type: str

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password}
    return {"user_id": user_id}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/jobs")
def create_job(job: JobCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_job_id
    job_id = next_job_id
    next_job_id += 1
    jobs[job_id] = {
        "id": job_id,
        "title": job.title,
        "salary_range": job.salary_range,
        "skill": job.skill,
        "remote": job.remote,
        "employment_type": job.employment_type
    }
    saves[job_id] = 0
    job_views[job_id] = None
    return {"id": job_id}

@app.get("/jobs/{job_id}")
def get_job(job_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if job_id not in jobs:
        raise HTTPException(status_code=404, detail="Job not found")
    job_views[job_id] = int(time.time())
    return jobs[job_id]

@app.get("/jobs")
def search_jobs(
    skill: Optional[str] = None,
    remote: Optional[bool] = None,
    employment_type: Optional[str] = None,
    authorization: Optional[str] = Header(None)
):
    user_id = get_current_user(authorization)
    results = []
    for jid, job in jobs.items():
        if skill and job["skill"] != skill:
            continue
        if remote is not None and job["remote"] != remote:
            continue
        if employment_type and job["employment_type"] != employment_type:
            continue
        results.append({
            "title": job["title"],
            "salary_range": job["salary_range"],
            "save_count": saves.get(jid, 0),
            "last_viewed": job_views.get(jid)
        })
    if results:
        job_views[jid] = int(time.time())
    return {"results": results, "query_timestamp": int(time.time())}

