    global next_user_id
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"username": req.username, "password": req.password, "id": user_id}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = uid
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.get("/parts/{part_id}")
def get_part(part_id: int, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    if part_id not in parts:
        raise HTTPException(status_code=404, detail="Part not found")
    return parts[part_id]

@app.post("/parts")
def create_part(part: PartCreate, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    global next_part_id
    part_id = next_part_id
    next_part_id += 1
    parts[part_id] = {
        "id": part_id,
        "part_number": part.part_number,
        "quantity": part.quantity,
        "reorder_threshold": part.reorder_threshold,
        "supplier_lead_time": part.supplier_lead_time,
        "location": part.location
    }
    return parts[part_id]

