def list_parts(location: Optional[str] = None, low_stock: Optional[bool] = None, authorization: Optional[str] = Header(None)):
    user_id = get_current_user(authorization)
    result = []
    for pid, p in parts.items():
        if location and p.get("location") != location:
            continue
        if low_stock and p["quantity"] > p["reorder_threshold"]:
            continue
        result.append(p)
    return result

@app.post("/restock")
def restock(req: RestockRequest, authorization: Optional[str] = Header(None)):
