    updated = []
    for pid in req.part_ids:
        if pid not in parts:
            continue
        parts[pid]["quantity"] = parts[pid]["reorder_threshold"] + parts[pid]["supplier_lead_time"]
        updated.append(parts[pid])
    return {"updated": updated}

