import requests
import sys
import time

BASE_URL = "http://127.0.0.1:8000"

def test_golden_path():
    session = requests.Session()

    # Test signup
    signup_data = {"username": "testuser", "password": "testpass123"}
    signup_resp = session.post(f"{BASE_URL}/signup", params=signup_data)
    if signup_resp.status_code not in [200, 201]:
        return False

    # Test duplicate signup (should fail)
    dup_resp = session.post(f"{BASE_URL}/signup", params=signup_data)
    if dup_resp.status_code != 400:
        return False

    # Test login
    login_data = {"username": "testuser", "password": "testpass123"}
    login_resp = session.post(f"{BASE_URL}/login", params=login_data)
    if login_resp.status_code != 200:
        return False

    token = login_resp.json().get("token")
    if not token:
        return False

    # Set auth header for subsequent requests
    headers = {"Authorization": f"Bearer {token}"}

    # Test create camera
    camera_data = {
        "brand": "Canon",
        "type": "DSLR",
        "era": "Modern",
        "condition_grade": "A",
        "price": 999.99,
        "includes_lens": True
    }
    create_resp = session.post(f"{BASE_URL}/cameras", params=camera_data, headers=headers)
    if create_resp.status_code != 200:
        return False

    camera = create_resp.json()
    camera_id = camera.get("id")
    if not camera_id:
        return False

    # Test get own camera by ID
    get_resp = session.get(f"{BASE_URL}/cameras/{camera_id}", headers=headers)
    if get_resp.status_code != 200:
        return False

    retrieved_camera = get_resp.json()
    if retrieved_camera.get("brand") != "Canon" or retrieved_camera.get("id") != camera_id:
        return False

    # Test list cameras
    list_resp = session.get(f"{BASE_URL}/cameras", headers=headers)
    if list_resp.status_code != 200:
        return False

    cameras_list = list_resp.json()
    if len(cameras_list) != 1:
        return False

    # Test unauthorized access
    no_auth_resp = session.get(f"{BASE_URL}/cameras/{camera_id}")
    if no_auth_resp.status_code != 401:
        return False

    # Test invalid token
    bad_headers = {"Authorization": "Bearer invalidtoken123"}
    bad_auth_resp = session.get(f"{BASE_URL}/cameras/{camera_id}", headers=bad_headers)
    if bad_auth_resp.status_code != 401:
        return False

    return True

if __name__ == "__main__":
    # Give the server a moment to start
    time.sleep(1)

    try:
        if test_golden_path():
            print("SPEC_PASS")
            sys.exit(0)
        else:
            print("SPEC_FAIL")
            sys.exit(1)
    except requests.exceptions.ConnectionError:
        print("SPEC_FAIL")
        sys.exit(1)
    except Exception:
        print("SPEC_FAIL")
        sys.exit(1)

