from fastapi import FastAPI, HTTPException, Header
from datetime import datetime, timedelta
import hashlib
import random
import string

app = FastAPI()

users = {}
tokens = {}
alerts = {}
alert_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

def hash_password(password):
    return hashlib.sha256(password.encode()).hexdigest()

def get_current_user(authorization: str = Header(None)):
    if not authorization or not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Invalid auth")
    token = authorization.split(" ")[1]
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.post("/signup")
def signup(username: str, password: str):
    if username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[username] = hash_password(password)
    token = generate_token()
    tokens[token] = username
    return {"token": token}

@app.post("/login")
def login(username: str, password: str):
    if username not in users or users[username] != hash_password(password):
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = username
    return {"token": token}

@app.get("/alerts/{alert_id}")
def get_alert(alert_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    alert = alerts.get(alert_id)
    if not alert:
        raise HTTPException(status_code=404, detail="Alert not found")
    if alert["expires_at"] < datetime.utcnow():
        alerts[alert_id]["archived"] = True
        raise HTTPException(status_code=404, detail="Alert expired and archived")
    return alert

@app.post("/alerts")
def create_alert(region_id: int, severity: str, message: str, expires_in_minutes: int = 60, authorization: str = Header(None)):
    get_current_user(authorization)
    global alert_id_counter
    alert = {
        "id": alert_id_counter,
        "region_id": region_id,
        "severity": severity,
        "message": message,
        "created_at": datetime.utcnow(),
        "expires_at": datetime.utcnow() + timedelta(minutes=expires_in_minutes),
        "archived": False
    }
    alerts[alert_id_counter] = alert
    alert_id_counter += 1
    return alert

@app.get("/alerts/region/{region_id}")
def get_alerts_by_region(region_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    now = datetime.utcnow()
    active = []
    for alert in alerts.values():
        if alert["region_id"] == region_id and not alert["archived"] and alert["expires_at"] > now:
            active.append(alert)
        elif alert["region_id"] == region_id and alert["expires_at"] <= now:
            alert["archived"] = True
    return active

