        raise HTTPException(status_code=404, detail="Seating chart not found")
    chart = seating_charts[chart_id]
    # Check ownership via associated guests/tables
    chart_owner = None
    for table_id in chart.get("table_assignments", {}):
        table = tables.get(table_id)
        if table and "owner_id" in table:
            if chart_owner is None:
                chart_owner = table["owner_id"]
            elif chart_owner != table["owner_id"]:
                raise HTTPException(status_code=403, detail="Access denied")
        else:
            raise HTTPException(status_code=403, detail="Access denied")
    if chart_owner != user_id:
        raise HTTPException(status_code=403, detail="Access denied")
    return chart

@app.post("/seating_charts")
