        for guest_id in chart.table_assignments[table_id]:
            if guest_id not in guests:
                raise HTTPException(status_code=404, detail=f"Guest {guest_id} not found")
            if guests[guest_id].get("owner_id") != user_id:
                raise HTTPException(status_code=403, detail="Access denied to guest")
    global next_chart_id
    chart_id = next_chart_id
    next_chart_id += 1
    seating_charts[chart_id] = {
        "id": chart_id, 
        "name": chart.name, 
        "table_assignments": chart.table_assignments
    }
    return seating_charts[chart_id]

