def signup(req: SignupRequest):
    global next_user_id
    if req.username in users:
        raise HTTPException(status_code=400, detail="Username already exists")
    user_id = next_user_id
    next_user_id += 1
    users[req.username] = {"id": user_id, "password": hashlib.sha256(req.password.encode()).hexdigest()}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    if users[req.username]["password"] != hashlib.sha256(req.password.encode()).hexdigest():
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = secrets.token_hex(32)
    tokens[token] = users[req.username]["id"]
    return {"token": token}

