def create_ingredient(ing: IngredientCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global next_ingredient_id
    ing_id = next_ingredient_id
    next_ingredient_id += 1
    ingredients[ing_id] = {"id": ing_id, "name": ing.name, "category": ing.category}
    return ingredients[ing_id]

@app.get("/ingredients/{ingredient_id}")
def get_ingredient(ingredient_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if ingredient_id not in ingredients:
        raise HTTPException(status_code=404, detail="Ingredient not found")
    return ingredients[ingredient_id]

@app.post("/recipes")
def create_recipe(rec: RecipeCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if rec.primary_ingredient_id not in ingredients:
        raise HTTPException(status_code=400, detail="Primary ingredient not found")
    global next_recipe_id
    rec_id = next_recipe_id
    next_recipe_id += 1
    recipes[rec_id] = {"id": rec_id, "name": rec.name, "primary_ingredient_id": rec.primary_ingredient_id, "instructions": rec.instructions}
