    get_current_user(authorization)
    if sub.ingredient_id not in ingredients:
        raise HTTPException(status_code=400, detail="Ingredient not found")
    if sub.substitute_ingredient_id not in ingredients:
        raise HTTPException(status_code=400, detail="Substitute ingredient not found")
    global next_substitution_id
    sub_id = next_substitution_id
    next_substitution_id += 1
    substitutions[sub_id] = {"id": sub_id, "ingredient_id": sub.ingredient_id, "substitute_ingredient_id": sub.substitute_ingredient_id}
    return substitutions[sub_id]

@app.get("/substitutions/{substitution_id}")
def get_substitution(substitution_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if substitution_id not in substitutions:
        raise HTTPException(status_code=404, detail="Substitution not found")
    return substitutions[substitution_id]

