    get_current_user(authorization)
    if rate.substitution_id not in substitutions:
        raise HTTPException(status_code=400, detail="Substitution not found")
    global next_rating_id
    rate_id = next_rating_id
    next_rating_id += 1
    compatibility_ratings[rate_id] = {"id": rate_id, "substitution_id": rate.substitution_id, "rating": rate.rating}
    return compatibility_ratings[rate_id]

@app.get("/compatibility-ratings/{rating_id}")
def get_compatibility_rating(rating_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if rating_id not in compatibility_ratings:
        raise HTTPException(status_code=404, detail="Rating not found")
    return compatibility_ratings[rating_id]

@app.get("/ingredients/{ingredient_id}/substitutions")
def get_substitutions_for_ingredient(ingredient_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    result = []
    for sub in substitutions.values():
        if sub["ingredient_id"] == ingredient_id:
            result.append(sub)
    return result

