from fastapi import FastAPI, HTTPException, Header
from pydantic import BaseModel
from typing import Optional
import hashlib
import secrets

app = FastAPI()

# In-memory stores
users = {}
tokens = {}
drugs = {}
interactions = {}
prescriptions = {}
prescription_drugs = {}

# ID counters
user_id_counter = 1
drug_id_counter = 1
interaction_id_counter = 1
prescription_id_counter = 1
prescription_drug_id_counter = 1

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def generate_token() -> str:
    return secrets.token_hex(32)

def get_current_user(authorization: Optional[str] = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing authorization header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class DrugCreate(BaseModel):
    name: str
    description: str = ""

class InteractionCreate(BaseModel):
    drug1_id: int
    drug2_id: int
    severity: str
    description: str = ""

class PrescriptionCreate(BaseModel):
    patient_name: str
    drug_ids: list[int]

# Auth endpoints
@app.post("/signup")
def signup(req: SignupRequest):
    global user_id_counter
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username already exists")
    user_id = user_id_counter
    user_id_counter += 1
    users[user_id] = {
        "id": user_id,
        "username": req.username,
        "password_hash": hash_password(req.password)
    }
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password_hash"] == hash_password(req.password):
            token = generate_token()
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

# Drug endpoints
@app.get("/drug/{drug_id}")
def get_drug(drug_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if drug_id not in drugs:
        raise HTTPException(status_code=404, detail="Drug not found")
    return drugs[drug_id]

@app.post("/drug")
def create_drug(drug: DrugCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global drug_id_counter
    drug_id = drug_id_counter
    drug_id_counter += 1
    drugs[drug_id] = {
        "id": drug_id,
        "name": drug.name,
        "description": drug.description
    }
    return drugs[drug_id]

# Interaction endpoints
@app.get("/interaction/{interaction_id}")
def get_interaction(interaction_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if interaction_id not in interactions:
        raise HTTPException(status_code=404, detail="Interaction not found")
    return interactions[interaction_id]

@app.post("/interaction")
def create_interaction(interaction: InteractionCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global interaction_id_counter
    if interaction.drug1_id not in drugs or interaction.drug2_id not in drugs:
        raise HTTPException(status_code=400, detail="One or both drugs not found")
    interaction_id = interaction_id_counter
    interaction_id_counter += 1
    interactions[interaction_id] = {
        "id": interaction_id,
        "drug1_id": interaction.drug1_id,
        "drug2_id": interaction.drug2_id,
        "severity": interaction.severity,
        "description": interaction.description
    }
    return interactions[interaction_id]

# Prescription endpoints
@app.get("/prescription/{prescription_id}")
def get_prescription(prescription_id: int, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    if prescription_id not in prescriptions:
        raise HTTPException(status_code=404, detail="Prescription not found")
    return prescriptions[prescription_id]

@app.post("/prescription")
def create_prescription(prescription: PrescriptionCreate, authorization: Optional[str] = Header(None)):
    get_current_user(authorization)
    global prescription_id_counter, prescription_drug_id_counter

    # Validate all drug IDs exist
    for drug_id in prescription.drug_ids:
        if drug_id not in drugs:
            raise HTTPException(status_code=400, detail=f"Drug {drug_id} not found")

    prescription_id = prescription_id_counter
    prescription_id_counter += 1

    prescriptions[prescription_id] = {
        "id": prescription_id,
        "patient_name": prescription.patient_name,
        "drug_ids": prescription.drug_ids
    }

    # Check for interactions between all drug pairs
    conflicts = []
    for i in range(len(prescription.drug_ids)):
        for j in range(i+1, len(prescription.drug_ids)):
            d1 = prescription.drug_ids[i]
            d2 = prescription.drug_ids[j]
            for inter in interactions.values():
