    tokens[uid] = token
    ratings[uid] = []
    return {"user_id": uid, "token": token}

@app.post("/login")
def login(req: LoginRequest):
    for uid, u in users.items():
        if u["username"] == req.username:
            token = tokens.get(uid)
            if not token:
                token = secrets.token_hex(16)
                tokens[uid] = token
            return {"token": token}
    raise HTTPException(status_code=401, detail="User not found")

@app.post("/ratings")
def create_rating(req: RatingRequest, authorization: str = Header(...)):
    current_user = get_current_user(authorization)
    global next_rating_id
    rid = next_rating_id
    next_rating_id += 1
    rating_entry = {"rating_id": rid, "user_id": req.user_id, "score": req.score, "created_at": time.time()}
    if req.user_id not in ratings:
        ratings[req.user_id] = []
    ratings[req.user_id].append(rating_entry)
    return rating_entry

@app.get("/ratings/{rating_id}")
def get_rating(rating_id: int, authorization: str = Header(...)):
    current_user = get_current_user(authorization)
    for uid, rating_list in ratings.items():
        for r in rating_list:
            if r["rating_id"] == rating_id:
                return r
    raise HTTPException(status_code=404, detail="Rating not found")

