from pydantic import BaseModel
from typing import Optional
import secrets

app = FastAPI()

users = {}
tokens = {}
proposals = {}
votes = {}
next_user_id = 1
next_proposal_id = 1
next_vote_id = 1

class SignupRequest(BaseModel):
    username: str
    password: str
    track: Optional[str] = None

class LoginRequest(BaseModel):
    username: str
    password: str

class ProposalCreate(BaseModel):
    title: str
    abstract: str
    track: str
    speaker: str

class VoteCreate(BaseModel):
    proposal_id: int
    score: int

def get_current_user(token: str = Header(...)):
    user_id = tokens.get(token)
    if user_id is None:
        raise HTTPException(status_code=401, detail="Invalid token")
    return user_id

@app.post("/signup")
def signup(req: SignupRequest):
    global next_user_id
    for u in users.values():
        if u["username"] == req.username:
            raise HTTPException(status_code=400, detail="Username taken")
    user_id = next_user_id
    next_user_id += 1
    users[user_id] = {"id": user_id, "username": req.username, "password": req.password, "track": req.track}
    return {"id": user_id, "username": req.username}

@app.post("/login")
def login(req: LoginRequest):
    for u in users.values():
        if u["username"] == req.username and u["password"] == req.password:
            token = secrets.token_hex(16)
            tokens[token] = u["id"]
            return {"token": token}
    raise HTTPException(status_code=401, detail="Invalid credentials")

@app.post("/proposals")
def create_proposal(req: ProposalCreate, token: str = Header(...)):
    global next_proposal_id
    user_id = get_current_user(token)
    pid = next_proposal_id
    next_proposal_id += 1
    proposals[pid] = {"id": pid, "title": req.title, "abstract": req.abstract, "track": req.track, "speaker": req.speaker, "user_id": user_id}
    return proposals[pid]

@app.get("/proposals/{proposal_id}")
def get_proposal(proposal_id: int, token: str = Header(...)):
    get_current_user(token)
    p = proposals.get(proposal_id)
    if not p:
        raise HTTPException(status_code=404, detail="Proposal not found")
    return p

@app.post("/votes")
def create_vote(req: VoteCreate, token: str = Header(...)):
    global next_vote_id
    user_id = get_current_user(token)
    if req.proposal_id not in proposals:
        raise HTTPException(status_code=404, detail="Proposal not found")
    if req.score < 1 or req.score > 10:
        raise HTTPException(status_code=400, detail="Score must be between 1 and 10")
    vid = next_vote_id
    next_vote_id += 1
    votes[vid] = {"id": vid, "proposal_id": req.proposal_id, "score": req.score, "user_id": user_id}
    return votes[vid]

@app.get("/votes/{vote_id}")
def get_vote(vote_id: int, token: str = Header(...)):
    get_current_user(token)
    v = votes.get(vote_id)
    if not v:
        raise HTTPException(status_code=404, detail="Vote not found")
    return v

@app.get("/tally/{track}")
def tally_track(track: str, token: str = Header(...)):
    get_current_user(token)
    track_proposals = [p for p in proposals.values() if p["track"] == track]
    result = {}
    for p in track_proposals:
        total = 0
        count = 0
        for v in votes.values():
            if v["proposal_id"] == p["id"]:
                total += v["score"]
                count += 1
        avg = total / count if count > 0 else 0
        result[p["id"]] = {"title": p["title"], "total_score": total, "vote_count": count, "average": avg}
    return result

