from pydantic import BaseModel
from typing import Optional, List
import random
import string

app = FastAPI()

users = {}
tokens = {}
hotels = {}
hotel_id_counter = 1

def generate_token():
    return ''.join(random.choices(string.ascii_letters + string.digits, k=32))

class SignupRequest(BaseModel):
    username: str
    password: str

class LoginRequest(BaseModel):
    username: str
    password: str

class HotelCreate(BaseModel):
    name: str
    star_rating: int
    city: str
    amenities: List[str] = []
    price_per_night: float

@app.post("/signup")
def signup(req: SignupRequest):
    if req.username in users:
        raise HTTPException(status_code=400, detail="User exists")
    users[req.username] = req.password
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

@app.post("/login")
def login(req: LoginRequest):
    if req.username not in users or users[req.username] != req.password:
        raise HTTPException(status_code=401, detail="Invalid credentials")
    token = generate_token()
    tokens[token] = req.username
    return {"token": token}

def get_current_user(authorization: str = Header(None)):
    if not authorization:
        raise HTTPException(status_code=401, detail="Missing auth header")
    token = authorization.replace("Bearer ", "")
    if token not in tokens:
        raise HTTPException(status_code=401, detail="Invalid token")
    return tokens[token]

@app.get("/hotels/{hotel_id}")
def get_hotel(hotel_id: int, authorization: str = Header(None)):
    get_current_user(authorization)
    if hotel_id not in hotels:
        raise HTTPException(status_code=404, detail="Hotel not found")
    return hotels[hotel_id]

@app.post("/hotels")
def create_hotel(hotel: HotelCreate, authorization: str = Header(None)):
    get_current_user(authorization)
    global hotel_id_counter
    hotel_id = hotel_id_counter
    hotel_id_counter += 1
    hotels[hotel_id] = {
        "id": hotel_id,
        "name": hotel.name,
        "star_rating": hotel.star_rating,
        "city": hotel.city,
        "amenities": hotel.amenities,
        "price_per_night": hotel.price_per_night
    }
    return hotels[hotel_id]

@app.get("/hotels")
def list_hotels(
    city: Optional[str] = None,
    amenities: Optional[str] = None,
    min_price: Optional[float] = None,
    max_price: Optional[float] = None,
    authorization: str = Header(None)
):
    get_current_user(authorization)
    results = []
    for h in hotels.values():
        if city and h["city"].lower() != city.lower():
            continue
        if amenities:
            req_amenities = [a.strip().lower() for a in amenities.split(",")]
            hotel_amenities = [a.lower() for a in h["amenities"]]
            if not all(a in hotel_amenities for a in req_amenities):
                continue
        if min_price is not None and h["price_per_night"] < min_price:
            continue
        if max_price is not None and h["price_per_night"] > max_price:
            continue
        results.append(h)
    return results

